part of 'ko_table.dart';

/// key = 中文原文（与源码逐字一致），value = 韩语。
///
/// 由 install/i18n/gen-tables.mjs 生成，可手改（改完跑 check-tables 复核）。
const Map<String, String> kKoTable = <String, String>{
  '\n请帮我创建一个 DSH 技能，直接落盘，不要只给示例。\n\n要求：\n1. 用你的 write 工具创建文件：{0}/<技能名>/SKILL.md\n2. <技能名> 必须匹配 ^[a-z0-9]+(?:-[a-z0-9]+)\$（小写字母/数字/连字符），这是 DSH 的技能名规范。\n3. 文件内容严格是下面这个格式（frontmatter 只有 name 与 description）：\n---\nname: <技能名>\ndescription: "<一句话说明什么时候该用这个技能>"\n---\n\n<技能正文：可执行的步骤、注意事项、输出格式；Markdown>\n4. 技能主题由你根据下面的描述来定，正文要具体到能照着做，不要写空话。\n5. 写完后告诉我：技能名、文件绝对路径、以及一句话说明它解决什么问题。\n\n我想让这个技能做的事：\n（在这里把你的需求写清楚，例如：把每天的聊天记录整理成一份 Markdown 日报，带待办清单）\n': '\nDSH 스킬을 만들어 주세요. 파일로 바로 저장하고, 예시만 보여주지는 마세요.\n\n요구 사항:\n1. write 도구로 파일 생성: {0}/<스킬 이름>/SKILL.md\n2. <스킬 이름>은 ^[a-z0-9]+(?:-[a-z0-9]+)\\\$(소문자/숫자/하이픈)와 일치해야 합니다. 이것이 DSH 스킬 이름 규칙입니다.\n3. 파일 내용은 아래 형식을 정확히 따라야 합니다(frontmatter에는 name과 description만):\n---\nname: <스킬 이름>\ndescription: "<이 스킬을 언제 쓰면 되는지 한 문장으로>"\n---\n\n<스킬 본문: 실행 가능한 단계, 주의 사항, 출력 형식; Markdown>\n4. 스킬 주제는 아래 설명을 보고 정하고, 본문은 그대로 따라 할 수 있을 만큼 구체적으로. 빈말은 쓰지 마세요.\n5. 끝나면 알려주세요: 스킬 이름, 파일 절대 경로, 그리고 이게 어떤 문제를 해결하는지 한 문장.\n\n이 스킬로 하고 싶은 일:\n(여기에 요구 사항을 구체적으로 적어 주세요. 예: 매일의 채팅 기록을 할 일 목록이 포함된 Markdown 일일 보고서로 정리)\n',
  '  - {0}（{1} 个成员）': '  - {0} ({1}명)',
  '  - {0}（{1}）· 模型 {2} 个 · Key：{3}': '  - {0} ({1}) · 모델 {2}개 · Key: {3}',
  '  （没有配置任何厂家）': '  (설정된 공급자가 없음)',
  ' · 内置': ' · 내장',
  ' · 内置（免费档）': ' · 내장(무료 등급)',
  ' · 含本次运行': ' · 이번 실행 포함',
  '**在图上直接选**：按在空白处拖动 = 拉出一个新框（放哪、多大都随你）；按在框里拖动 = 整块移动；拖**四个角**的圆点 = 改大小。下面这几个只是"一键放好"的快捷起点。': '**이미지에서 바로 선택하세요**: 빈 곳을 드래그하면 새 박스가 그려지고(위치·크기 자유), 박스 안을 드래그하면 통째로 이동하며, **네 모서리** 점을 드래그하면 크기가 바뀝니다. 아래 항목은 한 번에 놓는 출발점일 뿐입니다.',
  '**排版不用你操心**：你只说讲什么、想做成哪种样子，脚本自己算字号、分栏与分页（放不下会缩字号、再放不下会拆成「（续）」页）。产物是真正的 .pptx —— 原生形状，在 WPS / Office 里能改颜色、改字。下面是几个起点，点一个就开始（会话里再改成你要的）。': '**배치는 신경 쓰지 않으셔도 됩니다**: 무엇을 말할지, 어떤 모양으로 만들지만 알려 주세요. 글자 크기·단 구성·쪽 나눔은 스크립트가 계산합니다(안 들어가면 글자를 줄이고, 그래도 안 되면 「(계속)」 페이지로 나눕니다). 결과물은 진짜 .pptx(네이티브 도형)라 WPS / Office에서 색과 글자를 고칠 수 있습니다. 아래 시작점을 골라 시작하세요(세션에서 수정 가능).',
  '**这条通道不需要你填任何 Key** —— 它就是给"不想配 Key"准备的：打开后模型列表里会出现「免费模型（无需 Key）」这一组，直接用就行。\n\n内容由 [pollinations.ai](https://pollinations.ai) 的**匿名层**提供（它自己就是这么开放的：不用注册、不用 Key），不是我们绕出来的。': '**이 경로는 Key 입력이 전혀 필요 없습니다** — Key를 설정하고 싶지 않은 분을 위한 기능입니다. 켜면 모델 목록에 「무료 모델(Key 불필요)」 그룹이 나타나 바로 쓸 수 있습니다.\n\n모델은 [pollinations.ai](https://pollinations.ai)의 **익명 레이어**에서 제공됩니다(해당 서비스가 "가입 불필요, Key 불필요"로 공개한 방식이며, 저희가 제한을 우회한 것이 아닙니다).',
  '+ 新建轮换池': '+ 로테이션 풀 만들기',
  '321 名专家 / 22 个分区（来自专家库）。开启某位专家后，他的摘要会写进 AGENTS.md，DSH 会在每个新会话的第一个请求前注入模型上下文 ——**会占上下文**，所以别一次开太多。': '전문가 321명 / 22개 분과(전문가 라이브러리). 전문가를 켜면 요약이 AGENTS.md에 기록되고 DSH가 새 세션의 첫 요청 전에 모델 컨텍스트에 주입합니다 —— **컨텍스트를 소비**하므로 한 번에 너무 많이 켜지 마세요.',
  '44 种图型（架构 / 流程 / 时序 / ER / 时间线 / 桑基 / 甘特…）。产物是**自包含的网页**（HTML + 内联 SVG），画完能在「资料库」里直接打开看。下面点一个例子就开始（会话里再改成你要的）。': '44종 다이어그램(아키텍처 / 프로세스 / 시퀀스 / ER / 타임라인 / 생키 / 간트…). 결과물은 **자체 완결 웹 페이지**(HTML + 인라인 SVG)이며 그린 뒤 「자료실」에서 바로 열 수 있습니다. 아래 예시를 눌러 시작하세요(세션에서 수정 가능).',
  '6 位数字，120 秒内有效': '6자리 숫자, 120초 동안 유효',
  'AA:BB:CC:…（电脑端启动桥时打印）': 'AA:BB:CC:…(컴퓨터에서 브리지 시작 시 출력)',
  'ACP 的 session/resume 只恢复会话本身（模型上下文仍然在），但 DSH 要求工作目录与建会话时**完全一致**才允许恢复。': 'ACP의 session/resume은 세션 자체만 복원합니다(모델 컨텍스트는 그대로 남아 있습니다). 다만 DSH는 세션을 만들 때와 작업 디렉터리가 **완전히 같아야** 복원을 허용합니다.',
  'AI 能力': 'AI 기능',
  'AI 角色（实验）': 'AI 역할(실험)',
  'API Key 不能为空': 'API 키를 입력해야 합니다',
  'API Key 不能为空 —— 「测试并保存」要真打一次请求。': 'API 키를 입력해야 합니다 — "테스트 후 저장"은 실제로 요청을 보냅니다.',
  'API Key 已自动脱敏（会变成 ***已脱敏***），**不会**包含你的 Key。': 'API 키는 자동으로 마스킹됩니다(***마스킹됨*** 로 표시). 당신의 Key는 **포함되지 않습니다**.',
  'API Key 无效或没填。请回设置页检查 Key，并确认它属于当前选中的服务商。': 'API 키가 유효하지 않거나 비어 있습니다. 설정 화면으로 돌아가 Key를 확인하고, 현재 선택한 공급자의 키가 맞는지 확인하세요.',
  'API Key（可以直接在这里填）': 'API Key(여기에 바로 입력할 수 있습니다)',
  'APP界面设计台': '앱 UI 디자인 스튜디오',
  'APP界面设计台打不开：{0}': '앱 UI 디자인 스튜디오를 열 수 없습니다: {0}',
  'Agent 请求执行操作': 'Agent가 작업 실행을 요청합니다',
  'Agnes API Key（在 platform.agnes-ai.cn 创建，sk- 开头）': 'Agnes API 키(platform.agnes-ai.cn에서 생성, sk-로 시작)',
  'Agnes 官方当前把这几个模型标为免费：文本 agnes-3.0-flash、图像 agnes-image-2.5-flash（官方原文：所有输出分辨率档位与输入参考图片当前均免费）、视频 agnes-video-2.5-flash（官方原文：原价 ¥0.15/秒，现价 ¥0/秒）。这是**限时/当前**的优惠价，官方注明"免费政策如有调整，以平台最新公告为准"，不要当成永久免费无限量。': 'Agnes는 현재 이 모델들을 무료로 표시하고 있습니다: 텍스트 agnes-3.0-flash, 이미지 agnes-image-2.5-flash(공식 문구: 모든 출력 해상도 등급과 입력 참조 이미지가 현재 무료), 비디오 agnes-video-2.5-flash(공식 문구: 원래 ¥0.15/초, 현재 ¥0/초). 이는 **기간 한정/현재** 할인가입니다. 공식은 "무료 정책이 바뀌면 플랫폼의 최신 공지를 따릅니다"라고 명시하고 있으니, 영구 무료·무제한으로 생각하지 마세요.',
  'Agnes 官方端点：文本、图像、视频共用一个 Key（图形/视频的端口是内置的，不用你配），官方当前把这几个模型标为免费（限时优惠，以平台公告为准）。适合想先零成本试一下模型好不好用的人。': 'Agnes 공식 엔드포인트: 텍스트, 이미지, 비디오가 Key 하나를 공유합니다(이미지/비디오 엔드포인트는 내장되어 있어 따로 설정할 필요가 없습니다). 공식은 현재 이 모델들을 무료로 표시하고 있습니다(기간 한정, 플랫폼 공지 기준). 모델을 먼저 비용 없이 써 보고 싶은 분께 적합합니다.',
  'Agnes 文生图（当前免费）': 'Agnes 텍스트→이미지 (현재 무료)',
  'Agnes 文生视频（异步，等几分钟）': 'Agnes 텍스트→동영상 (비동기, 몇 분 소요)',
  'Agnes 的 size 是档位（1K/2K/3K/4K），不是像素值；参考图放 extra_body。': 'Agnes의 `size`는 단계(1K/2K/3K/4K)이며 픽셀 값이 아닙니다. 참조 이미지는 `extra_body`에 넣습니다.',
  'Agnes 的分辨率只认 720P 这一档。': 'Agnes는 720P 한 단계만 지원합니다.',
  'Agnes（免费）': 'Agnes(무료)',
  'AnySearch Key（可选）': 'AnySearch Key(선택)',
  'App 会去更新源读一份**版本清单**，有新版本就在这里提示你。它只读清单、**不会自己装东西** —— 装包那一步必须你亲手点（Android 规定普通应用不能静默安装，任何正规 App 都一样）。': '앱은 업데이트 소스에서 **버전 정보**를 읽어 새 버전이 있으면 여기에 알려 줍니다. 읽기만 하며 **스스로 무언가를 설치하지 않습니다** — 설치 버튼은 언제나 직접 누르셔야 합니다(Android는 일반 앱의 무음 설치를 허용하지 않습니다. 정상적인 앱은 모두 같습니다).',
  'App 内播放：可拖进度条（{0}）': '앱 내 재생 — 탐색(드래그) 가능 ({0})',
  'App 内播放：音频（{0}）': '앱 내 재생: 오디오 ({0})',
  'App 内没法播放这个文件': '이 파일은 앱 안에서 재생할 수 없습니다',
  'App 内没能渲染这个网页，原因：{0}\n下面是源码；要按网页看，请用右上角「浏览器打开」。': '앱에서 이 웹페이지를 렌더링하지 못했습니다. 원인: {0}\n아래는 소스입니다. 웹페이지로 보려면 오른쪽 위의 "브라우저에서 열기"를 사용하세요.',
  'App 内网页预览 · {0}': '앱 내 웹 미리보기 · {0}',
  'App 名：泡泡猫的DSH（本地 DSH 运行时）': '앱 이름: 泡泡猫的DSH(로컬 DSH 런타임)',
  'App 版本、机型、系统版本、屏幕与语言': '앱 버전, 기기 모델, OS 버전, 화면, 언어',
  'App 版本：v{0}{1}': '앱 버전: v{0}{1}',
  'Base URL / API Key / model id 三项都要填才能测试。': 'Base URL / API 키 / model id 세 가지를 모두 입력해야 테스트할 수 있습니다.',
  'Base URL 不能为空（自定义厂家必须自己填地址）。': 'Base URL은 비워 둘 수 없습니다(사용자 지정 공급자는 주소를 직접 입력해야 합니다).',
  'CPU（慢一点）': 'CPU(느림)',
  'CRF 20 左右画质很好、26~30 是"发出去够用"那一档。原来的宽度没超上限就不放大，只降码率。': 'CRF 20 정도면 화질이 아주 좋고, 26~30은 "보내기 충분한" 단계입니다. 원본 가로가 상한을 넘지 않으면 확대하지 않고 비트레이트만 낮춥니다.',
  'CSV/JSON → 结论 + 图表': 'CSV/JSON → 결론 + 차트',
  'Command（聚合，推荐）': 'Command(애그리게이터, 추천)',
  'DSH 会扫描两个真实目录：\n用户级 {0}/skills\n项目级 {1}/.dsh/skills\n点右上「新建」手写一个，或「对话生成」让模型写一个。': 'DSH는 실제 두 디렉터리를 검사합니다:\n사용자 수준 {0}/skills\n프로젝트 수준 {1}/.dsh/skills\n오른쪽 위 「새로 만들기」로 직접 작성하거나 「대화로 생성」으로 모델에게 작성하게 하세요.',
  'DSH 沙箱模式：danger-full-access —— 这是「Agent 能用哪些工具」的开关，与上面这些手机权限是两码事（Android 内核没有 landlock，这一项在手机上下调不了）。': 'DSH 샌드박스 모드: danger-full-access —— 「에이전트가 쓸 수 있는 도구」 스위치이며 위의 휴대폰 권한과는 별개입니다(Android 커널에 landlock이 없어 휴대폰에서는 낮출 수 없습니다).',
  'DeepSeek API Key（sk- 开头）': 'DeepSeek API 키(sk-로 시작)',
  'DeepSeek 官方': 'DeepSeek 공식',
  'DeepSeek 官方直连，用的是官方账号自己的额度与计费。适合已经有 DeepSeek 账号、想直接走官方端点的人。': 'DeepSeek 공식에 직접 연결하며, 공식 계정 자체의 할당량과 과금을 사용합니다. 이미 DeepSeek 계정이 있고 공식 엔드포인트를 바로 쓰고 싶은 분께 적합합니다.',
  'GPU 还没探测（引擎目录未就绪）：先启动一次本地模型，再点右上角刷新，GPU 就会可选。': 'GPU가 아직 감지되지 않았습니다(엔진 디렉터리 미준비). 로컬 모델을 한 번 시작한 뒤 오른쪽 위 새로고침을 누르면 GPU를 선택할 수 있습니다.',
  'GPU（通常快很多・推荐）': 'GPU(보통 훨씬 빠름 · 권장)',
  'HTTP 403（上游说：地区不可用）': 'HTTP 403(업스트림 응답: 지역에서 사용할 수 없음)',
  'HTTP 协议层出错：连接被中途关闭，或响应不完整。检查网络后重试。': 'HTTP 프로토콜 계층 오류: 연결이 도중에 끊겼거나 응답이 불완전합니다. 네트워크를 확인하고 다시 시도하세요.',
  'Key 不对或过期了 —— 回「设置 → 模型」重新填一把再点「测试并保存」。': 'Key가 틀렸거나 만료되었습니다 — 「설정 → 모델」로 돌아가 다시 입력하고 「테스트하고 저장」을 누르세요.',
  'Key 不能为空': 'Key는 비워 둘 수 없습니다',
  'Key 从哪来：用邮箱在 anysearch.com 注册就能拿一把（免费）。Key 只存在系统安全区，不进配置文件、不进日志。': 'Key를 받는 곳: anysearch.com에서 이메일로 가입하면 무료로 한 개 받습니다. Key는 시스템 보안 영역에만 저장되고 설정 파일과 로그에는 남지 않습니다.',
  'Key 存在「{0}」这家厂家名下（与「云端大模型」里那份是**同一个地方**，填一次两边都认）。留空就不动它 —— 所以这里**从不回显已存的 Key**。': 'Key는 「{0}」 업체 이름으로 저장됩니다(「클라우드 대형 모델」의 것과 **같은 곳**이라 한 번 입력하면 양쪽 모두 적용). 비워 두면 변경하지 않습니다 — 이 칸은 **저장된 Key를 표시하지 않습니다**.',
  'Key 已保存到「{0}」这家。': '"{0}"에 Key를 저장했습니다.',
  'Key 无效（401）': 'Key 무효(401)',
  'LongCat（美团）': 'LongCat(메이투안)',
  'MiMo 的官方接口没有数值语速参数，所以这三档是拼进风格指令里的（「语速放慢一些」这类），效果由模型理解。': 'MiMo 공식 API에는 숫자 속도 파라미터가 없어, 이 3단계는 스타일 지시(「조금 느리게」 등)에 문장으로 넣고 모델이 해석합니다.',
  'MiMo 的音色更自然，但**需要**你在「设置 → 云端大模型 → MiMo」里先填一个 API Key（`tp-` 开头的套餐 Key 会自动走套餐端点）。它出的是 wav（官方文档的格式），语速只能靠指令描述、所以只给三档。': 'MiMo는 더 자연스럽지만 **설정 → 클라우드 모델 → MiMo에서 API Key 입력이 필요**합니다(`tp-`로 시작하는 Key는 자동으로 토큰 플랜 엔드포인트를 사용합니다). 출력은 wav(공식 문서의 형식)이고, 속도는 말로 지시할 수밖에 없어 3단계만 제공합니다.',
  'MiMo（小米）': 'MiMo(샤오미)',
  'MiMo（更自然·需 Key）': 'MiMo(더 자연스러움, Key 필요)',
  'MiniMax 出 mp3、语速是真正的倍率，音色可以**从你的账号里拉取**（官方接口现拉，不是我们编的清单）。**需要**你在「设置 → 云端大模型 → MiniMax」里先填 API Key。': 'MiniMax는 mp3로 출력하고 속도는 실제 배율이며, 음성은 **내 계정에서 가져올 수** 있습니다(공식 API에서 즉시 조회 — 저희가 만들어낸 목록이 아닙니다). **설정 → 클라우드 모델 → MiniMax에서 API Key 입력이 필요**합니다.',
  'MiniMax 吃 aspect_ratio，不吃 size，也不吃参考图。': 'MiniMax는 `aspect_ratio`를 받으며 `size`와 참조 이미지는 받지 않습니다.',
  'MiniMax 拒绝了这次配音：{0}': 'MiniMax가 이 음성 합성을 거부했습니다: {0}',
  'MiniMax 的分辨率：H3 只支持 768P / 2K，H3-Max 只支持 480P / 768P（两边都能用的是 768P）；时长 H3 是 4–15 秒、H3-Max 是 5–15 秒（它不支持 4 秒）。': 'MiniMax 해상도: H3는 768P / 2K만, H3-Max는 480P / 768P만 지원합니다(둘 다 되는 것은 768P). 길이는 H3가 4–15초, H3-Max가 5–15초입니다(4초는 미지원).',
  'MiniMax 默认（英文叙事）': 'MiniMax 기본(영어 나레이션)',
  'MiniMax（多音色·需 Key）': 'MiniMax(다양한 음성, Key 필요)',
  'OpenAI 的 size 用像素值（1024x1024 这类），比例由尺寸表达；带参考图走 /images/edits multipart。': 'OpenAI의 `size`는 픽셀 값(1024x1024 등)이고 비율은 크기로 표현합니다. 참조 이미지가 있으면 /images/edits 멀티파트를 사용합니다.',
  'OpenCode API Key（同一个 Key 也用于免费那档）': 'OpenCode API Key(같은 키를 무료 등급에도 사용합니다)',
  'OpenCode Zen（免 Key）': 'OpenCode Zen(Key 불필요)',
  'OpenCode 的 Go 套餐：一个 Key 就能用 DeepSeek V4/V4.1、GLM 5.x、Qwen3.8、Grok 4.x 这一批模型。': 'OpenCode의 Go 요금제: 키 하나로 DeepSeek V4/V4.1, GLM 5.x, Qwen3.8, Grok 4.x 같은 모델을 쓸 수 있습니다.',
  'Seedream 的 size 用像素值，比例由尺寸表达；参考图放顶层 image 数组。': 'Seedream의 `size`는 픽셀 값이고 비율은 크기로 표현합니다. 참조 이미지는 최상위 `image` 배열에 넣습니다.',
  'TLS/HTTPS 握手失败：可能是网络中间人证书或系统时间不对。': 'TLS/HTTPS 핸드셰이크 실패: 중간자 인증서이거나 시스템 시간이 잘못됐을 수 있습니다.',
  'Tailscale IP 或局域网 IP': 'Tailscale IP 또는 LAN IP',
  'WebView 不支持它的容器或编码（比如部分 .mkv / .avi）。文件本身没问题 —— 用系统里能放它的应用打开即可。': 'WebView가 이 컨테이너/코덱을 지원하지 않습니다(일부 .mkv / .avi 등). 파일 자체는 문제없습니다 — 재생할 수 있는 앱으로 열면 됩니다.',
  'as_sk_…（留空 = 按匿名用）': 'as_sk_…(비워 두면 익명 사용)',
  'provider id（写进 overlay 的 providers.<id>）': 'provider id(overlay의 providers.<id>에 기록됨)',
  'size 要用 1024x1024 这类像素值，不是 1K/2K': 'size는 1K/2K 같은 단계가 아니라 1024x1024 같은 픽셀 값입니다',
  'v{0} 你选了跳过。出下一版时会再提示你。': 'v{0}은(는) 건너뛰기로 하셨습니다. 다음 버전이 나오면 다시 알려 드립니다.',
  'workspace: {0}\ncreated: {1}\ncreatedBy: 泡泡猫的DSH (Android)\n': 'workspace: {0}\ncreated: {1}\ncreatedBy: 泡泡猫的DSH (Android)\n',
  'wss 必须提供证书指纹——没有指纹就不该信任自签证书': 'wss는 인증서 지문이 필요합니다 — 지문이 없으면 자체 서명 인증서를 신뢰해서는 안 됩니다',
  '{0}\n…（已截断）': '{0}\n…(잘림)',
  '{0} / {1} · {2}/秒': '{0} / {1} · {2}/초',
  '{0} · {1} 个会话': '{0} · 세션 {1}개',
  '{0} 上下文': '{0} 컨텍스트',
  '{0} 个会话{1}': '세션 {0}개{1}',
  '{0} 个模型': '모델 {0}개',
  '{0} 个池子': '풀 {0}개',
  '{0} 个目录读取失败': '디렉터리 {0}개를 읽지 못했습니다',
  '{0} 充值': '{0} 충전',
  '{0} 分钟前': '{0}분 전',
  '{0} 分钟后': '{0}분 후',
  '{0} 天前': '{0}일 전',
  '{0} 小时前': '{0}시간 전',
  '{0} 崩过 {1} 次，已自动改用 {2}（优先保证能用）': '{0}이(가) {1}회 충돌하여 {2}(으)로 자동 전환(작동 우선)',
  '{0} 文件{1}': '파일 {0}개{1}',
  '{0} 条': '{0}개',
  '{0} 条说明': '설명 {0}건',
  '{0} 注册 / 申请 Key': '{0}에서 가입 / Key 신청',
  '{0} 类型（{1}）\n交给系统里能打开它的应用试试：': '{0} 유형({1})\n시스템에서 이걸 열 수 있는 앱에 맡겨 보세요:',
  '{0} 起不来，已自动改用 {1}（优先保证能用）': '{0}이(가) 시작되지 않아 {1}(으)로 자동 전환했습니다(사용 가능한 것을 우선)',
  '{0}: 无法列出目录（{1}）': '{0}: 디렉터리를 나열할 수 없음({1})',
  '{0}: 无法判断目录是否存在（{1}）': '{0}: 디렉터리 존재 여부를 확인할 수 없음({1})',
  '{0}: 无法读取文件信息（{1}）': '{0}: 파일 정보를 읽을 수 없음({1})',
  '{0}:{1}（{2} 小时后）': '{0}:{1}({2}시간 후)',
  '{0}K 上下文': '{0}K 컨텍스트',
  '{0}M 上下文': '{0}M 컨텍스트',
  '{0}月{1}日 {2}:{3}': '{0}월 {1}일 {2}:{3}',
  '{0}（{1} 个成员）': '{0}({1}명)',
  '{0}（占位，还没做）': '{0}(플레이스홀더, 아직 미구현)',
  '{0}（已失效）': '{0}(만료됨)',
  '{0}（本机服务没在运行）': '{0}(온디바이스 서비스가 실행 중이 아닙니다)',
  '{0}（正在回答）': '{0}(답변 중)',
  '{0}，{1} 个模型，{2}，{3}': '{0}, 모델 {1}개, {2}, {3}',
  '{0}，{1}，{2} 个模型，{3}': '{0}, {1}, 모델 {2}개, {3}',
  '{0}：这个入口还没接入': '{0}: 이 진입점은 아직 연결되지 않았습니다',
  '…还有 {0} 条，去发布页能看到全部。': '…외 {0}건은 릴리스 페이지에서 모두 볼 수 있습니다.',
  '⚠️ 三点如实说明：\n· 搜索请求会发到 **api.anysearch.com**（这是联网功能，不是本机算的）。\n· 它**在建会话那一刻**挂上去 —— 改完之后要**开一个新会话**才生效，老会话不变。\n· 匿名层限流较低：搜得太频繁会被限，等一会儿或填一把 Key。': '⚠️ 솔직하게 세 가지:\n· 검색 요청은 **api.anysearch.com**으로 전송됩니다(기기에서 계산하는 기능이 아닙니다).\n· **세션을 만들 때** 붙습니다 — 변경은 **새 세션**부터 적용되고 기존 세션은 그대로입니다.\n· 익명 레이어는 속도 제한이 낮습니다. 너무 자주 검색하면 제한되니 잠시 기다리거나 Key를 넣으세요.',
  '⚠️ 两点如实说明：\n· 多一层子 agent = **多一份 token 与时间**（子会话也要跑模型），用免费那条小模型通道时尤其明显。\n· 改完**只在下一个会话生效**（会话进程启动时才读这份配置）。': '⚠️ 솔직하게 두 가지:\n· 하위 에이전트를 한 층 더 두면 **토큰과 시간이 더 듭니다**(하위 세션도 모델을 돌립니다). 무료 소형 모델 경로에서 특히 두드러집니다.\n· 변경은 **다음 세션**부터 적용됩니다(설정은 세션 시작 시 읽힙니다).',
  '⚠️ 先说清它能做什么、不能做什么：\n· 匿名层**只有一个 20B 级的模型**（`openai-fast`）：聊天、用工具都行，但**不是聪明模型** —— 写小说、长文、画布这类重活它接不住，那些请用自己的模型。\n· 有速率限制（人多了会慢或被限），失败了再试一次即可。\n· 上游是社区项目，**随时可能变**；真变了他会如实报错，不会假装成功。\n· 用不到时把开关关掉即可，你自己的模型配置一点都不会动。': '⚠️ 할 수 있는 일과 없는 일을 먼저:\n· 익명 레이어 모델은 **20B급 하나뿐**입니다(`openai-fast`). 대화와 도구 사용은 되지만 **똑똑한 모델은 아닙니다** — 소설, 장문, 캔버스 같은 무거운 작업에는 부족합니다. 그런 작업은 직접 설정한 모델을 쓰세요.\n· 속도 제한이 있습니다(혼잡하면 느려지거나 거부됩니다). 그럴 땐 다시 시도하세요.\n· 상류는 커뮤니티 프로젝트라 **언제든 바뀔 수 있습니다**. 바뀌면 솔직하게 오류를 알리고 성공한 척하지 않습니다.\n· 필요 없을 때 스위치를 끄면 됩니다. 직접 설정한 모델 구성은 전혀 건드리지 않습니다.',
  '⚠️ 只提示、不替你判断：去掉**别人版权作品**上的水印有侵权风险（尤其发布或商用时）。': '⚠️ 알림만 드립니다, 판단은 본인 몫입니다: **타인의 저작물**에서 워터마크를 지우는 것은 침해 위험이 있습니다(특히 공개나 상업적 이용 시).',
  '⚠️ 本页不显示这 5 项的实时状态：Android 只在系统页面里读 / 改它们（要在这里显示，得再加一个原生查询接口，这一版没做）。是否已开启，以系统页面里的开关为准。': '⚠️ 이 페이지는 5가지 항목의 현재 상태를 표시하지 않습니다: Android는 이들을 시스템 페이지 안에서만 읽고 바꿉니다(여기에 표시하려면 네이티브 조회 API를 추가해야 하는데 이 버전에는 없습니다). 실제 상태는 시스템 페이지의 스위치로 확인하세요.',
  '⚠️ 请先看清楚：\n· 上游的免费额度**只给它自家客户端用**，这条通道是把请求**伪装成官方 CLI** 去通过它的限制 —— 属于灰色用法，**随时可能失效**（自 2026-09-16 起已收紧 6 次：换过端点、加过会话头、工具指纹从两个涨到四个）。\n· **它不需要任何 Key**：那条通道本来就是匿名的（上游凭据就是公开的 `public`），所以你不用在这里填任何东西；失效时它会如实报错，不会假装成功。\n· 它按出口 IP 限流，被限流时等一会儿再试。\n· 本 App **不做** IP 轮换、也不做反复重试（不拿它去刷额度）。\n· 用不到时请把它关掉。': '⚠️ 먼저 확인하세요:\n· 업스트림 무료 한도는 **자사 클라이언트 전용**이고, 이 채널은 요청을 **공식 CLI로 위장**해 통과시킵니다 — 회색지대 사용이며 **언제든 끊길 수 있습니다**(2026-09-16 이후 게이트 변경 6회: 엔드포인트 이동, 세션 헤더 추가, 도구 지문이 2개에서 4개로).\n· **Key가 필요 없습니다**: 이 레인은 원래 익명입니다(업스트림 자격 증명은 공개 문자열 `public`). 여기에 입력할 것은 없습니다. 실패하면 솔직히 오류를 내고 성공한 척하지 않습니다.\n· 출구 IP 기준 요청 제한이 있습니다. 제한되면 잠시 후 다시 시도하세요.\n· 이 앱은 IP 로테이션을 **하지 않고** 반복 재시도도 **하지 않습니다**(한도를 긁지 않습니다).\n· 쓰지 않을 때는 꺼 두세요.',
  '⚠️ 请求形状按各家的文档写（端点、参数名、轮询都不一样）—— **能不能通要试**；失败会把上游原话显示出来。': '⚠️ 요청 형식은 각 사 문서를 따릅니다(엔드포인트, 파라미터 이름, 폴링이 모두 다릅니다) —— **되는지는 시도해 봐야 합니다**. 실패하면 업스트림 원문을 그대로 보여 줍니다.',
  '⚠️ 边界（别踩）：图像与视频都**按厂家的形状**发 —— 端点、参数名、轮询各不相同（唯一来源是 assets/toolbox/media-vendors.mjs）。本机没有这些厂家的 Key、也没法真机验证，所以**能不能通要试**；失败了会把上游原话显示出来，不假装成功。': '⚠️ 한계: 이미지와 동영상 모두 **각 사의 형식**으로 전송합니다 —— 엔드포인트, 파라미터 이름, 폴링이 모두 다릅니다(유일한 출처는 assets/toolbox/media-vendors.mjs). 이 기기에는 해당 공급사의 Key가 없고 실기기 검증도 할 수 없으므로 **되는지는 시도해 봐야 합니다**. 실패하면 업스트림 원문을 그대로 보여 주고 성공한 척하지 않습니다.',
  '⚠️ 这个模型的对话模板可能与 DSH 不兼容（启动自检没通过）：发消息很可能直接失败。请到「设置 → 运行日志」导出后发回，我会按真实报错改。': '⚠️ 이 모델의 대화 템플릿이 DSH와 호환되지 않을 수 있습니다(시작 자체 점검 실패). 메시지를 보내면 실패할 가능성이 높습니다. 「설정 → 실행 로그」를 내보내 보내주세요. 실제 오류를 보고 수정하겠습니다.',
  '✗ 名字不合法。{0}': '✗ 이름이 올바르지 않습니다. {0}',
  '　「自定义」是占位：还没做，点了会如实说明，不会把主题切到一个不存在的状态。': '　"사용자 지정"은 플레이스홀더입니다: 아직 구현되지 않았고, 누르면 솔직히 그렇게 안내하며, 존재하지 않는 상태로 테마를 바꾸지 않습니다.',
  '　当前语言：{0}（{1}）': '　현재 언어: {0}({1})',
  '「{0}」已经在池子「{1}」里了。': '"{0}"은(는) 이미 풀 "{1}"에 있습니다.',
  '「{0}」已经登记，但名下一条模型都没有 —— 现在选中它没有任何模型可用。\n去「设置 → 模型 → 我的模型」点开这家：{1}点「测试并保存」（它会自动把模型登记进来），或点「获取模型」自己勾几个。': '「{0}」는 등록되어 있지만 모델이 하나도 없습니다 — 지금 선택하면 쓸 수 있는 모델이 없습니다.\n「설정 → 모델 → 내 모델」에서 이 서비스를 열어 주세요: {1}「테스트 후 저장」을 누르면 모델이 자동 등록되고, 아니면 「모델 가져오기」로 직접 몇 개 고를 수 있습니다.',
  '「{0}」执行失败：{1}': '"{0}" 실행 실패: {1}',
  '「{0}」执行异常：{1}': '"{0}" 실행 중 예외: {1}',
  '「{0}」执行成功：{1}': '"{0}" 실행 성공: {1}',
  '「{0}」的 Key 去哪拿': '“{0}”의 키를 어디서 받나요',
  '「{0}」还没配 API Key —— 现在选中它，发言时必然失败。去「设置 → 模型 → 我的模型」填 Key 并「测试并保存」。': '「{0}」에 API Key가 없습니다 — 지금 선택하면 발언할 때 반드시 실패합니다. 「설정 → 모델 → 내 모델」에서 Key를 입력하고 「테스트 후 저장」을 누르세요.',
  '「作品」里还没有图片 —— 先生成一张，或用上面的按钮选一张。': '「작품」에 아직 이미지가 없습니다. 먼저 생성하거나 위 버튼으로 골라 주세요.',
  '「免费模型（无需 Key）」这条通道被上游关掉了（不是你没配 Key —— 它本来就不用 Key）。\n下一步：去「设置 → 模型」换一个自己配了 Key 的模型；这条通道以后再恢复就能继续用。': '「무료 모델(Key 불필요)」경로가 상류에서 차단되었습니다(Key를 설정하지 않아서가 아닙니다 — 이 경로는 원래 Key가 필요 없습니다).\n다음 단계: 「설정 → 모델」에서 직접 Key를 설정한 모델로 바꾸세요. 이 경로가 복구되면 다시 쓸 수 있습니다.',
  '「推理后端」和「上下文长度」会记住：下次进这一页、下次启动本地服务都以它为准。': '"추론 백엔드"와 "컨텍스트 길이"는 기억됩니다. 다음에 이 페이지를 열 때와 다음에 로컬 서비스를 시작할 때 적용됩니다.',
  '一': '일',
  '一个 Key 即可用 DeepSeek / MiMo / LongCat / GLM / Qwen / Claude / GPT 等全部模型。': 'Key 하나로 DeepSeek / MiMo / LongCat / GLM / Qwen / Claude / GPT 등 모든 모델을 사용할 수 있습니다.',
  '一句话或一张参考图，生成图片': '한 줄 설명이나 참고 이미지로 이미지 생성',
  '一屏能看更多内容': '한 화면에서 더 많이 보기',
  '一条都没加进去。': '한 건도 추가되지 않았습니다.',
  '一行一个镜头。例如：\n深夜的办公室只剩一盏灯\n他盯着屏幕上的数字，笑了一下\n门开了，站着他的老板': '한 줄에 한 숏. 예:\n자정의 사무실, 등 하나만 남았다\n그는 화면의 숫자를 보며 웃었다\n문이 열리고 사장이 서 있었다',
  '一键发给开发者': '개발자에게 보내기',
  '一键美化': '원터치 보정',
  '万相只有文生视频（不吃首帧图），分辨率 720P / 1080P。': '만상(通義万相)은 텍스트→동영상만 지원하며(첫 프레임을 받지 않음) 해상도는 720P / 1080P입니다.',
  '万相没有比例参数：比例由尺寸表达（1280x720 就是 16:9），而且走异步任务。': '만상에는 비율 파라미터가 없습니다: 비율은 크기로 표현하며(1280x720이 16:9), 비동기 작업으로 실행됩니다.',
  '万相走异步任务（不是 OpenAI 兼容入口），尺寸用 1024*1024 这种写法': '완샹은 비동기 작업입니다(OpenAI 호환 엔드포인트가 아닙니다). 크기는 1024*1024 형식으로 씁니다',
  '三': '삼',
  '三个更新源都没连上（多半是网络问题，过一会儿再试）。': '세 개의 업데이트 소스 모두 연결하지 못했습니다(대개 네트워크 문제입니다. 잠시 후 다시 시도해 주세요).',
  '三色档位怎么算的': '세 단계 판정 기준',
  '上下文估算：约 {0}（{1} 条消息 · 约 {2} tokens）{3}': '컨텍스트 추정: 약 {0}({1}개 메시지 · 약 {2} tokens){3}',
  '上下文超出该模型上限。请精简输入，或换一个上下文窗口更大的模型。': '컨텍스트가 이 모델의 한도를 넘었습니다. 입력을 줄이거나 컨텍스트 창이 더 큰 모델로 바꾸세요.',
  '上下文长度': '컨텍스트 길이',
  '上下文长度（可选）': '컨텍스트 길이(선택)',
  '上次同步：{0}': '마지막 동기화: {0}',
  '上次检查': '마지막 확인',
  '上游把请求当成"非官方客户端"拒了。这条通道可能已经变了，把自检结果发给开发者核对。': '업스트림이 요청을 "비공식 클라이언트"로 보고 거부했습니다. 이 채널이 바뀌었을 수 있으니 자체 점검 결과를 개발자에게 보내 확인하세요.',
  '上游自己出问题了，过一会儿再试（不是你的配置问题）。': '업스트림 자체 문제입니다. 잠시 후 다시 시도하세요(설정 문제가 아닙니다).',
  '上游自身故障（5xx）': '업스트림 장애(5xx)',
  '上游那套自带的示例游戏（含成人向题材）**没有随包**；题材与分级请自己把握。': '업스트림이 함께 제공하는 예시 게임(성인题材 포함)은 **포함하지 않았습니다**. 주제와 등급은 직접 판단해 주세요.',
