  '下载中断：连接被提前关掉了（{0}）。已保留进度，可以重试续传。': '다운로드 중단: 연결이 일찍 닫혔습니다 ({0}). 진행 상황은 남겨 두어 이어받을 수 있습니다.',
  '下载出错了：{0}': '다운로드 오류: {0}',
