  '下载到的包校验没通过（哈希不符），已删除。这通常是下载中途坏了，请重试一次。': '내려받은 패키지가 검증을 통과하지 못해(해시 불일치) 삭제했습니다. 대개 다운로드 중에 손상된 경우이며, 다시 시도해 주세요.',
  '下载在**本机**做，断了能接着下；装之前会**验两样** —— 文件哈希（没下坏）+ 签名（跟现在这个 App 是同一把钥匙签的）。签名对不上就不给你装，这是防止包被替换的那道闸。': '다운로드는 **이 기기에서** 이루어지며, 끊겨도 이어받을 수 있습니다. 설치 전에 **두 가지를 확인**합니다 — 파일 해시(손상 여부)와 서명(지금 이 앱과 같은 키로 서명되었는지). 서명이 맞지 않으면 설치하지 않습니다. 이것이 패키지 바꿔치기를 막는 관문입니다.',
  '下载失败：HTTP {0}（{1}）': '다운로드 실패: HTTP {0} ({1})',
