  '下载的压缩包不见了，请重试。': '내려받은 압축 파일이 사라졌습니다. 다시 시도하세요.',
  '下载的资料是第三方社区语料：数据集作者做过过滤，但过滤不完整，我们也没有逐条审查过，内容不代表我们的观点，请自行判断是否适合你的用途。': '다운로드하는 자료는 제3자 커뮤니티 데이터입니다. 데이터셋 작성자가 필터링했지만 그 필터링은 불완전하고, 저희도 항목별로 검토하지 않았습니다. 내용은 저희 의견을 대표하지 않습니다. 용도에 맞는지는 직접 판단해 주세요.',
  '下载运行环境时出错：{0}': '실행 환경을 내려받는 중 오류가 발생했습니다: {0}',
  '不再触发': '다시 실행 안 함',
  '不到 1 分钟': '1분 미만',
  '不勾「精确剪」时走 `-c copy`（不重编码）：剪出来的位置会**对齐到最近的关键帧**，可能和你填的差零点几秒到一两秒 —— 换来的是几秒出结果、画质一点不掉。': '"정확히 자르기"를 끄면 `-c copy`(재인코딩 없음)로 처리합니다: 잘리는 지점이 **가장 가까운 키프레임**에 맞춰져 입력한 위치와 0.몇 초~1~2초 차이가 날 수 있습니다 — 대신 몇 초 만에 끝나고 화질은 전혀 떨어지지 않습니다.',
  '不勾就是对齐关键帧、几乎瞬间完成': '체크하지 않으면 키프레임에 맞춥니다 — 거의 순식간에 끝남',
