  '以上都在 App 私有目录里，其它应用读不到；长按可以复制。「模型清单」里存的是厂家/模型/轮换池的结构，**不含任何 API Key**（Key 只在系统安全区）。': '위 항목은 모두 앱 전용 디렉터리에 있어 다른 앱이 읽을 수 없습니다. 길게 눌러 복사하세요. 「모델 목록」에는 제조사/모델/로테이션 구조만 저장되며 **API Key는 포함되지 않습니다**(Key는 시스템 보안 영역에만).',
