  '会话已失效，请返回列表重新打开或新建会话': '세션이 만료되었습니다. 목록으로 돌아가 다시 열거나 새 세션을 만드세요.',
  '会话拉长了模型会**漂**（前后不像同一个人）。撑不住就开新的一局 —— 这不是你的用法问题。': '대화가 길어지면 모델이 **흔들립니다**(앞뒤가 같은 사람 같지 않게 됩니다). 버티지 못하면 새 판을 시작하세요 — 이건 당신의 사용법 문제가 아닙니다.',
