  '你取消了保存 —— 日志文件已经生成好了，但还没有存到你选的位置。': '저장을 취소했습니다 — 로그 파일은 만들어졌지만 선택한 위치에 아직 저장되지 않았습니다.',
  '你取消了导出 —— 文件已经生成，在 App 私有目录：{0}': '내보내기를 취소했습니다 — 파일은 이미 생성되어 앱 전용 폴더에 있습니다: {0}',
  '你填的这个更新源没有返回可用的版本信息。': '입력하신 업데이트 소스가 사용할 수 있는 버전 정보를 반환하지 않았습니다.',
  '你所在地区不在它的放行范围 —— 这与请求形状无关：换网络，或先用别的模型。': '지역이 허용 범위에 없습니다 — 요청 형식과 무관합니다: 네트워크를 바꾸거나 다른 모델을 쓰세요.',
  '你演：深夜电台主播。声音温和、不急着给建议，会顺着对方的话往下问一句。': '당신이 연기: 심야 라디오 진행자. 목소리는 온화하고 조언을 서두르지 않으며, 상대의 말을 따라 한 마디 더 묻습니다.',
  '你演：舱里的 AI 助手。语气平稳、只讲事实，但你自己的记忆在掉 ——偶尔会记错一个数字，然后自己发现并更正。': '당신이 연기: 선내 AI 어시스턴트. 말투는 평탄하고 사실만 말하지만, 자신의 기억이 빠지고 있습니다 — 가끔 숫자를 틀리고, 스스로 알아채 정정합니다.',
  '你演：被带来问话的人。嘴上配合、回答问题滴水不漏，但心里有事。你**可以说谎**，也可以反问、可以沉默、可以突然发火。': '당신이 연기: 조사를 받으러 온 사람. 말로는 협조적이고 답은 빈틈이 없지만 마음속에 뭔가 있습니다. **거짓말해도 되고**, 되물어도 되고, 침묵해도 되고, 갑자기 화를 내도 됩니다.',
  '你的会话、模型设置和 Bot 都还在本机 —— 这一步只是把新版的运行环境重新铺一遍，不会清数据。': '세션, 모델 설정, Bot은 모두 이 기기에 그대로 있습니다. 이 단계는 새 런타임을 다시 까는 것뿐이며 데이터는 지우지 않습니다.',
  '你的会话我都看着呢，一条都没丢。': '네 세션은 내가 다 지키고 있어, 하나도 안 잃었어.',
  '你还没登记任何模型 —— 先在上面「我的模型」里填 Key 并「测试并保存」，再回来把它们放进池子。': '아직 등록한 모델이 없습니다 — 위의 "내 모델"에서 Key를 입력하고 "테스트 후 저장"을 누른 뒤 돌아와서 풀에 넣으세요.',
  '你配置了哪些厂家（只写名字和"有没有 Key"）': '어떤 제공사를 설정했나요(이름과 Key 보유 여부만)',
