  '做游戏很花时间：一部小说从拆解到能玩，通常是**多轮对话**的事，不是一句话就出成品。': '게임 제작은 시간이 걸립니다: 소설을 분해해 플레이 가능한 형태가 되기까지 보통 **여러 차례 대화**가 필요하며, 한 마디로 완성되지 않습니다.',
  '做这个主要是下班晚上才有时间做，而且本人公众号一直没有人关注，要求不多：），麻烦大家点个关注就行': '이건 주로 퇴근 후 밤에만 만들 수 있고, 제 계정은 팔로워가 하나도 없어요. 바라는 건 별로 없습니다 :), 그냥 팔로우 한 번씩 눌러주세요.',
