  '先写一句大概的想法，我再帮你写专业。': '먼저 대략적인 아이디어를 적어 주세요. 제가 전문적으로 다듬어 드립니다.',
  '先写点内容再添加': '먼저 내용을 작성하세요',
  '先填 Base URL 再拉模型列表。': 'Base URL을 먼저 입력한 뒤 모델 목록을 가져오세요.',
  '先看引擎有没有（没有 → 红）；引擎有再看内存（不够 → 红；余量不足 2 GB、或 2 GB 以上文件装在 8 GB 机上 → 白）；都过 → 绿。点【测试】真跑一次之后，改用实测速度判：低于 5 tok/s 红、5–10 白、10 以上绿。': '먼저 엔진 포함 여부(없으면 빨강), 다음 메모리(부족하면 빨강, 여유 2 GB 미만이거나 8 GB 기기에서 2 GB 이상 파일이면 흰색), 둘 다 통과하면 초록. [테스트]로 실제 실행한 뒤에는 실측 속도로 판정합니다: 5 tok/s 미만 빨강, 5~10 흰색, 10 이상 초록.',
  '先确认手机能上网（换 WiFi/流量试一下）；如果用代理，看代理是否在跑。': '먼저 휴대폰이 인터넷에 연결되는지 확인하세요(Wi-Fi/데이터를 번갈아 시도). 프록시를 쓴다면 프록시가 실행 중인지 보세요.',
  '先粘贴 Key 再保存（留空不会改动已存的 Key）。': '저장하기 전에 Key를 붙여 넣으세요(비워 두면 저장된 Key는 그대로입니다).',
  '先选一张图（要按原图尺寸算框的位置，读不出尺寸就不给用）': '먼저 사진을 골라 주세요(상자 위치는 원본 크기로 계산합니다. 못 읽으면 쓰지 않습니다)',
  '先选一张要修的图。': '먼저 편집할 사진을 골라 주세요.',
