  '写小说、做游戏、剪视频 —— 我都能陪你干。': '소설도, 게임도, 영상 편집도 — 다 같이 할 수 있어.',
  '写模型配置失败：{0}': '모델 설정 쓰기 실패: {0}',
  '写系统目录': '시스템 디렉터리 쓰기',
  '冰糖': '冰糖',
  '冷调': '차갑게',
  '准备中…': '준비 중…',
  '准备失败：{0}': '준비 실패: {0}',
  '凌晨两点的直播间，一通"我没事，就是想说说话"的电话': '새벽 2시 방송실, "괜찮아요, 그냥 얘기하고 싶어서요"라는 전화 한 통',
  '凌晨两点，一盏台灯。他是被带来问话的人 —— 而他在装': '새벽 2시, 스탠드 하나. 그는 조사를 받으러 온 사람 — 그리고 연기하고 있습니다',
  '凌晨两点，直播间只剩你一个人。刚接进来一通电话，对方第一句是「我没事，就是想说说话」。': '새벽 2시, 방송실에는 당신 혼자입니다. 방금 전화 한 통이 들어왔고, 상대의 첫마디는 "괜찮아요, 그냥 얘기하고 싶어서요"입니다.',
  '凌晨的审讯室，一盏台灯照着桌面，屋外没有声音。问你的是一位进来就没坐下的警官。': '새벽의 심문실, 스탠드 하나가 책상을 비추고 밖에서는 아무 소리도 나지 않습니다. 묻는 경관은 들어온 뒤 한 번도 앉지 않았습니다.',
  '几个模型排成一队：前一个不可用就自动换下一个': '여러 모델을 줄 세워 두고, 앞 모델을 못 쓰면 자동으로 다음 모델로 넘어갑니다',
  '几段不是同一种格式时勾上：先把每段统一成第一段的规格再拼': '클립들의 형식이 다를 때 켜세요: 먼저 모두 첫 번째와 같은 사양으로 맞춘 뒤 이어 붙입니다',
  '出于安全，这个包不会给你装。': '안전을 위해 이 패키지는 설치하지 않습니다.',
  '分享': '공유',
  '分享 / 保存': '공유 / 저장',
  '分享 / 保存到相册': '공유 / 갤러리에 저장',
  '分享 / 发送给别人': '공유 / 다른 사람에게 보내기',
  '分享失败：{0}': '공유 실패: {0}',
  '分享没成功：{0}': '공유하지 못했습니다: {0}',
  '分享运行日志': '실행 로그 공유',
  '分类': '분류',
  '分类和重要度可以直接改。加入后是「全局」记忆（每个工作目录都注入）；想限定某个目录，可以在条目上再改。': '분류와 중요도는 여기서 바로 바꿀 수 있습니다. 추가하면 **전체** 기억이 됩니다(모든 작업 디렉터리에 주입). 특정 폴더로 제한하려면 나중에 항목에서 수정하세요.',
  '分辨率': '해상도',
  '分镜 → 每镜画面 → 合成一条短剧': '스토리보드 → 컷별 화면 → 숏드라마 한 편',
  '切换': '전환',
  '切换会重启本地服务（几秒到几十秒）。对话记录不清空 —— 新模型能看到之前的对话。': '전환하면 로컬 서비스가 재시작됩니다(몇 초~수십 초). 대화 기록은 지워지지 않아 새 모델도 이전 대화를 볼 수 있습니다.',
  '切换到 {0}': '{0}(으)로 전환',
  '切换失败：{0}': '전환 실패: {0}',
  '切换失败：引擎没起来（详见运行日志）': '전환 실패: 엔진이 시작되지 않았습니다(실행 로그 참조)',
  '切换本地模型': '로컬 모델 전환',
  '切界面文案，点一下立即生效、重启后保持': '인터페이스 문구 전환, 탭하면 바로 적용되고 재시작해도 유지됩니다',
  '切的是 App 自己画的界面：导航、设置、按钮、内置提示。电脑上那台 DSH 回传的内容 —— 会话消息、技能名、专家库、后端报错 —— 是它给的，保持原文，App 不替它决定用什么语言。': '앱이 직접 그리는 화면(내비게이션, 설정, 버튼, 내장 안내)만 바뀝니다. DSH가 돌려주는 내용(세션 메시지, 스킬 이름, 전문가 라이브러리, 백엔드 오류)은 원문 그대로 표시되며 언어를 앱이 정하지 않습니다.',
  '列表里没有你想要的，就点它拉一次再勾选。': '목록에 원하는 게 없으면 눌러서 한 번 불러온 뒤 선택하세요.',
