  '加好了。': '추가했습니다.',
  '勉强运行': '간신히 실행',
  '勾选 {0} 个 —— 保存时会和上面手填的 model id 一起登记。': '{0}개 선택 — 저장할 때 위에서 직접 입력한 model id와 함께 등록됩니다.',
  '勾选上面的模型（可多选）': '위 모델을 선택하세요 (여러 개 가능)',
  '勾选的这些已经在「我的模型」里了，没有重复写。': '선택한 항목은 이미 "내 모델"에 있어서 중복 등록하지 않았습니다.',
  '包名：{0}': '패키지명: {0}',
  '匿名': '익명',
  '厂家 id（用它读 Key）': '업체 id(Key를 읽는 데 사용)',
  '厂家名': '공급사 이름',
  '厂家和 Key 都有了，但还没有模型：去「设置 → 模型」点「获取模型」，勾好模型再保存，会话里才会出现可选模型。（想省事也可以先打开「免费模型（无需 Key）」。）': '제공자와 Key는 있는데 모델이 없습니다: \'설정 → 모델\'에서 \'모델 가져오기\'를 눌러 원하는 모델을 체크하고 저장해야 세션에서 선택할 수 있습니다. (간단히 하려면 \'무료 모델(Key 불필요)\'을 켜도 됩니다.)',
  '历史会话 · {0} · {1} · DSH 未提供标题': '지난 세션 · {0} · {1} · DSH가 제목을 제공하지 않음',
  '历史会话读取失败：运行时没起来或未配置模型（不影响下方本次会话）': '지난 세션을 불러오지 못했습니다: 런타임이 실행 중이 아니거나 모델이 설정되지 않았습니다 (아래 이번 세션에는 영향 없음)',
  '压小': '용량 줄이기',
  '压小要重新编码，按片长等：手机上处理 1 分钟 1080p 大约要几十秒到几分钟。': '용량 줄이기는 재인코딩이라 길이만큼 걸립니다: 1080p 1분이면 스마트폰에서 수십 초~몇 분 정도.',
  '压缩包大小不对（{0} 字节，应为 {1}）——下载不完整，已删掉，请重试。': '압축 파일 크기가 다릅니다 ({0} 바이트, 예상 {1}) — 다운로드가 불완전합니다. 삭제했으니 다시 시도하세요.',
  '压缩包校验不通过（sha256 对不上）——已删掉，请重试。如果总是这样，可能是网络中间有东西改了内容。': '체크섬이 맞지 않습니다 (sha256) — 압축 파일을 삭제했습니다. 다시 시도하세요. 계속 그렇다면 네트워크 중간에서 내용이 바뀌고 있을 수 있습니다.',
  '原因未知': '원인 불명',
  '原因：{0}\n画面和字幕都在；每一镜的时长是按文字长度**估**的。想要声音就改用 MiMo 或 MiniMax（各填一个 Key）再生成一次。': '이유: {0}\n영상과 자막은 그대로 들어 있습니다. 각 샷 길이는 글자 수로 **추정**한 값입니다. 소리가 필요하면 MiMo 또는 MiniMax로 바꾸고(각각 Key 입력) 다시 생성하세요.',
  '原图': '원본',
  '原图尺寸：{0}×{1} 像素': '원본 크기: {0}×{1} 픽셀',
  '原始信息（排查用）': '원본 정보(문제 확인용)',
  '去「专家」页打开开关，开启的专家会出现在这里。': '"전문가" 페이지에서 스위치를 켜면, 켠 전문가가 여기에 표시됩니다.',
  '去「设置 → 模型 → 我的模型」：点开一家内置厂家（地址已经内置好）→ 只填 API Key → 点「测试并保存」。\n\n保存成功后，这里就会按厂家分组列出你的模型，点一下就能用；此前那种"没配置也能随便切模型"的假象，就是硬编码清单造成的。': '「설정 → 모델 → 내 모델」로 가세요: 내장 제조사를 열고(주소는 이미 입력됨) → API Key만 붙여넣기 → 「테스트 후 저장」을 누릅니다.\n\n저장되면 여기에 제조사별로 모델이 나열되고 한 번 누르면 전환됩니다. 예전에 "설정 없이도 아무 모델이나 전환된다"는 착각은 하드코딩된 목록 때문이었습니다.',
  '去「设置 → 模型」填 Key': '설정 → 모델에서 Key 입력',
  '去哪拿 Key': '키 받는 곳',
  '去处理': '처리하기',
  '去微信搜索框粘贴就能关注（ID：paopaocat888）。': 'WeChat 검색창에 붙여넣으면 팔로우할 수 있습니다(ID: paopaocat888).',
  '去注册 / 申请 Key': 'Key 발급받기',
  '去知识库页重建': '지식 페이지에서 다시 만들기',
  '去系统设置': '시스템 설정 열기',
  '去设置': '설정 열기',
  '去设置里填 Key': '설정에서 Key 입력',
  '去设置里配 Key': '설정에서 Key 입력',
  '去重 / 规范 / 分组汇总': '중복 제거 / 형식 통일 / 그룹 집계',
  '参与检索': '검색에 사용',
  '参数': '설정',
  '参数不一致时重新编码（慢）': '형식이 다르면 재인코딩(느림)',
  '参数或模型不被支持：请确认模型名可用，并确认该模型支持 OpenAI 兼容协议。': '파라미터 또는 모델이 지원되지 않습니다: 모델 이름이 유효한지, 해당 모델이 OpenAI 호환 프로토콜을 지원하는지 확인하세요.',
  '参考图最多 4 张。': '참조 이미지는 최대 4장입니다.',
  '参考图（可选，最多 4 张）': '참조 이미지(선택, 최대 4장)',
  '双语对照，不是机翻腔': '대역 형식, 기계 번역투가 아님',
  '发消息…': '메시지…',
  '发消息前记得先把模型选好哦。': '메시지를 보내기 전에 모델을 골라 두는 거 잊지 마.',
  '发现新版本 v{0}': '새 버전 v{0} 사용 가능',
  '发送': '전송',
  '发送失败：{0}': '전송 실패: {0}',
  '取到了 {0} 个免费模型，已写进列表。': '무료 모델 {0}개를 가져와 목록에 추가했습니다.',
  '取消': '취소',
  '取消下载': '다운로드 취소',
  '取消提炼': '추출 취소',
  '取消生成': '생성 취소',
  '变暗': '어둡게',
  '口播': '내레이션',
  '口播与短剧': '내레이션과 숏드라마',
  '另外接口返回的 {0} 个是图像/视频模型 —— 那些端口是内置的（生成图片/视频时自动调用），不列进会话的模型列表。': '참고로 반환된 {0}개는 이미지/동영상 모델입니다 — 해당 엔드포인트는 내장되어 있고(이미지/동영상 생성 시 자동 호출) 세션 모델 목록에는 표시되지 않습니다.',
  '只会删掉这个池子（{0} 个成员）和它在模型面板里的那一项；成员模型本身与各厂家的 Key 都不动。': '이 풀({0}개 멤버)과 모델 패널의 해당 항목만 삭제됩니다. 멤버 모델 자체와 각 공급사의 Key는 그대로 유지됩니다.',
  '只信任这个指纹的证书，其它一律拒绝': '이 지문의 인증서만 신뢰하고 나머지는 모두 거부합니다',
  '只列了最近 {0} 个（共 {1} 个，按修改时间倒序；要看全部请用搜索或「我的资料」）': '최근 {0}개만 표시합니다 (전체 {1}개, 수정 시간 내림차순, 전체를 보려면 검색이나 "내 자료"를 사용하세요)',
  '只列出最近的 10 条磁盘会话（没有消息的空会话不列）。': '디스크의 최근 10개 세션만 표시합니다(메시지가 없는 빈 세션은 제외).',
  '只列本 App 真正会用到的那几项。点「申请」才会弹系统授权框 —— Android 不允许应用给自己开权限，也没有「一键全开」这种接口。': '이 앱이 실제로 쓰는 항목만 표시합니다. 「요청」을 눌러야 시스템 권한 창이 뜹니다 —— Android는 앱이 스스로 권한을 줄 수 없고 "전체 허용" API도 없습니다.',
  '只发最小的探测请求（免 Key 那条会真发一句话，1 个字）：不写任何文件、不读你的资料、不把结果上传给任何人。': '최소한의 탐색 요청만 보냅니다(Key 불필요 채널은 실제로 1토큰짜리 한 마디를 보냅니다). 파일을 쓰지 않고, 자료를 읽지 않으며, 결과를 누구에게도 업로드하지 않습니다.',
  '只在这个工作目录下适用：{0}': '이 작업 디렉터리에서만 적용: {0}',
  '只存本机安全区（Android Keystore）：不写进 models.json、不进日志、界面上也读不出来；填完点「测试并保存」。': '기기 보안 영역(Android Keystore)에만 저장합니다: models.json에 쓰지 않고, 로그에도 남기지 않으며, 화면에서도 읽을 수 없습니다. 입력한 뒤 「테스트 후 저장」을 누르세요.',
  '只存本机安全区：不写进 models.json、不进日志。': '이 기기의 보안 영역에만 저장됩니다: models.json에 기록되지 않고 로그에도 남지 않습니다.',
  '只把声音拿出来存成 .m4a（声音原样搬，不掉音质）': '소리만 꺼내서 .m4a로 저장(그대로 복사하므로 음질 저하 없음)',
  '只是从影视页的候选里去掉，不影响你的 Key。': '미디어 페이지 후보에서만 빠지고 Key는 그대로입니다.',
  '只是试一下：微信已不响应这条指令时，它会显示「页面无法访问」。': '그저 시도일 뿐입니다: WeChat이 이 명령에 응답하지 않으면 \'페이지를 열 수 없음\'이 표시됩니다.',
  '只有需要一个"更便宜/更小的模型去干粗活"时才需要改它；默认跟随当前会话。': '"더 저렴하거나 작은 모델에게 잡일을 맡기고 싶을 때"만 바꾸세요. 기본값은 현재 세션을 따릅니다.',
  '只能用字母、数字和横线；它会作为模型名出现在会话的模型面板里。': '영문, 숫자, 하이픈만 사용할 수 있습니다. 세션의 모델 패널에 모델 이름으로 표시됩니다.',
  '只能选图片。': '이미지만 선택할 수 있습니다.',
  '只能选图片（修图要一张图）。': '이미지만 선택할 수 있습니다(보정에는 사진이 필요합니다).',
  '只能选图片（参考图/首帧要图片）。': '이미지만 선택할 수 있습니다(참조/첫 프레임은 이미지).',
  '只需要填 API Key': 'API 키만 입력하면 됩니다',
  '可下载': '다운로드 가능',
  '可多选。网盘、微信、数据线拿到的模型文件都从这里进来，不需要存储权限。': '여러 개 선택 가능. 클라우드 드라이브·WeChat·케이블로 받은 모델 파일도 여기로 가져옵니다. 저장소 권한은 필요 없습니다.',
  '可用 · 系统识别服务': '사용 가능 · 시스템 인식 서비스',
  '可用 · 设备端离线识别': '사용 가능 · 기기 내 오프라인 인식',
  '可看图': '이미지 인식',
  '可选模型共 {0} 个 —— 在下面的列表里点一下就会加进这里。': '선택 가능한 모델 {0}개 — 아래 목록에서 누르면 여기에 추가됩니다.',
  '可选的图像模型': '선택 가능한 이미지 모델',
  '可选的视频模型': '선택 가능한 동영상 모델',
  '右上': '오른쪽 위',
  '右下': '오른쪽 아래',
  '各厂家的 Key（点一下就能填）': '업체별 Key(탭해서 입력)',
  '各通道都是正常的。': '모든 채널이 정상입니다.',
  '合成中…（{0} 镜）': '합성 중…({0}개 숏)',
  '同一份模型文件，区别只是"谁来算"：仅 CPU = 手机 CPU 算，慢但几乎所有手机都能跑；Vulkan = 交给手机 GPU 算，通常快 2–5 倍、更省电，需要 Android 9 以上。切换后端要重启服务。同一个模型两个后端各测一次，就能直接比出哪个快。': '같은 모델 파일이며 차이는 "누가 계산하는가"뿐입니다. CPU 전용 = 스마트폰 CPU(느리지만 거의 모든 기기에서 동작), Vulkan = 스마트폰 GPU(보통 2~5배 빠르고 전력 효율적, Android 9 이상 필요). 전환하려면 서비스를 다시 시작해야 합니다. 같은 모델을 두 백엔드에서 측정해 비교할 수 있습니다.',
  '后台运行依赖一个常驻通知把 App 留在后台。部分手机（尤其是国产 ROM 的省电策略）仍会杀掉进程，建议到系统设置里关闭本 App 的电池优化。App 被彻底杀掉期间不会触发，恢复后会把错过的记录标成「已错过」。': '백그라운드 실행은 상시 알림으로 앱을 살려 둡니다. 일부 휴대폰(특히 중국 ROM의 절전 정책)은 그래도 프로세스를 종료합니다. 시스템 설정에서 이 앱의 배터리 최적화를 꺼 두는 것을 권장합니다. 앱이 완전히 종료된 동안에는 실행되지 않고, 복귀 후 놓친 기록은 「놓침」으로 표시됩니다.',
  '后天 {0}:{1}': '모레 {0}:{1}',
  '含视觉编码器（mmproj）': '비전 인코더(mmproj) 포함',
  '含运行环境': '실행 환경 포함',
  '启动': '시작',
  '启动 node 解包失败：{0}': '압축 해제용 node 실행 실패: {0}',
  '启动后自动检查': '시작할 때 자동 확인',
  '启动失败：{0}': '시작 실패: {0}',
  '启动次数：{0}': '실행 횟수: {0}',
  '启用 TLS 时必须填证书指纹（电脑端启动桥时会打印）': 'TLS를 사용할 때는 인증서 지문이 필요합니다 (컴퓨터에서 브리지를 시작할 때 출력됩니다)',
  '启用免 Key 免费模型': 'Key 불필요 무료 모델 사용',
  '启用社区免费通道': '커뮤니티 무료 채널 사용',
  '响应不是 JSON': '응답이 JSON이 아닙니다',
  '喵～今天想聊点什么？': '야옹~ 오늘은 무슨 얘기 할까?',
  '四': '사',
  '回「设置 → 模型」把「免费模型 · OpenCode Zen」打开一次（它会起代理），然后再点自检。': '「설정 → 모델」로 돌아가 「무료 모델 · OpenCode Zen」을 한 번 켜세요(프록시가 시작됩니다). 그런 뒤 자체 점검을 다시 실행하세요.',
  '回「设置 → 模型」点一次「获取模型」重新拉；一直拉不到就说明上游这条通道又变了，把自检结果发出去核对。': '「설정 → 모델」로 돌아가 「모델 가져오기」를 한 번 누르세요. 계속 비어 있다면 업스트림 채널이 또 바뀐 것이니 자체 점검 결과를 보내 확인하세요.',
  '回创作台': '스튜디오로 돌아가기',
  '因为上一轮没回完': '이전 턴이 완료되지 않았기 때문',
  '因为对话历史对不上': '대화 기록이 일치하지 않았기 때문',
  '因为换了模型或参数': '모델이나 매개변수가 바뀌었기 때문',
  '因为系统提示变了': '시스템 프롬프트가 바뀌었기 때문',
  '国内集群是「冰糖」': '중국 클러스터는 「冰糖」',
  '图像 / 视频模型': '이미지 / 동영상 모델',
  '图像 / 视频走哪家，就用哪家的 Key；存的位置和「云端大模型」**同一个**，在哪边填都认。': '이미지/동영상이 어느 업체를 거치든 그 업체의 Key를 씁니다. 저장 위치는 「클라우드 대형 모델」과 **같은 곳**이라 어느 쪽에서 입력해도 적용됩니다.',
  '图像模型': '이미지 모델',
  '图像用 aspect_ratio，不用 size': '이미지는 size가 아니라 aspect_ratio를 사용합니다',
  '图像请求的形状**按各家的文档写**（size 是像素值还是 1K/2K 档位、参考图放哪、要不要 response_format 都不同）—— 本机没有这些厂家的 Key，**能不能通要试**；失败会把上游原话显示出来。': '이미지 요청 형식은 **각 사 문서를 따릅니다**(`size`가 픽셀인지 1K/2K 단계인지, 참조 이미지 위치, `response_format` 필요 여부가 모두 다릅니다) —— 이 기기에는 해당 공급사의 Key가 없으므로 **되는지는 시도해 봐야 합니다**. 실패하면 업스트림 원문을 그대로 보여 줍니다.',
  '图形': '이미지',
  '图形模型': '이미지 모델',
  '图片文件已不在': '이미지 파일이 없습니다',
  '图生图专家': '이미지 편집 전문가',
  '在「生图」或「生视频」里生成一个，它会自动出现在这里。': '이미지/동영상 생성에서 만들면 여기에 표시됩니다.',
  '在「设置 → 图像 / 视频模型」里可以添加别的模型。⚠️ 请求形状按各家的文档写（生图 / 生视频各一套：端点、参数名、轮询都不一样），**能不能通要试** —— 失败会把上游原话显示出来。': '「설정 → 이미지 / 동영상 모델」에서 다른 모델을 추가할 수 있습니다. ⚠️ 요청 형식은 각 사 문서를 따릅니다(이미지용과 동영상용이 따로: 엔드포인트, 파라미터 이름, 폴링이 다릅니다). **되는지는 시도해 봐야 합니다** —— 실패하면 업스트림 원문을 그대로 보여 줍니다.',
  '在下面输入第一条消息。\nAgent 会在你的电脑上读写文件、执行命令。': '아래에 첫 메시지를 입력하세요.\nAgent가 컴퓨터에서 파일을 읽고 쓰고 명령을 실행합니다.',
  '在工作区里生成的文件会出现在这里。\n{0}工作区：{1}': '작업 공간에서 생성된 파일이 여기에 표시됩니다.\n{0}작업 공간: {1}',
  '在手机上画界面草图（Material 3），导出成给 AI 的描述（随包自带，打开即用）': '휴대폰에서 UI 스케치(Material 3)를 그리고 AI용 설명으로 내보냅니다(동봉, 바로 사용)',
  '在手机上跑，不联网、不花额度': '휴대폰에서 실행: 네트워크와 과금 불필요',
  '在某一秒截一张图当封面（.jpg）': '특정 초의 한 프레임을 표지 이미지로 캡처(.jpg)',
  '在浏览器里打开它注册 / 登录，把 Key 复制回来，再点这一行的「填 Key」贴进来。': '브라우저에서 열어 가입/로그인한 뒤 키를 복사해 오고, 이 행의 「키 입력」을 눌러 붙여 넣으세요.',
  '在电脑上双击 dsh-mobile 目录里的：\n\n  start-bridge.cmd      （启用 TLS，推荐）\n  start-bridge-ws.cmd   （明文，仅私有网络）\n  pair-phone.cmd        （生成配对码）\n': '컴퓨터에서 dsh-mobile 폴더 안의 다음을 더블클릭하세요:\n\n  start-bridge.cmd      (TLS 사용, 권장)\n  start-bridge-ws.cmd   (평문, 사설 네트워크 전용)\n  pair-phone.cmd        (페어링 코드 생성)\n',
  '地址已经内置好了 —— 不用你填端点。': '주소는 이미 내장되어 있습니다 — 엔드포인트를 입력할 필요가 없습니다.',
  '地址或模型不存在：请检查 Base URL 是否写对（例如 LongCat 必须是 /openai/v1，漏掉 openai 就会 404）。': '주소 또는 모델이 없습니다: Base URL을 확인하세요(예: LongCat은 /openai/v1이어야 하며 openai를 빼면 404).',
  '域名解析失败：请检查 Base URL 有没有写错，以及当前网络能否上网。': '도메인 해석 실패: Base URL이 잘못되지 않았는지, 현재 네트워크가 인터넷에 연결되는지 확인하세요.',
  '基于 DeepSeek Harness 的本地运行时，除模型接口外不依赖任何服务器。': 'DeepSeek Harness 기반 로컬 런타임으로, 모델 API 외에는 어떤 서버에도 의존하지 않습니다.',
  '填 Key': 'Key 입력',
  '壁纸': '배경화면',
  '壁纸已换上。': '배경화면을 적용했습니다.',
  '声音是**原样搬过去**的（不重新编码），存成 .m4a —— 安卓/苹果/电脑都能放。': '소리는 **그대로 복사**되어(재인코딩 없음) .m4a로 저장됩니다 — 안드로이드/아이폰/PC 어디서나 재생됩니다.',
  '备注：卡在哪一步、哪里别扭、想改什么': '메모: 어디서 막혔는지, 어색한 점, 바꾸고 싶은 것',
  '备用 Key {0}（内容不显示）': '백업 Key {0}(내용 표시 안 함)',
  '备用 Key（多账号）· 已添加 {0} 把': '백업 Key(여러 계정) · {0}개 추가됨',
  '复制下面这段，到「首页」的任意会话里发出去（把括号里的内容换成你的）。模型看到就会走这条流程。': '아래 텍스트를 복사해 「홈」의 아무 세션에 보내세요(괄호 안은 직접 바꿔 주세요). 모델이 이 흐름대로 진행합니다.',
  '复制公众号 ID': '공식 계정 ID 복사',
  '复制日志路径': '로그 경로 복사',
  '复制起始指令': '시작 프롬프트 복사',
  '复制路径': '경로 복사',
  '外观': '외관',
  '外观与语言': '모양 및 언어',
  '多人协同，打造超级团队': '여럿이 함께 협력해 슈퍼 팀을 만들어 보세요',
  '多模态': '멀티모달',
  '多模态模型"看图"靠它 —— 它是单独一个文件（几百 MB），所以下载时会跟本体一起下（清单里叫"伴生文件"）。少了下半截，模型就只能聊天、看不了图。': '멀티모달 모델이 "보는" 역할을 하는 별도 파일(수백 MB)이라 본체와 함께 다운로드됩니다(매니페스트에서는 "동반 파일"). 없으면 대화는 되지만 이미지를 볼 수 없습니다.',
  '多模态模型下完可以对话，但图片还发不进模型：App 目前只发纯文本。引擎其实已经带了看图能力，只差"启动时指一下视觉编码器"和"把图片发出去"这两处接线，后面版本补。': '다운로드 후 멀티모달 모델과 대화는 가능하지만 이미지는 아직 전달되지 않습니다(현재 앱은 텍스트만 전송). 엔진에는 이미 비전 기능이 있으므로 "시작 시 비전 인코더 지정"과 "이미지 전송" 두 곳만 연결하면 됩니다. 이후 버전에서 지원합니다.',
  '多模态（能看图）': '멀티모달(이미지를 볼 수 있음)',
  '大': '크게',
  '太多了，只显示最新的 {0} 个；更早的可在「资料库」里按文件看。': '너무 많아 최신 {0}개만 표시합니다. 그 이전 것은 라이브러리에서 파일로 볼 수 있습니다.',
  '失败': '실패',
  '套餐(token plan)': '요금제(token plan)',
  '如实说明：App 里**看不了** .pptx 的样子（没有 Office 组件）。生成后在「资料库」里能找到它，用「用其它应用打开」交给手机上的 WPS / Office，或者直接分享出去。': '분명히 말씀드리면: 이 앱에서는 .pptx의 모양을 **볼 수 없습니다**(Office 구성 요소 미포함). 생성 후 「자료실」에서 찾을 수 있고, 「다른 앱으로 열기」로 휴대폰의 WPS / Office에 넘기거나 바로 공유하세요.',
  '如实说明：上游那几个 python 自检脚本（几何校验、drawio/mermaid 导入）**没有随包**（手机上没 python），所以那几步用不了；上游的 211 个示例图也没随包（省 4.4 MB）。画法规范在技能里是完整的。': '솔직히: 업스트림 python 자체 점검 스크립트(기하 검증, drawio/mermaid 가져오기)는 **포함하지 않았습니다**(휴대폰에 python이 없음). 따라서 그 단계는 사용할 수 없습니다. 업스트림 예시 그림 211개도 포함하지 않았습니다(4.4 MB 절약). 그리는 규칙은 스킬 안에 완전히 들어 있습니다.',
  '如果提示"安装包里没有 assets/studio"，说明这一版没把APP界面设计台打进去，需要重新构建 App。': '"설치 패키지에 assets/studio가 없습니다"라고 나오면 이 빌드에 앱 UI 디자인 스튜디오가 포함되지 않은 것이므로 앱을 다시 빌드해야 합니다.',
  '如果要把它发出去/上架，注意商店对**AI 生成内容**的要求（标记、年龄分级），这块要你自己把握。': '배포하거나 스토어에 올린다면 스토어의 **AI 생성 콘텐츠** 요건(표시, 연령 등급)을 확인하세요. 이 부분은 직접 판단하셔야 합니다.',
  '子会话用哪个模型': '하위 세션이 쓸 모델',
  '子智能体': '하위 에이전트',
  '字号': '글자 크기',
  '存在系统安全存储，不会写进命令行': '시스템 보안 저장소에 보관되며 명령줄에 기록되지 않습니다',
  '存好后在微信「扫一扫 → 右上角相册」里选这张图。': '저장한 뒤 WeChat에서 \'스캔 → 오른쪽 위 앨범\'을 열고 이 이미지를 선택하세요.',
  '存相册没成功（{0}）。可以改用「复制公众号 ID」，或直接截屏这张二维码。': '앨범 저장에 실패했습니다({0}). \'공식 계정 ID 복사\'를 쓰거나 이 QR 코드를 캡처하세요.',
  '安全提醒：桥拥有你电脑的命令执行权。优先使用 Tailscale 私有网络，不要在公网上做端口转发，也不要把配对码或证书指纹发给别人。': '보안 주의: 브리지는 사용자의 컴퓨터에서 명령을 실행할 수 있는 권한을 가집니다. Tailscale 같은 사설 네트워크를 우선하고, 공용 인터넷에 포트 포워딩하지 말며, 페어링 코드나 인증서 지문을 다른 사람에게 보내지 마세요.',
  '安全连接失败': '보안 연결 실패',
  '安装包所在的位置没有对系统开放（这是应用自身的配置问题，请把运行日志发给开发者）。': '설치 파일이 있는 위치가 시스템에 공개되어 있지 않습니다(앱 자체의 설정 문제입니다. 실행 로그를 개발자에게 보내 주세요).',
  '安装失败（没有更多信息）': '설치 실패 (추가 정보 없음)',
  '安装插件': '플러그인 설치',
  '安装未知应用': '알 수 없는 앱 설치',
  '安装（会弹出系统安装界面）': '설치(시스템 설치 화면이 열립니다)',
  '完全不渲染 —— 唯一能彻底不看到英文思考的办法': '아예 그리지 않음 — 영어 생각을 완전히 보지 않는 유일한 방법',
  '完全在本机算出来的配音：**不用联网、不用任何 Key、免费**。代价要说清：① 第一次要**下一次模型**（31.5 MB，装好后占约 32 MB 磁盘）；② 音色**比云端机械**（多说话人离线模型就是这样）；③ 手机上的实际速度**还没在真机上量过**。': '전적으로 이 기기에서 계산하는 더빙: **네트워크 불필요, Key 불필요, 무료**. 대가는 분명히 밝힙니다: ① 처음에 **모델을 한 번 내려받아야** 합니다 (31.5 MB, 설치 후 약 32 MB); ② 음성은 **클라우드보다 기계적**입니다 (다화자 오프라인 모델의 일반적 특성); ③ 실기기에서의 실제 속도는 **아직 측정하지 않았습니다**.',
  '官方 CLI 的默认音色': '공식 CLI 기본 음성',
  '官方直连。若你的 Key 是 Anthropic 协议的，端点要改成 https://api.deepseek.com/anthropic。': '공식 직결 연결. Key가 Anthropic 프로토콜이라면 엔드포인트를 https://api.deepseek.com/anthropic 으로 변경하세요.',
  '定位': '위치',
  '定时任务': '예약 작업',
  '实测 {0} tok/s': '실측 {0} tok/s',
  '实测 {0} tok/s（首字 {1} ms）': '실측 {0} tok/s(첫 토큰 {1} ms)',
  '实测 {0} tok/s（首字 {1} ms），能用但偏慢': '실측 {0} tok/s(첫 토큰 {1} ms) — 사용 가능하지만 느린 편입니다.',
  '实测 {0} tok/s，一句话要等十几秒，基本没法用': '실측 {0} tok/s — 한 문장에 10초 이상 걸려 사실상 사용할 수 없습니다.',
  '实测完成：{0}': '실측 완료: {0}',
  '实验通道 · OpenCode Zen（第三方通道）': '실험 채널 · OpenCode Zen(서드파티)',
  '审讯室': '심문실',
  '宿主返回失败': '호스트가 실패를 반환했습니다',
  '对方的目标：听出他**真正**的问题，并在节目结束前让他自己说出来。如果时间到了他还没说出口，就按"这一夜没能留住他"收尾，不要硬圆。': '상대의 목표: 그의 **진짜** 문제를 알아듣고, 방송이 끝나기 전에 본인 입으로 말하게 하는 것. 시간이 다 되어 말하지 못했다면 "그 밤은 그를 붙잡지 못했다"로 마무리하고, 억지로 매듭짓지 마세요.',
  '对方的目标：在 8 轮之内判断你到底有没有在说谎，然后说「我知道了」。到那一刻你必须给出真相（或者揭穿他的误判），然后这局结束。': '상대의 목표: 8라운드 안에 당신이 거짓말하는지 판단하고 "알겠어요"라고 말하는 것. 그 순간 당신은 진실을 밝히거나(혹은 잘못된 판단을 뒤집거나) 해야 하고, 그러면 이 판은 끝납니다.',
  '对方的目标：在氧气耗尽前做完三个决定（先修哪条线、要不要丢一个货舱、要不要叫醒同伴）。三个都定了这局就结束，你按结果给一个明确的结局。': '상대의 목표: 산소가 떨어지기 전에 세 가지를 결정하는 것(어느 계통을 먼저 고칠지, 화물칸을 버릴지, 동료를 깨울지). 셋 다 정해지면 이 판은 끝나고, 당신은 결과에 맞춰 분명한 결말을 제시합니다.',
  '对话已清空': '대화를 지웠습니다',
  '对话生成': '대화 생성',
  '对话缓存：省掉重算 {0} 次 · 整段重建 {1} 次': '대화 캐시: 재계산 생략 {0}회 · 전체 재구축 {1}회',
  '对话缓存：还没开始对话': '대화 캐시: 아직 대화가 없습니다',
  '对话越长越吃上下文：DSH 每轮光系统提示就要约 7k tokens，所以别选 4k（会一直报"上下文不够"）。越大越吃内存，服务和测速都用这个档位；改了要重启服务。': '대화가 길수록 컨텍스트를 더 씁니다: DSH는 매 턴 시스템 프롬프트만으로 약 7k 토큰을 사용하므로 4k를 선택하지 마세요("컨텍스트 부족"이 계속 납니다). 클수록 메모리를 더 씁니다. 서비스와 측정 모두 이 설정을 사용하며, 변경 후에는 재시작이 필요합니다.',
