  '已把本机模型移出轮换池：{0}。本机模型只在手机上跑，不进池子（你的要求）。': '온디바이스 모델을 로테이션 풀에서 제거했습니다: {0}. 온디바이스 모델은 휴대폰에서만 실행되므로 풀에 넣지 않습니다(요청하신 대로).',
