  '我们来玩一局「有目标的角色扮演」。\n\n【你演】{0}\n\n{1}\n\n【场景】{2}\n\n【目标与结束条件】{3}\n\n{4}\n\n现在开始：你先说第一句。': '\'목표가 있는 역할극\' 한 판을 해 봅시다.\n\n【당신이 연기】{0}\n\n{1}\n\n【장면】{2}\n\n【목표와 종료 조건】{3}\n\n{4}\n\n지금 시작합니다: 당신이 첫 마디를 하세요.',
  '我刚{0}：{1}\n\n【自动看图结果 · 由内置免费视觉链生成，供参考】\n{2}': '방금 {0}: {1}\n\n[자동 이미지 분석 결과 · 내장 무료 비전 체인 생성, 참고용]\n{2}',
  '我刚{0}：{1}\n（这是二进制文件，我这边只有 read 工具，能否理解取决于模型的视觉能力）': '방금 {0}: {1}\n(이것은 바이너리 파일입니다. 여기에는 read 도구만 있어서, 이해할 수 있는지는 모델의 비전 능력에 달려 있습니다)',
  '我希望你怎么回答': '어떻게 답해 주길 바라는지',
  '我帮你用泡泡猫的DSH，把想法做成成品': '泡泡猫의 DSH로 아이디어를 결과물로 만들어 드립니다',
  '我是谁：语言、职业、长期身份': '나는 누구인지: 언어, 직업, 장기적 정체성',
  '我的手机': '내 휴대폰',
  '我的模型': '내 모델',
  '我的资料': '내 자료',
  '我的项目': '내 프로젝트',
  '或者用浏览器下载': '또는 브라우저에서 다운로드',
  '截第几秒（如 0:03，留空=开头）': '몇 초 지점(예: 0:03, 비우면 처음)',
  '所有下载源都没成功，最后一个是：{0}': '모든 다운로드 소스가 실패했습니다. 마지막은: {0}',
  '所有已注册的模型（点一下就进池子{0}）': '등록된 모든 모델(탭하면 풀 {0}에 들어갑니다)',
  '手上已有视频：剪一段 / 拼接 / 抽音频 / 抽一帧 / 压小（本机跑，不联网）': '이미 가진 영상에 대해: 구간 자르기 / 이어 붙이기 / 오디오 추출 / 프레임 캡처 / 용량 줄이기(모두 이 기기에서, 네트워크 불필요)',
  '手上已经有视频之后的几刀：剪一段、把几段拼起来、把声音抽出来、截一张封面、压小一点好发出去。**全部在本机跑**（用随包的 ffmpeg），不联网、不花任何额度。除了「压小」和「精确剪」要重新编码，其余几刀都是几秒就完事、也不掉画质。': '영상이 이미 있을 때 필요한 몇 가지: 구간 자르기, 여러 클립 이어 붙이기, 오디오 추출, 표지 프레임 캡처, 보내기 좋게 용량 줄이기. **모두 이 기기에서 실행**됩니다(동봉된 ffmpeg 사용) — 네트워크도, 사용량도 들지 않습니다. "용량 줄이기"와 "정확히 자르기"만 재인코딩이고, 나머지는 몇 초면 끝나며 화질도 그대로입니다.',
  '手动添加': '직접 추가',
  '手机上只能做**网页游戏**（HTML/JS）—— 它能在本 App 的资料库里直接打开玩。Unity / Godot 那类做不到，要如实说。': '휴대폰에서는 **웹 게임**(HTML/JS)만 만들 수 있습니다 — 이 앱의 자료실에서 바로 열어 즐길 수 있습니다. Unity / Godot 같은 빌드는 불가능하며, 그 점은 솔직히 말합니다.',
  '手机权限': '휴대폰 권한',
  '打不开网页：{0}': '웹페이지를 열 수 없습니다: {0}',
  '打开「安装未知应用」设置': '‘알 수 없는 앱 설치’ 설정 열기',
  '打开专家中心': '전문가 센터 열기',
  '打开发布页': '릴리스 페이지 열기',
  '打开后，**会话里的 AI 会自己去查资料**（用户 2026-10-15 选定的方案 B）：App 在建会话时给运行时挂一个 `AnySearch` 的 MCP 服务器，模型于是能搜网页、并把来源链接写进回答。\n\n**不用填 Key 也能搜** —— 匿名层就能用（只是限流低）；想要更稳的额度，可以用邮箱在 [anysearch.com](https://anysearch.com) 换一把免费 Key（可选，填在下面）。': '켜면 **세션 안의 AI가 스스로 자료를 찾습니다**(2026-10-15 선택한 방안 B): 앱이 세션 생성 시 런타임에 `AnySearch` MCP 서버를 붙여, 모델이 웹을 검색하고 답변에 출처 링크를 씁니다.\n\n**검색에 Key는 필요 없습니다** — 익명 레이어가 바로 동작합니다(속도 제한은 낮음). 더 안정적인 할당량이 필요하면 [anysearch.com](https://anysearch.com)에서 이메일로 무료 Key를 받으세요(선택 사항, 아래에 붙여 넣기).',
  '打开后，**会话里的 AI 可以"分人做事"**：把一块子任务交给另一个 agent 实例（**它有自己的上下文窗口**），干完只把结论拿回来 —— 主会话因此不会被中间过程撑爆，也能并行推进几件事。': '켜면 **세션 안의 AI가 일을 나눠 맡길 수 있습니다**: 작업의 일부를 다른 에이전트 인스턴스(**자체 컨텍스트 창**)에 넘기고 결론만 받아옵니다 — 메인 세션이 중간 과정으로 부풀지 않고 병행도 가능합니다.',
  '打开后，App 会在本机起一个小小的**转发代理**，把请求按**官方 CLI 的样子**发到 OpenCode 的匿名免费额度，并把拿到的免费模型直接加进你的模型列表 —— **不用配置任何 Key**。\n\n⚠️ 只是想"不用 Key 就能聊"的话，**用上面那条（免 Key 免费模型）就好** —— 这条 Zen 通道自 2026-09-16 起被上游改过 6 次门禁，时好时坏（2026-10-16 本机实测又能用了，但它随时可能再变）；想知道此刻通不通，点下面的「通道自检」。': '켜면 앱이 기기 안에 작은 **전달 프록시**를 띄워, 요청을 **공식 CLI의 형태**로 OpenCode 익명 무료 한도에 보내고, 받아온 무료 모델을 모델 목록에 그대로 추가합니다 — **설정할 Key가 없습니다**.\n\n⚠️ \'Key 없이 대화\'만 원한다면 **위 항목(무료 모델, Key 불필요)을 쓰세요** — 이 Zen 채널은 2026-09-16 이후 게이트가 6번 바뀌어 될 때도 안 될 때도 있습니다(2026-10-16 실기기 측정에서는 다시 됐지만 언제든 또 바뀔 수 있습니다). 지금 되는지 보려면 아래 「채널 자체 점검」을 누르세요.',
  '打开失败：{0}': '열기 실패: {0}',
  '打开没成功：{0}': '열지 못했습니다: {0}',
  '打开记忆': '기억 열기',
  '执行中…': '실행 중…',
  '执行命令': '명령 실행',
  '执行异常：{0}': '실행 오류: {0}',
  '执行环境被沙箱挡住了（Android 上不该出现）。\n下一步：回「设置 → 模型」随便切一次模型，App 会重写运行配置并补上「danger-full-access」，之后重发即可。': '실행 환경이 샌드박스에 막혔습니다(Android에서는 나오면 안 되는 상황입니다).\n다음 단계: "설정 → 모델"에서 아무 다른 모델로 한 번 전환하세요. 앱이 실행 구성을 다시 쓰고 "danger-full-access"를 채워 넣습니다. 그런 다음 다시 보내면 됩니다.',
  '执行结束': '실행 종료',
  '扩写失败。': '확장에 실패했습니다.',
  '扩展名是 .{0}，但内容里有 NUL 字节 —— 按文本渲染会是乱码，所以这里如实告诉你而不是硬渲染。\n（{1}）\n\n{2}': '확장자는 .{0}이지만 내용에 NUL 바이트가 있습니다 — 텍스트로 렌더링하면 깨져 나오므로, 억지로 렌더링하지 않고 그대로 알려드립니다.\n({1})\n\n{2}',
  '扫描之后这个文件被移动或删除了。\n{0}': '스캔한 뒤 이 파일이 이동되거나 삭제되었습니다.\n{0}',
  '扫描失败': '스캔 실패',
  '批量重命名 / 分类移动': '일괄 이름 변경 / 분류 이동',
  '找不到入口时手动找：{0}': '입구를 못 찾겠으면 직접 여세요: {0}',
  '找不到这个文件：「{0}」——可能还没生成出来，或被改名/删除了': '이 파일을 찾을 수 없습니다: "{0}" — 아직 생성되지 않았거나, 이름이 바뀌었거나 삭제되었을 수 있습니다',
  '找不到这条记忆（可能已被删除）': '해당 기억을 찾을 수 없습니다(이미 삭제되었을 수 있습니다)',
  '技术细节': '기술 세부 정보',
  '技术细节（原始参数）': '기술 세부 정보(원시 파라미터)',
  '技能': '스킬',
  '技能 {0}': '스킬 {0}',
  '技能名（kebab-case）': '스킬 이름(kebab-case)',
  '技能名：{0}': '스킬 이름: {0}',
  '技能正文（Markdown 指令）': '스킬 본문(Markdown 지침)',
  '技能目录': '스킬 폴더',
  '把 {0} 加进池子「{1}」': '{0}을(를) 풀 "{1}"에 추가',
  '把**一本小说**改编成**一个能在浏览器里玩的游戏**。它不是"AI 自己玩"，也不是"AI 对战" —— 是一套有原著依据的改编流程：每一步都要引原文，最后要拿运行证据说话。': '**소설 한 권**을 **브라우저에서 즐길 수 있는 게임**으로 바꿉니다. "AI가 혼자 노는 것"도 "AI 대전"도 아니고, 원작에 근거를 두는 각색 워크플로입니다. 각 단계에서 원문을 인용하고, 마지막에는 실행 증거로 증명합니다.',
  '把**每行一句话**当成一个镜头，拼成一条短剧：每镜一句配音、一张画面、一行字幕。想要每镜不同画面就打开下面那个开关（会用生图按该行文本画一张）。': '**한 줄이 한 숏**입니다: 숏마다 음성 한 줄, 화면 한 장, 자막 한 줄로 숏드라마를 만듭니다. 숏마다 다른 화면을 원하면 아래 스위치를 켜세요(해당 줄 텍스트로 이미지를 생성합니다).',
  '把一本小说改编成能在浏览器里玩的游戏（七个阶段）': '소설을 브라우저에서 즐기는 게임으로(7단계)',
  '把一段**文稿**变成一条带配音和字幕的视频：自动分段 → 每段配音 → 字幕画在画面上 → 合成。适合口播、解说、知识分享。': '**원고**를 음성과 자막이 있는 동영상으로 만듭니다: 자동 분할 → 부분별 음성 → 화면에 자막 그리기 → 합성. 내레이션, 해설, 지식 공유에 적합.',
  '把一段动作描述生成短视频': '동작 설명으로 짧은 영상 생성',
  '把下面这些材料做成 8 页左右的工作汇报（材料我贴在后面）': '아래 자료를 8장 정도의 업무 보고 슬라이드로 만들어 주세요(자료는 뒤에 붙여 넣습니다).',
  '把二维码存到相册': 'QR 코드를 앨범에 저장',
  '把几段按你排的顺序接成一条（要求参数一致，否则要勾重编码）': '정한 순서대로 여러 클립을 하나로 이어 붙입니다(형식이 같아야 하며, 다르면 재인코딩을 켜세요)',
  '把勾选的 {0} 个加入我的模型': '선택한 {0}개를 내 모델에 추가',
  '把小说做成游戏': '소설을 게임으로 만들기',
  '把材料变成问答卡片': '자료를 문답 카드로 변환',
  '把自检结果发给开发者看一下（里面没有 Key）。': '자체 점검 결과를 개발자에게 보내 확인하세요(Key는 들어 있지 않습니다).',
  '把要念的稿子贴进来。例如：\n大家好，今天讲三个提高效率的小习惯……': '읽을 원고를 붙여 넣으세요. 예:\n안녕하세요, 오늘은 효율을 높이는 작은 습관 세 가지를 말씀드립니다…',
  '把这两个方案做成一页对比：左边 A 方案、右边 B 方案': '이 두 안을 한 장 비교 슬라이드로 만들어 주세요: 왼쪽 A안, 오른쪽 B안.',
  '把这个模型放进哪个池子？': '이 모델을 어느 풀에 넣을까요?',
  '把这个登录流程画成时序图：用户、App、认证服务、数据库': '이 로그인 흐름을 시퀀스 다이어그램으로: 사용자, 앱, 인증 서비스, 데이터베이스',
  '把这段时间的产物理成周报': '이 기간의 산출물을 주간 보고서로 정리',
  '折叠': '접기',
  '抽一帧': '프레임 캡처',
  '抽音频': '오디오 추출',
  '拉到 {0} 个模型 —— 勾好再一次性加入，不会有上限、也不会顶掉别家。': '{0}개 모델을 가져왔습니다 — 체크한 뒤 한 번에 추가하세요. 상한이 없고 다른 곳의 모델을 밀어내지도 않습니다.',
  '拉到 {0} 个模型，勾选后保存。': '{0}개 모델을 가져왔습니다. 체크한 뒤 저장하세요.',
  '拉到 {0} 个音色。': '음성 {0}개를 가져왔습니다.',
  '拉取中…': '가져오는 중…',
  '拉取音色': '음성 가져오기',
  '拉取音色失败 HTTP {0}：{1}': '음성 가져오기 실패 HTTP {0}: {1}',
  '拉取音色失败：{0}': '음성 가져오기 실패: {0}',
  '拉取音色超时了（{0} 秒）。': '음성 가져오기가 시간 초과되었습니다({0}초).',
  '拉起安装界面失败。': '설치 화면을 열지 못했습니다.',
  '拉起安装界面失败：{0}': '설치 화면을 열지 못했습니다: {0}',
  '拍照': '사진 촬영',
  '拒绝': '거부',
  '拼接': '이어 붙이기',
  '拼接**要求几段的画面/声音格式一致**（同一次拍摄的通常就行）。不一致时不会硬拼（硬拼的成品画面会中途变形），而是让你勾「参数不一致时重新编码」——那就慢了。': '이어 붙이기는 **클립들의 영상/오디오 형식이 같아야** 합니다(같은 촬영본이면 보통 문제없음). 다르면 억지로 붙이지 않고(억지로 붙이면 중간에 화면이 뒤틀립니다) "형식이 다르면 재인코딩"을 켜라고 안내합니다 — 그만큼 느립니다.',
  '拿不到「运行环境」的下载信息（网络不通或更新源连不上），所以这次装不了运行环境。你可以稍后重试；也可以把 runtime.zip 放到这台手机的 {0} 目录下，再点一次「开始准备」。': '실행 환경의 다운로드 정보를 가져오지 못했습니다(네트워크 불통 또는 업데이트 소스 연결 실패). 이번에는 준비할 수 없습니다. 잠시 후 다시 시도하거나, runtime.zip을 이 휴대폰의 {0} 폴더에 넣고 ‘준비 시작’을 다시 누르세요.',
  '拿到 {0} 个模型': '모델 {0}개 확보',
  '按 OpenAI 兼容形状发：size 用像素值，参考图放顶层 image 数组。': 'OpenAI 호환 형식으로 전송합니다: `size`는 픽셀 값이고 참조 이미지는 최상위 `image` 배열에 넣습니다.',
  '按住说话': '길게 눌러 말하기',
  '按量付费（充值）账号用这个端点。': '종량제(충전) 계정은 이 엔드포인트를 사용하세요.',
  '换一个': '변경',
