  '未配置模型': '모델 미설정',
  '本': '개',
  '本 App 随包包含以下第三方组件：\n\n· ffmpeg 7.1（含 libx264）—— 用于口播/短剧的拼接、转码、混音、加字幕。以 GPLv2 或更高版本（GPLv2+）授权，因为启用了 libx264（GPL）。\n  许可全文：https://www.gnu.org/licenses/old-licenses/gpl-2.0.html\n  相应源码：https://ffmpeg.org/download.html 与 https://code.videolan.org/videolan/x264\n  本 App 未修改其源码，只做了针对 Android arm64 的编译（构建参数随仓库的 install/build-ffmpeg-android.sh 一并提供）。\n\n· frontend-design 与 discernment-nudge —— 两个随包「技能」（写给模型看的流程说明），搬自 Anthropic 官方开源技能库（github.com/anthropics/skills），以 Apache-2.0 授权。\n  本 App 已修改其文字：翻译成中文，并针对手机端的执行环境改写（本机没有 python；原版里"截图回看"这类做不到的步骤已删掉）。\n  许可全文随包提供：assets/skills/frontend-design/LICENSE.txt 与 assets/skills/discernment-nudge/LICENSE.txt\n  许可全文链接：https://www.apache.org/licenses/LICENSE-2.0\n\n· novel-to-game / novel-game-analyze / game-concept / game-world-design / game-art-direction / game-build / game-qa（七个随包技能）—— 来自 NovelToGame v0.4.0（zenstory.ai 的「有原著依据的小说改编游戏工作流」），以 MIT 授权。\n  本 App 只改写了两处：技能简介改写成一行中文、正文开头加署名区块；正文与参考文件一字未改。\n  许可全文随包提供：assets/skills/novel-to-game/LICENSE.txt\n\n· diagram-design —— 画图表技能（44 种图型，出自包含的 HTML + 内联 SVG），来自 diagram-design v2.6（github.com/cathrynlavery/diagram-design），以 MIT 授权。\n  本 App 只随包了必需部分（技能正文 + 方法文档 + 五套模板 + 图标）；上游的 211 个示例图与 5 个 python 脚本没有随包（原因写在技能正文的署名区块里）。\n  许可全文随包提供：assets/skills/diagram-design/LICENSE.txt\n\n· Android 运行时自带的系统组件（按 Android 系统许可）。\n· DeepSeek Harness 及各 dsh-* 子包（按各自许可）。': '이 App에 포함된 서드파티 구성 요소：\n\n· ffmpeg 7.1(libx264 포함) — 내레이션/숏드라마의 연결·트랜스코딩·오디오 믹스·자막에 사용. libx264(GPL)를 활성화했으므로 GPLv2 이상(GPLv2+)으로 제공.\n  라이선스 전문: https://www.gnu.org/licenses/old-licenses/gpl-2.0.html\n  대응 소스: https://ffmpeg.org/download.html 및 https://code.videolan.org/videolan/x264\n  이 App은 소스를 수정하지 않았고 Android arm64용 빌드만 했습니다(빌드 인자는 저장소의 install/build-ffmpeg-android.sh에 포함).\n\n· frontend-design과 discernment-nudge — 함께 포함된 두 「스킬」(모델이 읽는 절차 문서). Anthropic 공식 오픈소스 스킬 저장소(github.com/anthropics/skills)에서 가져왔으며 Apache-2.0으로 제공.\n  이 App은 텍스트를 수정했습니다: 중국어 번역 및 휴대폰 실행 환경에 맞춘 재작성(이 기기에는 python이 없고, 원본의 「스크린샷으로 확인」 같은 단계는 삭제).\n  라이선스 전문은 패키지에 포함: assets/skills/frontend-design/LICENSE.txt 및 assets/skills/discernment-nudge/LICENSE.txt\n  라이선스 전문 링크: https://www.apache.org/licenses/LICENSE-2.0\n\n· novel-to-game / novel-game-analyze / game-concept / game-world-design / game-art-direction / game-build / game-qa(함께 포함된 7개 스킬) — NovelToGame v0.4.0(zenstory.ai의 원작 근거 소설→게임 워크플로)에서 왔으며 MIT 라이선스입니다.\n  이 App이 바꾼 것은 두 가지뿐입니다: 소개 문구를 한 줄 중국어로 바꾸고, 본문 맨 앞에 출처 표기를 추가했습니다. 본문과 참조 파일은 변경하지 않았습니다.\n  라이선스 전문은 패키지에 포함: assets/skills/novel-to-game/LICENSE.txt\n\n· diagram-design — 다이어그램 스킬(44종, 자체 완결 HTML + 인라인 SVG). diagram-design v2.6(github.com/cathrynlavery/diagram-design)에서 왔으며 MIT 라이선스입니다.\n  필요한 부분만 포함했습니다(SKILL.md + references/ + 템플릿 5종 + 아이콘). 업스트림 예시 그림 211개와 python 스크립트 5개는 포함하지 않았습니다(이유는 스킬 본문의 출처 표기에).\n  라이선스 전문은 패키지에 포함: assets/skills/diagram-design/LICENSE.txt\n\n· Android 런타임 기본 시스템 구성 요소(Android 시스템 라이선스).\n· DeepSeek Harness 및 각 dsh-* 하위 패키지(각자의 라이선스).',
