  '本地模型只做简单对话：不经过 DSH，不带系统提示、不带工具 —— 所以它不会像会话里那样乱答。': '로컬 모델은 간단한 대화 전용입니다. DSH를 거치지 않고 시스템 프롬프트와 도구를 쓰지 않습니다.',
  '本地模型崩溃记录（模型 | 后端：次数）—— 用于"闪退"定位：': '온디바이스 모델 충돌 기록(모델 | 백엔드: 횟수) — 강제 종료 진단용:',
  '本地模型已就绪：{0}': '온디바이스 모델 준비 완료: {0}',
  '本地模型服务': '온디바이스 모델 서비스',
  '本地模型服务没在运行': '로컬 모델 서비스가 실행 중이 아닙니다',
  '本地模型服务没在运行 —— 点「设置」启动它': '로컬 모델 서비스가 실행 중이 아닙니다 —— 「설정」에서 시작하세요',
  '本地模型服务没在运行：先回「本地大模型」页启动它，再回来聊。': '로컬 모델 서비스가 실행 중이 아닙니다. 「설정 → 로컬 대형 모델」에서 시작한 뒤 다시 오세요.',
  '本地模型服务：{0}': '로컬 모델 서비스: {0}',
  '本地模型服务：运行中': '로컬 모델 서비스: 실행 중',
  '本地模型的上下文不够：这一轮要 {0} tokens，但只给了 {1}。\n下一步：打开「设置 → 本地大模型（测试）」，在「本地模型服务」里把上下文调大一档（推荐 16k），再重新启动服务。': '로컬 모델의 컨텍스트가 부족합니다: 이번 턴에 {0} 토큰이 필요한데 {1}만 주어졌습니다.\n다음 단계: 「설정 → 로컬 대형 모델(테스트)」에서 「로컬 모델 서비스」의 컨텍스트를 한 단계 올리고(16k 권장) 서비스를 다시 시작하세요.',
  '本地运行时 · 非云端账户': '로컬 런타임 · 클라우드 계정 아님',
  '本机': '이 기기',
  '本机 · {0}': '이 기기 · {0}',
  '本机**不能**自动截 WebView 的图（Android 上它是平台视图，截出来常常是空白），所以这里由你玩过之后逐项勾选 —— 这份记录就是证据。': '이 기기는 WebView를 **자동으로 캡처할 수 없습니다**(Android에서는 플랫폼 뷰라 대개 빈 화면이 나옵니다). 그래서 플레이한 뒤 항목별로 체크해 주세요 — 이 기록이 증거입니다.',
  '本机代理没在跑': '기기 내 프록시가 실행 중이 아닙니다',
  '本机工作区': '이 기기의 워크스페이스',
  '本机播放服务或 WebView 没建起来（原因见运行日志）。': '로컬 재생 서버 또는 WebView를 시작하지 못했습니다(이유는 실행 로그를 참고하세요).',
  '本机模型不在这里 —— 本地模型只做简单对话，且它的入口已撤下，暂时没有界面能进入它。': '로컬 모델은 여기에 없습니다. 간단한 대화 전용이며, 진입점도 제거되어 지금은 화면에서 열 방법이 없습니다.',
  '本机模型不能进轮换池 —— 它只在你手机上跑，轮换池是给云端模型排队用的。': '온디바이스 모델은 로테이션 풀에 넣을 수 없습니다 — 휴대폰에서만 실행되고, 풀은 클라우드 모델을 순서대로 시도하기 위한 것입니다.',
  '本机模型不需要 API Key —— 如果看到这条，说明 App 注入本机凭据时出了问题（这是个 bug，请在「运行日志」里反馈这条消息）。': '온디바이스 모델에는 API 키가 필요하지 않습니다. 이 메시지가 보인다면 앱이 로컬 자격 증명을 주입하지 못한 것입니다(버그입니다. "실행 로그"에서 이 메시지를 알려주세요).',
  '本机模型需要 Android 9 或更高（当前系统较旧）': '온디바이스 모델은 Android 9 이상이 필요합니다(현재 기기는 이전 버전)',
  '本机现有的运行环境包：{0}': '이 기기에 있는 실행 환경 패키지: {0}',
  '本机用户': '이 기기 사용자',
  '本机离线配音写出了空文件，请再试一次。': '기기 내장 더빙이 빈 파일을 만들었습니다. 다시 시도하세요.',
  '本机离线配音失败：{0}': '기기 내장 더빙 실패: {0}',
  '本机离线配音的引擎没能加载（{0}）。可能是安装包不完整，或这台机器的架构不受支持 —— 可以改用系统 / MiMo / MiniMax。': '기기 내장 더빙 엔진을 불러오지 못했습니다 ({0}). 설치가 불완전하거나 이 기기의 CPU 아키텍처가 지원되지 않을 수 있습니다 — 시스템 / MiMo / MiniMax로 전환하세요.',
  '本机离线配音的模型**已经装好**了（占约 32 MB，离线可用）。': '기기 내장 더빙 모델이 **설치되어 있습니다** (약 32 MB, 오프라인 사용 가능).',
  '本机离线配音的模型还没装好（{0}）。到「配音 → 本机离线」点一下下载即可。': '오프라인 더빙 모델이 아직 설치되지 않았습니다 ({0}). 「더빙 → 기기 내장」에서 다운로드를 누르세요.',
  '本机离线配音的模型还没装（缺 {0}）。在「配音 → 本机离线」那里点下载即可（31.5 MB，装好后离线可用、不用 Key）。': '기기 내장 더빙 모델이 설치되지 않았습니다 (누락: {0}). 「더빙 → 기기 내장」에서 다운로드하세요 (31.5 MB, 설치 후 오프라인·Key 불필요).',
  '本机离线配音（2026-10-13 新增，随包）\n\n· sherpa-onnx 1.13.8 —— 本机离线配音的推理引擎（语音合成）。以 Apache-2.0 授权，https://www.apache.org/licenses/LICENSE-2.0\n  源码与文档：https://github.com/k2-fsa/sherpa-onnx\n  本 App 未修改其源码，直接用官方发布的 arm64 预编译库。\n\n· onnxruntime —— sherpa-onnx 的推理后端（随包的 libonnxruntime.so）。以 MIT 授权，源码：https://github.com/microsoft/onnxruntime\n\n· seek-bzip 2.0.0 —— 纯 JS 的 bzip2 解压（用来在手机上解模型压缩包，因为 Android 既没有 tar 也没有 bzip2）。以 MIT 授权，源码**原样**随包提供：assets/toolbox/vendor/seek-bzip/（含 LICENSE）\n\n· 语音模型 vits-icefall-zh-aishell3 —— **不随包**，由你在 App 里按需下载（约 32 MB）。它来自 icefall（Apache-2.0）（https://github.com/k2-fsa/icefall），基于 aishell3 数据集训练。下载前界面上会写明体积与来源。': '기기 내장 오프라인 더빙 (2026-10-13 추가, 동봉)\n\n· sherpa-onnx 1.13.8 — 기기 내장 더빙의 추론 엔진 (음성 합성). Apache-2.0 라이선스, https://www.apache.org/licenses/LICENSE-2.0\n  소스 및 문서: https://github.com/k2-fsa/sherpa-onnx\n  이 앱은 소스를 수정하지 않고 공식 배포된 arm64 빌드 라이브러리를 그대로 사용합니다.\n\n· onnxruntime — sherpa-onnx가 사용하는 추론 백엔드 (동봉된 libonnxruntime.so). MIT 라이선스, 소스: https://github.com/microsoft/onnxruntime\n\n· seek-bzip 2.0.0 — 순수 JS bzip2 해제 (Android에 tar도 bzip2도 없어 기기에서 모델 압축 파일을 푸는 데 사용). MIT 라이선스, 소스는 **수정 없이 동봉**: assets/toolbox/vendor/seek-bzip/ (LICENSE 포함)\n\n· 음성 모델 vits-icefall-zh-aishell3 — **동봉하지 않습니다**. 앱에서 필요할 때 내려받습니다 (약 32 MB). icefall (Apache-2.0, https://github.com/k2-fsa/icefall)이 aishell3 데이터셋으로 학습한 모델입니다. 다운로드 전에 앱이 용량과 출처를 표시합니다.',
