  '架构图 / 流程图 / 时序图 / ER 图 / 时间线…（44 种，出自包含网页）': '아키텍처 / 순서도 / 시퀀스 / ER / 타임라인… (44종, 자체 완결 HTML)',
  '查看「哪个应用在用、用了多久」的能力。⚠️ 这一项没有「只看本应用」的页面：打开后是一份应用列表，要自己在里面找到本应用再允许。': '어떤 앱이 사용 중인지, 얼마나 썼는지 보는 기능입니다. ⚠️ 이 항목에는 "이 앱만" 보는 페이지가 없습니다: 열면 앱 목록이 나오므로 그 안에서 이 앱을 찾아 직접 허용해야 합니다.',
