  '框：x={0} y={1} 宽 {2} 高 {3}（像素）—— 上面预览里那块就是真会被盖住的地方。': '상자: x={0} y={1} 너비 {2} 높이 {3}(픽셀) — 위 미리보기의 그 부분이 실제로 덮이는 곳입니다.',
  '桥启用证书时必须打开；需要填证书指纹': '브리지에서 인증서를 사용할 때는 반드시 켜야 하며, 인증서 지문을 입력해야 해요.',
