  '检测失败：{0}': '확인 실패: {0}',
  '模型': '모델',
  '模型"想"的那一段怎么显示（它的语言由模型决定）': '모델이 「생각하는」 부분을 어떻게 표시할지(언어는 모델이 결정합니다)',
  '模型名不能为空。': '모델 이름은 비워 둘 수 없습니다.',
  '模型名不被该端点接受。请点「获取模型」从列表里选一个，别手填错名字。': '이 엔드포인트는 이 모델 이름을 받지 않아요. "모델 가져오기"를 눌러 목록에서 고르고, 이름을 직접 입력하지 마세요.',
  '模型名要用控制台里的接入点/模型 id': '모델 이름은 콘솔의 엔드포인트/모델 id를 사용해야 합니다',
  '模型名（发给上游的 id）': '모델 이름(업스트림에 보낼 id)',
  '模型已在本会话生效，但**没能记住**（保存失败：{0}）。重启 App 后会回到原来的模型。': '모델은 이 세션에서 적용되지만 **기억하지 못했습니다**(저장 실패: {0}). 앱을 다시 시작하면 원래 모델로 돌아갑니다.',
  '模型已就绪': '모델 준비 완료',
  '模型已经登记好（{0} 个，会话里能选），但连通性测试没通过 —— 先按下面的原因排查，别急着在新会话里用它。': '모델은 등록되었지만({0}개, 세션에서 선택 가능) 연결 테스트가 실패했습니다 — 아래 원인을 먼저 확인하고, 새 세션에서 성급히 쓰지 마세요.',
  '模型已经登记好（{0} 个，会话里能选），但连通性测试没通过 —— 见下面的原因。': '모델은 등록됐어요({0}개, 세션에서 선택 가능). 다만 연결 테스트에 실패했어요 — 아래 원인을 확인하세요.',
  '模型已配置。': '모델 설정 완료.',
  '模型文件只是"权重"（一堆数字），真正算的是引擎。这一版随包的是 **LiteRT-LM**（跑 Gemma 4 那批 `.litertlm`）。其它格式（比如 `.gguf` 的 llama.cpp）**没有**编进包里，所以那些模型会显示「缺引擎」。缺引擎不是你的手机不行，是包里没有那个引擎；引擎一上，红就会变绿。': '모델 파일은 \'가중치\'(숫자 덩어리)일 뿐이고, 실제 계산은 엔진이 합니다. 이 빌드에 포함된 것은 **LiteRT-LM**(Gemma 4의 `.litertlm`용)입니다. 다른 형식(예: llama.cpp의 `.gguf`)은 **패키지에 포함되지 않아** 해당 모델은 \'엔진 없음\'으로 표시됩니다. 기기 문제가 아니라 패키지에 그 엔진이 없기 때문이며, 엔진이 들어가면 빨강이 초록으로 바뀝니다.',
  '模型没有返回任何内容。': '모델이 아무것도 반환하지 않았습니다.',
  '模型没有返回可用文本：{0}': '모델이 사용할 수 있는 텍스트를 반환하지 않았습니다: {0}',
  '模型清单': '모델 목록',
  '模型的 JSON 里没有 items 数组 —— 这次没提炼出结果。': '모델의 JSON에 items 배열이 없습니다 — 이번에는 아무것도 추출하지 못했습니다.',
  '模型的输出不是合法 JSON（{0}）': '모델의 출력이 올바른 JSON이 아닙니다({0})',
  '模型的输出解析失败：{0}': '모델 출력을 해석하지 못했습니다: {0}',
  '模型的输出里找不到 JSON 结构（前 120 字：{0}）': '모델 출력에서 JSON 구조를 찾지 못했습니다(앞 120자: {0})',
  '模型的输出顶层既不是对象也不是数组。': '모델 출력의 최상위가 객체도 배열도 아닙니다.',
  '模型设置': '모델 설정',
  '模型轮换池': '모델 로테이션 풀',
  '模型返回 HTTP {0}（用的是 {1}）：{2}': '모델이 HTTP {0}을(를) 반환했습니다(사용: {1}): {2}',
  '模型这边被限流了（429）。等一会儿再点，或换一个模型。': '모델이 제한되었습니다(429). 잠시 후 다시 누르거나 다른 모델로 바꾸세요.',
  '模型选好了但还没填 Key 的话，从这里过去': '모델은 골랐지만 Key가 없다면 여기에서',
  '模型配置': '모델 구성',
  '模型配置变了（Key / 端点 / 模型清单），进程里的旧配置不会热更新，正在重建会话…': '모델 구성이 바뀌었어요(Key / 엔드포인트 / 모델 목록). 프로세스의 이전 구성은 핫 리로드되지 않아 세션을 다시 만드는 중…',
  '模糊': '흐리게',
  '欢迎来到泡泡猫的DSH': '泡泡猫의 DSH에 오신 것을 환영합니다',
  '正在下载模型 {0} / {1} MB': '모델 내려받는 중 {0} / {1} MB',
  '正在下载运行环境…': '실행 환경 내려받는 중…',
  '正在下面的「编辑轮换池」表单里改成员 —— 改完点「保存轮换池」。': '아래 "로테이션 풀 편집" 폼에서 멤버를 수정 중 — 다 고치면 "로테이션 풀 저장"을 누르세요.',
  '正在交给系统…': '시스템으로 넘기는 중…',
  '正在从安装包里取出运行环境…': '설치 패키지에서 실행 환경을 꺼내는 중…',
