  '正在准备 APP界面设计台（首次会解包一次，之后直接打开）…': '앱 UI 디자인 스튜디오를 준비하는 중입니다(처음 한 번만 풀면 다음부터는 바로 열립니다)…',
  '正在切换模型…': '모델 전환 중…',
  '正在取消（会终止这次模型调用）…': '취소하는 중입니다(이번 모델 호출을 종료합니다)…',
