  '每个版本改了什么（当前 v{0}）': '버전별 변경 사항 (현재 v{0})',
  '每周': '매주',
  '每周{0} {1}:{2}': '매주 {0} {1}:{2}',
  '每天': '매일',
  '每天 {0}:{1}': '매일 {0}:{1}',
  '每镜生成一张新画面（按该行文本用生图）': '숏마다 새 화면 생성(해당 줄 텍스트로 이미지 생성)',
  '氧气还剩 40 分钟，而你也正在忘记事情': '산소는 40분 남았고, 당신도 기억을 잃어가고 있습니다',
  '汇总一份周报': '주간 보고서 정리',
  '池名': '풀 이름',
  '池名不能为空 —— 这个名字会当成模型名显示在会话的模型面板里。': '풀 이름은 비워둘 수 없습니다 — 이 이름은 세션의 모델 패널에 모델 이름으로 표시됩니다.',
  '池名不能叫 rotate —— 这个名字被轮换代理自己占用了。': '풀 이름을 "rotate"로 지정할 수 없습니다 — 이 이름은 로테이션 프록시가 이미 사용 중입니다.',
  '池名只能用字母、数字和横线（例：cat、fast-1）。': '풀 이름은 영문, 숫자, 하이픈만 사용할 수 있습니다 (예: cat, fast-1).',
  '池子在会话的模型面板里就是一项，名字就是池名（数据上是 `rotate/<池名>`）。': '풀은 세션의 모델 패널에 한 항목으로 표시되고 이름은 풀 이름입니다 (데이터상 `rotate/<풀 이름>`).',
  '池子里的顺序 = 尝试顺序：1 先试，失败了再试 2 …… 编辑成员时可以上移下移。': '풀 안의 순서 = 시도 순서: 1을 먼저 시도하고 실패하면 2를 시도 …… 멤버 편집 시 위/아래로 이동할 수 있습니다.',
  '没做成': '실패',
  '没取到免费模型 —— 上游那条通道可能暂时不可用（或这台机器上不了网）。': '무료 모델을 가져오지 못했습니다 — 상류 경로가 일시적으로 불가하거나 이 기기가 오프라인일 수 있습니다.',
  '没填内容，Key 未改动。': '입력이 없어 Key는 변경하지 않았습니다.',
  '没成功': '실패했습니다',
  '没找到要存的二维码图片（assets/images/wechat_qr.png 不在包里），存相册这一步跳过了。': '저장할 QR 이미지를 찾지 못했습니다(assets/images/wechat_qr.png가 패키지에 없음). 앨범 저장 단계는 건너뛰었습니다.',
  '没有匹配「{0}」的记忆。': '\'{0}\'와 일치하는 기억이 없습니다.',
  '没有匹配的文件': '일치하는 파일 없음',
  '没有可用的下载源': '사용 가능한 다운로드 소스가 없습니다',
  '没有可用的内容。': '사용할 내용이 없습니다.',
  '没有可自检的通道（先去「模型」里打开一个）。': '점검할 채널이 없습니다(먼저 모델에서 하나 켜세요).',
  '没有可配音的文本。': '음성으로 만들 텍스트가 없습니다.',
  '没有存 Key': '저장된 Key 없음',
  '没有找到可以剪的视频。\n这里列的是「作品」里生成过的视频 + 工作区里的视频；两个地方都空的话，先去「创作台 → 生视频」生成一段，或把视频放进工作区。': '자를 수 있는 동영상이 없습니다.\n여기에는 작품에서 생성한 동영상과 작업 공간의 동영상이 나옵니다. 둘 다 비어 있다면 먼저 「스튜디오 → 동영상 생성」으로 만들거나 동영상을 작업 공간에 넣어 주세요.',
  '没有拿到失败原因，下面是脚本的原话：': '실패 이유를 받지 못했습니다. 아래는 스크립트 원문입니다:',
  '没有提炼出内容': '추출된 내용이 없습니다',
  '没有访问该模型的权限（可能是套餐不含、或 Key 权限受限）。': '이 모델에 접근할 권한이 없습니다 (요금제에 포함되지 않았거나 Key 권한이 제한되었을 수 있습니다).',
  '没有识别到内容（可能没说话、或识别服务临时失败）。可以重试，或先用文字输入。': '인식된 내용이 없습니다 (말하지 않았거나 인식 서비스가 일시적으로 실패했을 수 있습니다). 다시 시도하거나 텍스트로 입력하세요.',
  '没有读到内容': '내용을 읽지 못했습니다',
  '没有选中任何文件': '선택된 파일이 없습니다',
  '没有配置 MiMo（小米）的 API Key，无法配音。请在「设置 → 云端大模型 → MiMo」里填一个 Key，或改用系统配音。': 'MiMo(샤오미) API Key가 없어 음성 합성을 할 수 없습니다. 설정 → 클라우드 모델 → MiMo에서 Key를 입력하거나 휴대폰 음성으로 바꾸세요.',
  '没有配置 MiniMax 的 API Key，拉不到音色列表。请在「设置 → 云端大模型 → MiniMax」里填一个 Key。': 'MiniMax API Key가 없어 음성 목록을 가져올 수 없습니다. 설정 → 클라우드 모델 → MiniMax에서 Key를 입력하세요.',
  '没有配置 MiniMax 的 API Key，无法配音。请在「设置 → 云端大模型 → MiniMax」里填一个 Key，或改用系统配音。': 'MiniMax API Key가 없어 음성 합성을 할 수 없습니다. 설정 → 클라우드 모델 → MiniMax에서 Key를 입력하거나 휴대폰 음성으로 바꾸세요.',
  '没法给「{0}」登记任何模型，所以没有保存成功：自动拉取失败，这家也没有内置建议模型。请点「获取模型」自己勾选，或到「添加模型」里手填 model id。': '「{0}」에 등록할 모델이 하나도 없어 저장하지 못했습니다: 자동 가져오기에 실패했고 이 서비스에는 내장 추천 모델도 없습니다. 「모델 가져오기」로 직접 고르거나 「모델 추가」에서 model id를 직접 입력하세요.',
  '没能唤起微信（{0}），可以自己打开微信扫一扫。': '위챗을 열지 못했습니다({0}) — 직접 위챗 스캔을 열어 주세요.',
  '没能唤起微信（可能是没装微信，或这条指令被别的应用接管了）—— 可以自己打开微信扫一扫再扫这张图。': 'WeChat을 열지 못했습니다(설치되어 있지 않거나 다른 앱이 이 명령을 가져갔을 수 있습니다) — 직접 WeChat 스캔을 열어 이 이미지를 스캔하세요.',
  '没能完成': '완료하지 못했습니다',
  '没能打开「{0}」的设置页。手动找：{1}': '「{0}」 설정 페이지를 열지 못했습니다. 직접 열기: {1}',
  '没能打开系统设置页': '시스템 설정 페이지를 열지 못했습니다',
  '没能把会话跑起来。常见原因：模型还没配好、网络不通，或者本机模型服务已经停了。改完之后点「重试」；下面的报文是给开发者看的原始信息。': '세션을 시작하지 못했습니다. 흔한 원인: 모델 미설정, 네트워크 불통, 온디바이스 모델 서비스 중지. 고친 뒤 「다시 시도」를 누르세요. 아래 내용은 개발자용 원본 메시지입니다.',
  '没能读到工作区目录里的文件。\n{0}\n\n点右上角刷新重试。': '워크스페이스 디렉터리의 파일을 읽지 못했습니다.\n{0}\n\n오른쪽 위 새로고침을 눌러 다시 시도하세요.',
  '没能读到这条会话的历史记录（会话文件可能已被清理，或解码失败）。模型的上下文仍然在，直接接着问就行。': '이 세션의 기록을 읽지 못했습니다 (세션 파일이 정리되었거나 디코딩에 실패했을 수 있습니다). 모델의 컨텍스트는 그대로 있으니 계속 질문하세요.',
