  '流畅运行': '원활하게 실행',
  '浅色': '라이트',
  '浅色：白底玻璃面板 + 青紫点缀，白天和强光下看得清。深色：同一套强调色的深色面，面板换成更亮的半透明层，夜里不刺眼。像素：近黑底 + 高饱和的薄荷/洋红/琥珀，并且**圆角全部变成直角**（不只是换色）。': '라이트: 흰 유리 패널에 청록/보라 포인트 — 낮이나 밝은 곳에서도 잘 보입니다. 다크: 같은 포인트 색을 어두운 면에 올리고 패널은 더 밝은 반투명으로 — 밤에도 눈이 편합니다. 픽셀: 거의 검은 바탕에 고채도 민트/마젠타/앰버, 그리고 **모든 둥근 모서리가 직각이 됩니다**(색만 바꾸는 게 아닙니다).',
