  '清单按「内存 + 芯片」挑文件：芯片命中就下 NPU 专属版，否则用通用版。': '목록은 "메모리 + 칩"으로 파일을 고릅니다. 칩이 일치하면 NPU 전용판, 아니면 범용판을 사용합니다.',
