  '清单里写的包大小大得不像话（{0}），不下。': '매니페스트에 적힌 크기가 너무 큽니다({0}). 다운로드하지 않습니다.',
  '清单里的 sha256 还没回填时，只能校验文件大小；回填后才会逐字节校验。': 'sha256가 입력되기 전에는 파일 크기만 검증합니다. 입력되면 바이트 단위로 검증합니다.',
  '清单里缺少 {0} 的文件大小，无法校验': '목록에 {0}의 파일 크기가 없어 검증할 수 없습니다',
