  '游戏页面加载失败：{0}': '게임 페이지를 불러오지 못했습니다: {0}',
  '源码模式 · {0}': '소스 모드 · {0}',
  '点一下「创作台 · 生图」，我给你画一张。': '\'스튜디오 · 이미지 생성\'을 누르면 한 장 그려줄게.',
  '点一下立即生效，重启后保持': '한 번 누르면 바로 적용되고 재시작 후에도 유지됩니다',
  '点一条 → 带着对应技能的指令开新会话': '하나를 누르면 → 해당 스킬 지시와 함께 새 세션 시작',
  '点下面按钮后会打开系统的「保存文件」界面：存到哪儿由你决定（一般是"下载"目录）。': '아래 버튼을 누르면 시스템의 "파일 저장" 화면이 열립니다. 저장 위치는 직접 정할 수 있습니다 (보통 "다운로드" 폴더).',
  '点下面的「获取模型」可以直接勾选。': '아래 "모델 가져오기"에서 바로 선택할 수 있습니다.',
  '点下面的按钮**直接开一个新会话**（首句就是这段起始指令）；也可以自己复制走，发到任意会话里。': '아래 버튼을 누르면 **바로 새 세션을 엽니다**(첫 메시지가 이 지시문입니다). 복사해서 아무 세션에 보내도 됩니다.',
  '点击展开会话': '눌러서 세션 펼치기',
  '点厂家名字展开：介绍 → 去注册 → 获取模型 → 填 Key → 测试并保存': '공급자 이름을 눌러 펼치기: 소개 → 가입 → 모델 가져오기 → Key 입력 → 테스트 후 저장',
  '点右上角 + 新建：设定时间后，到点会自动跑一次对话任务。': '오른쪽 위 + 새로 만들기: 시간을 설정하면 해당 시각에 대화 작업이 자동으로 실행됩니다.',
  '点右上角「新建工作区」建一个；工作区就是 DSH 运行的工作目录。': '오른쪽 위 "새 워크스페이스"를 눌러 만드세요. 워크스페이스는 DSH가 실행되는 작업 디렉터리입니다.',
  '点底部的输入框开始一次对话，会话会出现在这里；本机历史会话由 DSH 的会话文件提供。': '하단 입력창을 눌러 대화를 시작하면 세션이 여기에 표시됩니다. 로컬 기록 세션은 DSH 세션 파일에서 가져옵니다.',
  '版本': '버전',
  '版本 {0}{1}{2}：{3}（点一下{4}）': '버전 {0}{1}{2}: {3} (눌러서 {4})',
  '特大': '특대',
  '特殊权限（必须去系统页面手动打开，应用无法自行授予）': '특수 권한 (시스템 화면에서 직접 켜야 하며, 앱이 스스로 부여할 수 없습니다)',
  '状态：代理在跑（127.0.0.1:{0}）· 免费模型 {1} 个{2}': '상태: 프록시 실행 중(127.0.0.1:{0}) · 무료 모델 {1}개{2}',
  '状态：代理没在跑': '상태: 프록시가 실행 중이 아닙니다',
  '状态：读取中…': '상태: 읽는 중…',
  '现在一个模型都没有，开始会话也没法回话。\n\n去「设置 → 模型」：选一家服务商（端点会自动填好），填上你的 API Key，点「测试并保存」。通过之后回到首页就能开始了。': '지금은 모델이 하나도 없어서 세션을 시작해도 답할 수 없습니다.\n\n「설정 → 모델」로 이동하세요: 서비스를 고르고(엔드포인트는 자동 입력됩니다) API Key를 입력한 뒤 「테스트 후 저장」을 누르세요. 통과하면 홈으로 돌아와 바로 시작할 수 있습니다.',
  '现在用你填的这一条。清空后保存就回到内置的两条源。': '입력하신 소스를 사용 중입니다. 비우고 저장하면 내장된 두 소스로 돌아갑니다.',
  '现在用内置的两条源（GitHub 原站为主、jsDelivr 兜底），**一般不用动**。如果这两条在你那边连不上，把你自己的镜像地址填进来。': '내장된 두 소스(GitHub 원본 우선, jsDelivr 예비)를 사용 중입니다. **보통은 바꿀 필요가 없습니다**. 둘 다 연결되지 않으면 사용하시는 미러 주소를 입력하세요.',
  '现在还不能"看图"': '아직 "이미지 보기"는 연결되지 않았습니다',
  '现在这个模型属于「{0}」，但那一家的 API Key 还没配，所以调不通。\n下一步：打开「设置 → 模型」，把这一家的 Key 填上（Agnes 可以到 platform.agnes-ai.cn 免费注册拿 Key），保存后回到会话重发一次。': '현재 이 모델은 "{0}"에 속하지만 해당 공급자의 API 키가 아직 설정되지 않아 호출할 수 없습니다.\n다음 단계: "설정 → 모델"을 열고 이 공급자의 Key를 입력하세요 (Agnes는 platform.agnes-ai.cn에서 무료로 가입해 Key를 받을 수 있습니다). 저장한 뒤 세션으로 돌아가 다시 보내세요.',
  '生图': '이미지',
  '生图/生视频经常遇到 429（限流）或排队时，多一把 Key 就能在被限流时**自动换另一把**继续。注意：限流按**账号**算 —— **同一个账号**多建几把 Key 共享同一份配额，加了也没用，必须是**另一个账号**的 Key。': '이미지/동영상 생성에서 429(제한)이나 대기가 자주 발생할 때, Key가 하나 더 있으면 제한 중에도 **자동으로 다른 Key로 전환**해 계속할 수 있습니다. 주의: 제한은 **계정 단위**입니다 — **같은 계정**에서 여러 개를 만들어도 같은 할당량을 공유해 소용없고, **다른 계정**의 Key여야 합니다.',
  '生图模型': '이미지 모델',
  '生图用': '이미지 생성',
  '生图用哪个模型？': '이미지 생성에 쓸 모델은?',
  '生成一张图片': '이미지 생성하기',
  '生成一段视频': '동영상 생성하기',
  '生成交接笔记（插进输入框）': '인수인계 노트 생성 (입력창에 삽입)',
  '生成口播视频': '내레이션 동영상 생성',
  '生成后打开系统分享面板（微信 / QQ / 文件传输助手 / 邮件都行）': '생성 후 시스템 공유 패널을 엽니다 (WeChat / QQ / 파일 전송 / 메일 모두 가능)',
  '生成图像与视频': '이미지와 동영상',
  '生成图片': '이미지 생성',
