  '生成并{0}': '생성 후 {0}',
  '生成报告失败（运行日志还没初始化）。': '보고서를 만들 수 없습니다(실행 로그가 아직 초기화되지 않았습니다).',
  '生成日志失败：{0}': '로그 생성 실패: {0}',
  '生成日志失败：拿不到 App 私有目录，无法落盘。': '로그 생성 실패: 앱 전용 디렉터리를 가져오지 못해 저장할 수 없습니다.',
  '生成日志文件并选择保存位置（系统「保存文件」，零权限）': '로그 파일을 생성하고 저장 위치 선택 (시스템 "파일 저장", 권한 불필요)',
  '生成真正的 .pptx（不是 HTML 糊弄）': '진짜 .pptx 생성 (HTML로 때우지 않음)',
  '生成真正的 .pptx：12 种版式 + 自动排版（封面 / 卡片 / 时间线 / 对比 / 数据图…）': '진짜 .pptx 생성: 12가지 레이아웃 + 자동 조판(표지/카드/타임라인/비교/데이터 차트…)',
  '生成短剧视频': '숏드라마 동영상 생성',
  '生成视频': '동영상 생성',
  '生视频': '동영상',
  '生视频模型': '동영상 모델',
  '生视频用': '동영상 생성',
  '生视频用哪个模型？': '동영상 생성에 쓸 모델은?',
  '用 code-tool 技能帮我写一个小工具并跑通。需求：\n（说清输入是什么、要输出什么；我会写成 node 脚本、真的执行一次、把结果给你）': 'code-tool 스킬로 작은 도구를 만들고 실제로 실행해 주세요. 요구 사항:\n(입력이 무엇이고 출력이 무엇인지 적어 주세요. node 스크립트를 작성해 한 번 실제로 실행하고 결과를 드립니다)',
  '用 data-analysis 技能帮我分析数据。数据文件在：\n（把文件路径或工作区文件名写在这里；我要看结论、关键数字和图表）': 'data-analysis 스킬로 데이터를 분석해 주세요. 데이터 파일:\n(파일 경로나 작업 공간의 파일명을 적어 주세요. 결론과 핵심 숫자, 차트를 보고 싶습니다)',
  '用 diagram-design 技能，': 'diagram-design 스킬로, ',
  '用 doc-digest 技能帮我速读这份长文：\n（给出文件路径或粘贴内容；我要要点清单和一条时间线）': 'doc-digest 스킬로 이 긴 글을 빠르게 읽어 주세요:\n(파일 경로를 주거나 본문을 붙여 넣어 주세요. 핵심 목록과 타임라인을 원합니다)',
  '用 doc-processing 技能帮我处理这份文档：\n（写清文件路径与你要的结果：摘要、改写、纠错，还是转成 Markdown/HTML）': 'doc-processing 스킬로 이 문서를 처리해 주세요:\n(파일 경로와 원하는 결과를 적어 주세요: 요약, 다시 쓰기, 교정, Markdown/HTML 변환 등)',
  '用 file-organize 技能帮我整理工作区文件。目标：\n（说明按什么规则重命名或归档；动手前我会先把计划列给你确认）': 'file-organize 스킬로 작업 공간 파일을 정리해 주세요. 목표:\n(어떤 규칙으로 이름을 바꾸거나 보관할지 적어 주세요. 실행 전에 계획을 먼저 보여 드리고 확인받습니다)',
  '用 make-image 技能帮我生成一张图片。画面描述：\n（写清主体、场景、风格、光线；我会直接生成图片文件并告诉你路径）': 'make-image 스킬로 이미지를 생성해 주세요. 화면 설명:\n(피사체, 장면, 스타일, 조명을 적어 주세요. 이미지 파일을 바로 만들고 경로를 알려 드립니다)',
  '用 make-slides 技能帮我做一份幻灯片。': 'make-slides 스킬로 슬라이드를 만들어 주세요.',
  '用 make-slides 技能帮我做一份幻灯片。主题/材料：\n（把主题或要讲的内容写在这里，我先按你说的整理大纲，再生成 .pptx 文件并告诉你路径）': 'make-slides 스킬로 슬라이드 자료를 만들어 주세요. 주제/자료:\n(주제나 발표할 내용을 여기에 적어 주세요. 먼저 목차를 정리한 뒤 .pptx 파일을 만들고 경로를 알려 드립니다)',
  '用 make-video 技能帮我生成一段视频。画面描述：\n（写清主体、动作、镜头、时长；我会提交任务并等它生成好，然后给你文件路径）': 'make-video 스킬로 동영상을 생성해 주세요. 화면 설명:\n(피사체, 동작, 카메라, 길이를 적어 주세요. 작업을 제출하고 완료될 때까지 기다린 뒤 파일 경로를 알려 드립니다)',
  '用 novel-to-game 技能把我这本小说做成一个能玩的游戏：\n（给出小说文件路径或书名。我会先拆原著、再比选方向，然后一步步做出能真跑的网页游戏 —— 这是一条多轮流水线，不是一轮就能交付的）': 'novel-to-game 스킬로 제 소설을 플레이 가능한 게임으로 만들어 주세요:\n(소설 파일 경로나 제목을 주세요. 먼저 원작을 분해하고 방향을 비교한 뒤 실제로 돌아가는 웹 게임을 차근차근 만듭니다 — 여러 차례 대화가 필요한 작업이고 한 번에 끝나지 않습니다)',
  '用 sheet-cleanup 技能帮我整理这张表：\n（给出 CSV 路径；说明要去重、统一格式，还是要按某列分组汇总）': 'sheet-cleanup 스킬로 이 표를 정리해 주세요:\n(CSV 경로를 주세요. 중복 제거인지, 형식 통일인지, 특정 열 기준 그룹 집계인지 알려 주세요)',
  '用 study-cards 技能把这些材料变成学习卡片：\n（给出文件路径或主题；我要「问题 / 答案」成对的卡片，能直接背）': 'study-cards 스킬로 이 자료를 학습 카드로 만들어 주세요:\n(파일 경로나 주제를 주세요. 바로 외울 수 있는 「질문 / 답」 쌍 카드를 원합니다)',
  '用 translate-polish 技能帮我翻译并润色：\n（给出原文或文件路径，说明目标语言与语气；我要双语对照版）': 'translate-polish 스킬로 번역하고 다듬어 주세요:\n(원문이나 파일 경로, 목표 언어와 어조를 알려 주세요. 대역본을 드립니다)',
  '用 weekly-report 技能帮我写一份周报。时间范围与关注点：\n（比如"这周做的三件事"；我会先看工作区里的文件再汇总，不确定的地方会问你）': 'weekly-report 스킬로 주간 보고서를 써 주세요. 기간과 중점:\n(예: "이번 주에 한 세 가지 일". 작업 공간 파일을 먼저 보고 정리하며, 불확실한 부분은 여쭙습니다)',
  '用其它应用打开': '다른 앱으로 열기',
  '用周围像素把它盖住 —— **不是恢复原内容**。纯色、平滑背景效果好；复杂纹理背景会看出痕迹。': '주변 픽셀로 덮을 뿐, **원래 내용을 복원하는 것이 아닙니다**. 단색·매끄러운 배경은 잘 되지만, 복잡한 무늬 배경은 흔적이 남습니다.',
  '用哪个图像模型？': '어떤 이미지 모델을 쓸까요?',
  '用哪个文本模型？': '어떤 텍스트 모델을 쓸까요?',
  '用哪个视频模型？': '어떤 동영상 모델을 쓸까요?',
  '用户级': '사용자 수준',
  '用手机上的播放器打开': '휴대폰 플레이어로 열기',
  '用手机自带的语音朗读：零配置、免费、可离线。⚠️ **但不是每台手机都装了语音引擎或中文语音包** —— 遇到"没有可用的文字转语音引擎"时，下面两条路任选：① 去系统设置里装一个引擎并下载中文语音包；② 改用 MiMo 或 MiniMax（都要一个 API Key，见下）。': '기기 내장 음성을 사용합니다: 설정 불필요, 무료, 오프라인 가능. ⚠️ **다만 모든 기기에 음성 엔진이나 중국어 음성 데이터가 설치되어 있지는 않습니다** — "사용 가능한 음성 합성 엔진이 없습니다"가 나오면 아래 두 가지 중 하나를 하세요: ① 시스템 설정에서 엔진을 설치하고 중국어 음성 데이터를 내려받기; ② MiMo 또는 MiniMax로 전환 (둘 다 API Key 필요 — 아래 참조).',
  '申请失败：{0}': '요청 실패: {0}',
  '申请常用权限': '일반 권한 요청',
  '电影感': '시네마',
  '电脑地址': '컴퓨터 주소',
  '电脑端 DSH 启动失败：{0}': '컴퓨터의 DSH 시작 실패: {0}',
  '电脑端 DSH 正在重启：{0}': '컴퓨터의 DSH 재시작 중: {0}',
  '电脑端状态：{0}': '컴퓨터 상태: {0}',
  '画一张 ER 图：用户、订单、商品三张表以及它们的关系': 'ER 다이어그램: 사용자·주문·상품 세 테이블과 그 관계',
  '画一张系统架构图：调用方 → 网关 → 三个后端服务 → 数据库': '시스템 아키텍처 다이어그램: 호출자 → 게이트웨이 → 백엔드 3개 → 데이터베이스',
  '画一张项目时间线（甘特）：需求、开发、测试、上线四段': '프로젝트 타임라인(간트): 요구사항·개발·테스트·출시 네 단계',
  '画图表': '다이어그램 그리기',
  '画字幕 {0}/{1}': '자막 그리는 중 {0}/{1}',
  '画幅': '화면 비율',
  '画第 {0}/{1} 镜的画面…': '{0}/{1}번 숏 화면 그리는 중…',
  '画面比例': '화면 비율',
  '留空 = 不改动已存的 Key': '비워 두기 = 저장된 Key 변경 안 함',
  '留空 → 会生成 provider id「{0}」（中文名推不出字母，所以自动编号）': '비워 두면 → provider id "{0}"가 생성됩니다(중국어 이름은 영문자를 만들 수 없어 자동 번호가 붙습니다)',
  '留空就按厂家名生成，例如 qwen': '비워두면 공급자 이름으로 생성됩니다 (예: qwen)',
  '白桦': '白桦',
  '盘上有 {0} 个模型本版跑不了：{1}。它们要 llama.cpp 引擎，而这个引擎 0.47 起就不随包了 —— 回「本地大模型」页可以删掉，或下载 Gemma 4 这类 .litertlm 模型': '디스크에 있는 모델 {0}개가 이 버전에서는 실행되지 않습니다: {1}. 이들은 llama.cpp 엔진이 필요하지만 해당 엔진은 0.47부터 포함되지 않습니다. 「로컬 대형 모델」페이지에서 삭제하거나 Gemma 4 같은 .litertlm 모델을 내려받으세요.',
  '直接就能用，不用填 Key。': '바로 사용할 수 있습니다. Key가 필요 없습니다.',
  '直接问它就好（这里没有工具、没有技能，纯聊天）。': '그냥 물어보세요(여기에는 도구도 스킬도 없고 순수한 대화입니다).',
  '相册': '앨범',
  '看看卡在哪一步': '어디에서 멈췄는지 보기',
  '真实行为（本地轮换代理）：按池子里的顺序依次尝试，只有上游失败（429 限流 / 5xx / 连不上 / 等响应头等到超时）才换下一个 —— 流式响应一旦开始下发就不再切换（HTTP 响应头已经发出去，这是协议本身的约束，不是偷懒）；全部成员都失败，才会把错误抛回会话。它还会记住每个池子"上次成功"的那个成员，下次先从它开始试。': '실제 동작(로컬 로테이션 프록시): 풀 순서대로 시도하고, 업스트림이 실패했을 때(429 제한 / 5xx / 연결 불가 / 응답 헤더 대기 시간 초과)만 다음으로 넘어갑니다 — 스트리밍 응답이 시작되면 더는 전환할 수 없습니다(HTTP 헤더가 이미 나갔고, 이는 프로토콜 제약이지 게으름이 아닙니다). 모든 멤버가 실패해야 오류를 세션으로 돌려줍니다. 각 풀의 "마지막 성공" 멤버도 기억해 다음에는 거기서 시작합니다.',
  '知识库': '지식 베이스',
  '知识库 {0} 段': '지식 베이스 {0}건',
  '知识库「{0}」的索引还是旧切法建的：它把好几篇不相关的文章塞在同一块里，检索会不准 —— 新的相关度门槛对它也无效。去知识库页点「重建（推荐）」就好（在本机重建，不联网、不花额度）。': '지식 「{0}」의 색인은 예전 방식으로 만들어졌습니다: 관련 없는 글을 한 블록에 몰아넣어 검색이 부정확하고, 새 관련도 기준도 통하지 않습니다. 지식 페이지에서 「다시 만들기(권장)」를 누르세요(휴대폰에서 재구성, 네트워크·과금 없음).',
  '知识库内容来自第三方社区语料，依 CC BY-SA 4.0 许可使用。': '지식 콘텐츠는 제3자 커뮤니티 말뭉치에서 왔으며 CC BY-SA 4.0 라이선스로 사용합니다.',
  '知识库是给本地模型查的离线资料 —— 查到的片段会折进「本地对话」那一轮的问题里，所以它不联网、不花额度。': '지식 베이스는 로컬 모델이 찾아보는 오프라인 자료입니다. 일치하는 부분은 「로컬 대화」의 해당 턴 질문에 함께 들어가므로 네트워크나 과금이 필요 없습니다.',
  '知道了': '확인',
  '短剧': '숏드라마',
  '短剧剧本专家': '숏드라마 대본 전문가',
  '硅基流动没有时长参数：时长由模型决定，分辨率按比例换算成 image_size。': 'SiliconFlow에는 길이 파라미터가 없습니다: 길이는 모델이 정하고 해상도는 비율에서 `image_size`로 환산됩니다.',
  '确定删除「{0}」吗？': '「{0}」를 삭제할까요?',
  '确定删除「{0}」吗？会释放 {1}': '「{0}」를 삭제할까요? {1}이(가) 확보됩니다.',
  '确定删除「{0}」？': '"{0}"을(를) 삭제할까요?',
  '磁盘历史会话 {0} 条': '디스크 기록 세션 {0}개',
  '磁盘历史会话 {0} 条（其中 {1} 条是空会话，没列出来）': '디스크의 지난 세션 {0}개(빈 세션 {1}개는 목록에서 제외)',
  '磁盘历史会话：未读取': '디스크 기록 세션: 불러오지 않음',
  '移出这个池子': '이 풀에서 제거',
  '移动文件': '파일 이동',
  '移除': '제거',
  '移除这张图': '이 이미지 제거',
  '空闲 · {0} 条': '유휴 · {0}개',
  '立即运行一次': '지금 한 번 실행',
  '端口': '포트',
  '端口必须是数字': '포트는 숫자여야 합니다',
  '端点': '엔드포인트',
  '端点与其他厂商不同（/paas/v4）': '엔드포인트가 다른 업체와 다릅니다(/paas/v4)',
  '端点已切到「{0}」：{1}': '엔드포인트를 "{0}"(으)로 전환했어요: {1}',
  '端点是 /zen/go/v1（免费那档是 /zen/v1，两个别混）。「获取模型」拉的是这个端点的实时清单（实测约 37 个），里面**含免费模型**（如 beam-free、longcat-2.5-preview-free）——所以看到 *-free 不用吃惊，它们确实属于这档。若某个模型报「没有访问该模型的权限」，那是你这把 Key 在该模型上的权限问题，不是 Key 坏了。': '엔드포인트는 /zen/go/v1(무료 등급은 /zen/v1, 둘을 혼동하지 마세요). 「모델 가져오기」는 이 엔드포인트의 실시간 목록을 가져오며(실측 약 37개) 그 안에 **무료 모델이 포함됩니다**(예: beam-free, longcat-2.5-preview-free) — 그러니 *-free 이름을 보고 놀라지 마세요, 실제로 이 등급에 속합니다. 어떤 모델에서 「이 모델에 접근할 권한이 없습니다」가 나오면 그것은 이 키의 해당 모델 권한 문제이지, 키가 고장 난 것이 아닙니다.',
  '端点（这家有两套，点一下切换；选错会 401/404）': '엔드포인트 (이 제공자는 두 가지예요. 탭해서 전환하세요. 잘못 고르면 401/404가 나요)',
  '第 {0} 号': '화자 {0}번',
  '第 {0} 镜的字幕帧没渲染出来。': '{0}번 숏 자막 프레임을 렌더링하지 못했습니다.',
  '第 {0} 镜的画面没生成出来。': '{0}번 숏 화면이 생성되지 않았습니다.',
  '第 {0} 镜起**跳过配音**（{1}）—— 改成"画面 + 字幕"的静音片继续做完，后面每一镜都不再尝试配音。': '샷 {0}부터 **더빙을 건너뜁니다** ({1}) — "영상 + 자막" 무음본으로 계속 만들어 끝냅니다. 이후 샷은 다시 시도하지 않습니다.',
  '第一次用建议：选一个 → 启动 →【测速】，再换另一个测一次，哪个 tok/s 高就用哪个。切换要重启服务，所以跑着的时候按钮是灰的。': '처음에는 하나를 선택 → 시작 → [속도 측정], 다른 쪽으로 바꿔 다시 측정해 tok/s가 높은 쪽을 사용하세요. 전환하려면 서비스를 다시 시작해야 하므로 실행 중에는 버튼이 비활성화됩니다.',
  '第三方组件与许可': '서드파티 구성 요소 및 라이선스',
  '等待当前轮次结束或先取消…': '현재 라운드가 끝나기를 기다리거나 먼저 취소하세요…',
  '等模型回复超时了，再点一次试试。': '모델 응답 시간이 초과되었습니다. 다시 눌러 주세요.',
  '等配音超时了（{0} 秒）。再试一次，或把文稿拆短些。': '음성 대기 시간 초과({0}초). 다시 시도하거나 원고를 짧게 나누세요.',
  '签名与当前应用一致，可以安装。': '서명이 현재 앱과 일치합니다. 설치할 수 있습니다.',
  '签名校验没通过。': '서명 검증을 통과하지 못했습니다.',
  '简介与正文都不能为空': '설명과 본문 모두 비워 둘 수 없어요',
  '简介：什么时候该用这个技能': '설명: 이 스킬을 언제 쓰는지',
  '管理知识库': '지식 베이스 관리',
  '精确剪（重新编码，慢）': '정확히 자르기(재인코딩, 느림)',
  '系统识别={0} · 设备端离线={1} · 可处理识别的应用数={2} · 语言={3}{4}': '시스템 인식={0} · 기기 내 오프라인={1} · 인식 지원 앱 수={2} · 언어={3}{4}',
  '系统语言：{0}': '시스템 언어: {0}',
  '系统配音写了空文件，请再试一次。': '휴대폰 음성이 빈 파일을 만들었습니다. 다시 시도해 주세요.',
  '系统配音失败：{0}': '휴대폰 음성 실패: {0}',
  '系统配音超时了（这台设备的语音引擎没有回应）。再试一次，或改用 MiMo。': '휴대폰 음성 시간이 초과되었습니다(음성 엔진이 응답하지 않음). 다시 시도하거나 MiMo로 바꾸세요.',
  '系统配音（零配置）': '기기 내장 음성 (설정 불필요)',
  '系统里没有任何语音识别服务，App 无论怎么写都用不了语音 —— 需要去应用商店装一个（例如各家的语音助手），或改用文字输入。': '이 시스템에는 음성 인식 서비스가 없어 앱을 어떻게 만들어도 음성 입력은 쓸 수 없습니다. 앱 스토어에서 설치하거나(각 사의 음성 비서 등) 텍스트 입력을 사용하세요.',
  '系统里没有能打开这种文件的应用': '이 종류의 파일을 열 수 있는 앱이 없어요',
  '给「{0}」填 Key': '"{0}"의 Key 입력',
  '给本地模型查的离线资料': '로컬 모델이 찾아보는 오프라인 자료',
  '给这条会话起个名字': '이 세션에 이름 붙이기',
  '统一形象图（可选）': '공통 인물 이미지(선택)',
  '继续上次会话': '지난 세션 이어하기',
  '继续上次会话：{0}': '지난 세션 이어하기: {0}',
  '继续下载（已下 {0} MB）': '다운로드 계속 ({0} MB 완료)',
  '编辑': '편집',
  '编辑定时任务': '예약 작업 편집',
  '编辑成员': '멤버 편집',
  '编辑技能 {0}': '스킬 {0} 편집',
  '编辑轮换池「{0}」': '로테이션 풀 "{0}" 편집',
  '缺少环境变量：{0}': '환경 변수가 없어요: {0}',
  '网络不通：请检查手机网络/代理，然后重试。': '네트워크가 안 돼요. 휴대폰 네트워크/프록시를 확인한 뒤 다시 시도하세요.',
  '置顶': '맨 위로 고정',
  '美化是**本机 ffmpeg 滤镜**做的（调色 / 锐化 / 磨皮 / 暗角）：不联网、不花额度、秒级完成。': '보정은 **기기 안의 ffmpeg 필터**로 합니다(색 보정 / 샤프닝 / 피부 보정 / 비네트). 네트워크 없이, 할당량 없이, 몇 초 만에 끝납니다.',
  '美团 LongCat。适合已经拿到 LongCat Key 的用户。': '메이투안 LongCat. 이미 LongCat Key가 있는 분에게 맞아요.',
  '联网': '온라인',
  '联网请求': '온라인 요청',
  '聚合平台，模型名照它站内的写': '애그리게이터 플랫폼입니다. 모델 이름은 사이트에 표기된 그대로 쓰세요',
  '聚合端点：一个 Key 就能用到 DeepSeek / MiMo / LongCat / GLM / Qwen / Claude / GPT 等多家模型。适合不想挨家注册、只想填一次 Key 的人。': '집계 엔드포인트: Key 하나로 DeepSeek / MiMo / LongCat / GLM / Qwen / Claude / GPT 등 여러 모델을 쓸 수 있어요. 여러 곳에 가입하지 않고 Key를 한 번만 입력하고 싶은 분에게 맞아요.',
  '能不能放取决于手机上的 WebView 解码器；放不出来时会在这里说明，并可以改用其它应用打开。': '재생 여부는 휴대폰의 WebView 코덱에 달려 있습니다. 재생할 수 없으면 여기에 표시되고 다른 앱으로 열 수 있습니다.',
  '脚本原话（出问题时能看出来卡在哪）': '스크립트 원문 로그(문제가 생기면 어디서 막혔는지 보입니다)',
  '自定义': '사용자 지정',
  '自定义厂家才需要你填地址；内置厂家的地址一律自动用内置值。': '주소를 입력해야 하는 건 사용자 지정 제공자뿐이에요. 내장 제공자는 항상 내장 주소를 자동으로 써요.',
  '自定义端点': '사용자 지정 엔드포인트',
  '自定义配色还没做。现在有「浅色 / 深色 / 像素」三套皮肤，点「自定义」不会切主题 —— 也不会把主题切到一个不存在的状态。': '사용자 지정 색상은 아직 없습니다. 실제 스킨은 「라이트 / 다크 / 픽셀」 세 가지이며, 「사용자 지정」을 눌러도 테마가 바뀌지 않고 — 존재하지 않는 상태로 남지도 않습니다.',
  '自己手写一条': '직접 한 건 작성',
  '自检本身出错了：{0}': '자체 점검 자체가 실패했습니다: {0}',
  '自检结果已写进运行日志并生成报告 —— 在分享面板里选一个应用发给开发者即可（报告里没有 Key）。': '자체 점검 결과가 실행 로그에 기록되고 보고서가 생성되었습니다 — 공유 시트에서 앱을 골라 개발자에게 보내세요(보고서에 Key는 없습니다).',
  '至少要放 1 个成员 —— 池子里一个模型都没有的话，选中它必然失败。': '멤버를 최소 1개 넣어야 해요 — 모델이 하나도 없는 풀을 선택하면 반드시 실패해요.',
  '至少要有一个 model id：手填一个，或用「获取模型」勾一个。': 'model id가 최소 하나 필요해요. 직접 입력하거나 "모델 가져오기"로 선택하세요.',
  '船体刚刚被撞过，主电源断了，副氧还剩 40 分钟，通讯断续（一次只能说几句）。舱里只有一名船员还醒着。': '선체가 방금 충돌로 손상되고 주전원이 나갔으며, 예비 산소는 40분 남았고 통신은 끊깁니다(한 번에 몇 문장만). 선내에서 깨어 있는 승무원은 한 명뿐입니다.',
  '芯片': '칩',
  '芯片：{0}': '칩셋: {0}',
  '苏打': '苏打',
  '英文女声 · 活泼': '영어 여성 · 발랄',
  '英文女声 · 甜美': '영어 여성 · 달콤',
  '英文男声 · 沉稳': '영어 남성 · 차분',
  '英文男声 · 阳光': '영어 남성 · 밝음',
  '茉莉': '茉莉',
  '获取中…': '가져오는 중…',
  '获取模型': '모델 가져오기',
  '获取模型列表需要 API Key：先在上面填好 Key 再点「获取模型」。（实测这四家的 /models 都要鉴权，不带 Key 一律 401。）': '모델 목록을 가져오려면 API Key가 필요합니다: 위에 Key를 먼저 입력한 뒤 「모델 가져오기」를 누르세요. (실측: 이 네 곳의 /models는 모두 인증이 필요하고 Key 없이는 항상 401입니다.)',
  '获取模型列表需要 API Key：自定义端点绝大多数也要鉴权。': '모델 목록을 가져오려면 API 키가 필요해요. 사용자 지정 엔드포인트도 대부분 인증이 필요해요.',
  '获取模型列表需要 API Key：请先填写 {0} 的 Key 再点获取。（实测这四家的 /models 都要求鉴权，不带 Key 一律返回 401。）': '모델 목록을 가져오려면 API 키가 필요해요. 먼저 {0}의 Key를 입력한 뒤 가져오기를 누르세요. (실측 결과 이 네 곳의 /models는 모두 인증이 필요하고, Key가 없으면 무조건 401이에요.)',
  '落盘日志文件：{0}': '디스크에 저장하는 로그 파일: {0}',
  '表格整理': '표 정리',
  '被上游拒绝（403：地区封锁）': '업스트림 거부(403: 지역 차단)',
  '被上游拒绝（403：当成非官方客户端）': '업스트림 거부(403: 비공식 클라이언트로 간주)',
  '被限流了：等一会儿再试，或换一个模型。': '요청 제한입니다: 잠시 후 다시 시도하거나 다른 모델로 바꾸세요.',
  '被限流（429）': '요청 제한(429)',
  '装不动也不要紧：这个模型包里 172 MB 的规则文件**不会解出来**（实测对我们没用），所以只占约 32 MB。也可以手动装 —— 把这几个文件放进下面这个目录：\n{0}': '다운로드가 안 되어도 괜찮습니다: 압축 안의 172 MB 규칙 파일은 **풀지 않습니다** (실측 결과 불필요). 그래서 약 32 MB만 사용합니다. 수동 설치도 가능합니다 — 다음 디렉터리에 파일을 넣으세요:\n{0}',
  '装入样例': '샘플 설치',
  '装好了': '설치 완료',
  '装好了：本机离线配音现在可以用了（离线、零 Key）。': '설치 완료: 기기 내장 더빙을 사용할 수 있습니다 (오프라인, Key 불필요).',
  '要修的图': '편집할 사진',
  '要执行什么不能为空 —— 到点它会作为一条消息发给模型。': '실행할 내용은 비워 둘 수 없어요 — 시간이 되면 메시지로 모델에 전송돼요.',
  '要执行什么（会作为一条消息发给模型）': '실행할 내용 (메시지로 모델에 전송돼요)',
  '要执行的内容：': '실행할 내용:',
  '要点 + 时间线，别再让我读完': '핵심 + 타임라인, 끝까지 읽지 않아도 됩니다',
  '要用就回「设置 → 模型」填上它的 API Key。': '사용하려면 「설정 → 모델」로 돌아가 해당 API Key를 입력하세요.',
  '要用就回「设置 → 模型」把 Zen 那条打开（它经 App 内代理转发）。': '사용하려면 「설정 → 모델」로 돌아가 Zen 항목을 켜세요(앱 내 프록시를 거쳐 전달됩니다).',
  '要用就回「设置 → 模型」把「免费模型（无需 Key）」打开。': '사용하려면 「설정 → 모델」로 돌아가 「무료 모델(Key 불필요)」을 켜세요.',
  '规则：① 只以你的角色身份说话，**不要出戏**、不要解释自己是 AI、不要总结或复述我的问题；② 每次回复短一点（2-3 句），把行动的余地留给我；③ **不要替我决定**、不要替我写台词；④ 我说「结束」时，给出这个角色的结局（一两句，说清发生了什么）。': '규칙: ① 오직 당신 캐릭터로서만 말하기 — **역할에서 벗어나지 말고**, 자신이 AI라고 설명하지 말고, 내 질문을 요약하거나 되풀이하지 않기; ② 답변은 짧게(2~3문장), 행동할 여지를 나에게 남기기; ③ **나 대신 결정하지 말고**, 내 대사를 쓰지 않기; ④ 내가 "끝"이라고 하면 이 캐릭터의 결말을 제시하기(무슨 일이 있었는지 한두 문장으로).',
  '视觉编码器（mmproj）': '비전 인코더(mmproj)',
  '视频': '동영상',
  '视频已生成：{0}': '동영상 생성됨: {0}',
  '视频是异步任务：几十秒到几分钟都正常，期间不会重复提交。': '동영상은 비동기 작업입니다: 수십 초에서 몇 분 걸리는 것이 정상이며, 그동안 다시 제출하지 않습니다.',
  '视频模型': '동영상 모델',
  '视频请求的形状同样按各家文档写：豆包 Seedance（方舟异步任务）/ MiniMax / 通义万相（百炼异步）/ 硅基流动 各一套 —— **能不能通要试**；失败会把上游原话显示出来。': '동영상 요청 형식도 각 사 문서를 따릅니다: 더우바오 Seedance(Ark 비동기 작업) / MiniMax / 通義万相(百炼 비동기) / SiliconFlow 각각 별도 형식 —— **되는지는 시도해 봐야 합니다**. 실패하면 업스트림 원문을 그대로 보여 줍니다.',
  '角色三视图专家': '캐릭터 삼면도 전문가',
  '角色现在是**打字**的：本机还没有「朗读回复」（语音合成在「创作台 → 口播/短剧」那条线上，不在会话里）——想让角色出声要另做一层，已列入后续。': '지금 캐릭터는 **타이핑**입니다: 이 기기에는 아직 \\\'읽어주는 답변\\\'이 없습니다(음성 합성은 \\\'스튜디오 → 내레이션/숏드라마\\\' 라인에 있고 대화 안에는 없습니다) — 캐릭터에게 목소리를 주려면 한 겹 더 필요하며, 이후 과제로 두었습니다.',
  '角色的**记忆只在这一局里**：开个新会话它就忘了。想让某件事长期记住，写进设置里的「记忆」。': '캐릭터의 **기억은 이 판 안에만** 있습니다: 새 세션을 열면 잊어버립니다. 어떤 일을 오래 기억하게 하려면 설정의 \'기억\'에 적어 두세요.',
  '解出来的模型文件不齐，缺：{0}（压缩包已保留在 {1}，可以重试）': '압축을 푼 모델 파일이 불완전합니다. 누락: {0} (압축 파일은 {1}에 남겨 두었으니 다시 시도할 수 있습니다)',
  '解包失败（退出码 {0}）：{1}': '압축 해제 실패 (종료 코드 {0}): {1}',
  '解压完成但仍找不到运行时文件': '압축은 풀었지만 런타임 파일을 찾지 못했어요',
  '解除配对': '페어링 해제',
  '订阅失败：{0}': '구독 실패: {0}',
  '认不出的厂家按 OpenAI 兼容形状试：size 用像素值。': '알 수 없는 공급사는 OpenAI 호환 형식으로 시도합니다: `size`는 픽셀 값입니다.',
  '让 App 能安装 APK（例如以后把新版本安装包交给它来升级）。每次安装系统还会再问你一次。': '앱이 APK를 설치할 수 있게 합니다(예: 새 빌드를 넘겨 업데이트). 설치할 때마다 시스템이 다시 확인합니다.',
  '让 App 能读写手机里任意目录的文件（不只是自己那一份）。不开也能用：会话与工具会在自己的私有目录、以及你手动选给它的范围内活动。': '앱이 휴대폰의 임의 폴더에 있는 파일을 읽고 쓸 수 있게 합니다(자기 폴더만이 아니라). 꺼져 있어도 동작합니다: 세션과 도구는 앱 전용 폴더와 사용자가 파일 선택으로 넘긴 범위에서만 활동합니다.',
  '让 DSH 写一份文档或生成一张图，产物会出现在这里。': 'DSH에게 문서를 쓰게 하거나 이미지를 생성하면 결과물이 여기에 나타나요.',
  '让「短剧剧本专家」写一版': '\'숏드라마 대본 전문가\'에게 쓰게 하기',
  '让会话能用子智能体': '하위 에이전트',
  '让会话能联网搜索': '세션에서 웹 검색 사용',
  '让模型**演一个角色**，你跟他打交道 —— 每张牌都写清了「谁演谁、在哪、你要办成什么、什么时候算完」。**这不是聊天**：聊天没有压力、没有后果、也没法结束。': '모델이 **역할을 연기하게** 하고 당신이 그와 상대하는 것입니다 — 카드마다 \'누가 누구를 연기하는지, 어디서, 무엇을 이루어야 하는지, 언제 끝나는지\'가 적혀 있습니다. **이건 채팅이 아닙니다**: 채팅에는 압박도, 결과도, 끝낼 방법도 없습니다.',
  '让模型**长期记住**你的事（身份、偏好、项目事实、禁忌）：可以自己写，也可以从最近的会话里**自动提炼**候选、由你确认。它写进 AGENTS.md，DSH 在**每个新会话的第一个请求前**注入模型上下文；**对已经打开的会话不生效**，要新建会话。': '모델이 **장기적으로 기억할 것**(정체성, 선호, 프로젝트 사실, 금기)을 적을 수 있습니다. 직접 쓰거나 최근 세션에서 후보를 **자동 추출**해 확인할 수 있습니다. AGENTS.md에 기록되고 DSH가 **새 세션의 첫 요청 전에** 모델 컨텍스트에 주입합니다. **이미 열려 있는 세션에는 적용되지 않습니다** — 새 세션을 만드세요.',
  '让模型演一个角色，你跟他打交道 —— 每局都有目标和结束条件': '모델이 역할을 연기하게 하고 당신이 상대합니다 — 모든 판에 목표와 종료 조건이 있습니다',
  '让模型记住这些（关闭后不再注入）': '모델이 이것들을 기억하게 하기(끄면 주입하지 않습니다)',
  '让模型读一段真实对话，提炼出长期有效的偏好与事实。**提炼结果不会自动写入**，要你勾选确认；每次提炼都会真实调用一次模型（会花额度）。': '모델이 실제 대화를 읽고 오래 유효한 선호와 사실을 추출합니다. **추출 결과는 자동으로 기록되지 않습니다** — 남길 항목을 선택하세요. 추출할 때마다 실제로 모델을 한 번 호출합니다(할당량을 사용합니다).',
  '让谁帮你写？': '누구에게 맡길까요?',
  '记得先在「云端大模型」里把「{0}」这家配好（厂家 id 用 {1}）—— Key 是从那边读的。': '먼저 「클라우드 대형 모델」에서 "{0}"을(를) 설정하세요(공급사 id는 {1}) —— Key는 거기서 읽습니다.',
  '记忆': '기억',
  '记忆占用 {0} / {1} 字节': '기억 사용량 {0} / {1} 바이트',
  '记忆总量超了：现在约 {0} 字节，上限 {1} 字节。请先删掉几条再添加（总预算与专家说明共享 DSH 的 64 KB 注入上限）。': '기억 총량이 초과했습니다: 현재 약 {0} 바이트, 상한 {1} 바이트. 먼저 몇 개를 삭제하세요(총 예산은 전문가 설명과 DSH의 64 KB 주입 상한을 공유합니다).',
  '许可未知（请自行确认来源）': '라이선스 알 수 없음(출처를 직접 확인하세요)',
  '许可：{0}': '라이선스: {0}',
  '设为默认': '기본으로 설정',
  '设备凭据已失效，请重新配对': '기기 자격 증명이 만료됐어요. 다시 페어링해 주세요',
  '设置': '설정',
  '设置 → 应用 → 特殊应用权限 → 使用情况访问权限（部分手机叫「有权查看使用情况的应用」）': '설정 → 앱 → 특수 앱 액세스 → 사용 정보 접근(일부 기기는 「사용 정보에 액세스할 수 있는 앱」)',
  '设置 → 应用 → 特殊应用权限 → 修改系统设置': '설정 → 앱 → 특수 앱 액세스 → 시스템 설정 수정',
  '设置 → 应用 → 特殊应用权限 → 安装未知应用 → 本应用 → 允许': '설정 → 앱 → 특수 앱 액세스 → 알 수 없는 앱 설치 → 이 앱 → 허용',
  '设置 → 应用 → 特殊应用权限 → 所有文件访问权限（Android 11 及以上；部分手机在「应用管理 → 本应用 → 权限 → 文件和媒体」里）': '설정 → 앱 → 특수 앱 액세스 → 모든 파일 액세스(Android 11 이상, 일부 기기는 「앱 → 이 앱 → 권한 → 파일 및 미디어」)',
  '设置 → 应用 → 特殊应用权限 → 显示在其他应用上层': '설정 → 앱 → 특수 앱 액세스 → 다른 앱 위에 표시',
  '设置：下载模型 / 启动服务 / 后端 / 知识库 / 联网': '설정: 모델 다운로드 / 서비스 시작 / 백엔드 / 지식 베이스 / 웹 검색',
  '访问敏感凭据': '민감한 자격 증명 접근',
  '证书 SHA-256 指纹': '인증서 SHA-256 지문',
  '试听失败：{0}': '미리 듣기 실패: {0}',
  '试听这一句': '이 문장 미리 듣기',
  '该给的都给了': '필요한 건 다 제공했어요',
  '语言': '언어',
  '语速': '속도',
  '语速中等，节奏稳定。': '보통 속도, 안정된 리듬.',
  '语速放慢一些，吐字清楚，停顿从容。': '조금 느리게, 또렷하게, 여유 있게 끊어서.',
  '语速是发给 MiniMax 的倍率（1.00× 为原速）。音色列表拉不到也不影响用：默认音色照样能配。': '속도는 MiniMax에 보내는 배율입니다(1.00×가 원래 속도). 음성 목록을 가져오지 못해도 사용에는 문제없습니다 — 기본 음성으로도 합성됩니다.',
  '语速稍快一些，节奏紧凑但不含糊。': '조금 빠르게, 리듬은 촘촘하되 불분명하지 않게.',
  '语音识别不可用': '음성 인식을 사용할 수 없어요',
  '语音识别失败：{0}': '음성 인식 실패: {0}',
  '语音输入': '음성 입력',
  '语音输入用不了：这台手机的系统里**没有**任何语音识别服务（可处理识别的应用数={0}）。装一个语音助手类应用后它才会生效；在此之前请用文字输入。': '음성 입력을 쓸 수 없습니다: 이 휴대폰에는 음성 인식 서비스가 **없습니다**(인식을 처리할 수 있는 앱 수={0}). 음성 비서 앱을 설치하면 동작합니다. 그전까지는 문자로 입력해 주세요.',
  '说明：DSH 的运行方式由 overlay 决定 —— 它把模型路由指向你填的端点。这也是为什么换端点必须重新保存一次。': '설명: DSH의 동작 방식은 overlay가 결정합니다 — 모델 라우팅을 입력한 엔드포인트로 향하게 합니다. 그래서 엔드포인트를 바꾸면 반드시 다시 저장해야 합니다.',
  '说明：装进来之后，在下面点「建索引」，这一包才会被检索。建好索引的包，在「本地对话」里提问时会**自动查** —— 把最相关的几段资料（每包最多 2 段、总共最多 3 段）一起发给模型。⚠️ 查到不等于模型一定照它回答；资料没命中时，一句都不会发出去。': '설명: 팩을 설치한 뒤 아래에서 「색인 만들기」를 누르면 그 팩이 검색 대상이 됩니다. 색인을 만든 팩은 「로컬 대화」에서 질문하면 **자동으로 검색**되어, 가장 관련 있는 몇 문단(팩당 최대 2문단, 총 최대 3문단)이 질문과 함께 모델로 전송됩니다. ⚠️ 찾았다고 해서 모델이 그대로 따르는 것은 아닙니다. 하나도 일치하지 않으면 아무것도 전송되지 않습니다.',
  '说话人：{0}（共 {1} 个，试听一下挑一个）': '화자: {0} (총 {1}개, 들어보고 고르세요)',
  '请先填 API Key 再点「测试并保存」—— 安全区里也还没有这一家的 Key。这一家的模型列表与对话都要求鉴权，不带 Key 一律 401。': '「테스트 후 저장」을 누르기 전에 API Key를 입력하세요 — 보안 영역에도 이 서비스의 Key가 없습니다. 이 서비스는 모델 목록과 대화 모두 인증이 필요해 Key 없이는 항상 401입니다.',
  '请填**另一个账号**的 Key —— 同一账号多建几把共享同一份配额，加了也没用。': '**다른 계정**의 Key를 입력하세요 — 같은 계정에서 여러 개를 만들어도 같은 할당량을 공유하므로 소용없습니다.',
  '请帮忙推广一下我的公众号，粉丝太少没有更新动力了': '제 공식 계정 좀 홍보해 주세요. 팔로워가 너무 적어서 업데이트할 의욕이 안 생겨요.',
  '请求 {0} 超时': '{0} 요청 시간이 초과됐어요',
  '请求太频繁或已达额度上限，请稍后重试。': '요청이 너무 잦거나 한도에 도달했어요. 잠시 후 다시 시도하세요.',
  '请求太频繁，被限流了。等几秒到一分钟再试。': '요청이 너무 잦아서 제한됐어요. 몇 초에서 1분 정도 기다렸다가 다시 시도하세요.',
  '请求失败：{0}': '요청 실패: {0}',
  '请求被拒绝（多为模型名写错或参数不被支持）。': '요청이 거부됐어요 (대부분 모델 이름 오타나 지원되지 않는 파라미터 때문이에요).',
  '请求被拒绝，请检查模型名、Base URL 与 Key。': '요청이 거부됐어요. 모델 이름, Base URL, Key를 확인하세요.',
  '请求超时：网络太慢或服务商无响应。检查网络后重试。': '요청 시간이 초과됐어요. 네트워크가 느리거나 제공자가 응답하지 않아요. 네트워크를 확인한 뒤 다시 시도하세요.',
  '请选择记忆的 JSON 文件（.json）。': '기억 JSON 파일(.json)을 선택하세요.',
  '请阅读这个文件：{0}': '이 파일을 읽어 주세요: {0}',
  '读不出这张图的尺寸，去水印用不了（怕把框盖错地方）—— 可以只做美化。': '이 이미지의 크기를 읽을 수 없어 워터마크 제거는 쓸 수 없습니다(상자를 대충 놓지 않습니다). 보정만 가능합니다.',
  '读不到会话历史': '세션 기록을 읽지 못했습니다',
  '读不到当前应用的签名，没法确认新包是不是同一家签的；出于安全，这次不装。': '현재 앱의 서명을 읽을 수 없어 새 패키지가 같은 곳에서 서명되었는지 확인할 수 없습니다. 안전을 위해 이번에는 설치하지 않습니다.',
  '读不到本机内存，先按保守估计': '기기 메모리를 읽을 수 없어 보수적으로 추정합니다.',
  '读取 {0}/schedules.json 失败：{1}': '{0}/schedules.json 읽기 실패: {1}',
  '读取会话列表失败：{0}': '세션 목록을 읽지 못했습니다: {0}',
  '读取失败': '읽기 실패',
  '读取安装包签名时出错了。': '설치 패키지 서명을 읽는 중 오류가 발생했습니다.',
  '读取已保存的设置失败（{0}）。下面显示的是空表单，**不代表你没配过** —— 请先不要重填，把这条报给开发者。': '저장된 설정을 읽지 못했습니다({0}). 아래 폼은 비어 있지만 **설정한 적이 없다는 뜻이 아닙니다**. 우선 다시 입력하지 말고 개발자에게 알려 주세요.',
  '读取开关状态失败：{0}': '토글 상태를 읽지 못했어요: {0}',
  '读取文件': '파일 읽기',
  '读取文件失败：{0}': '파일을 읽지 못했습니다: {0}',
  '读取权限失败：{0}': '권한 확인 실패: {0}',
  '调色、锐化、擦除水印（本机处理，不联网）': '색 보정·선명화·워터마크 지우기(기기 내 처리, 네트워크 불필요)',
  '豆包 Seedance 的分辨率由模型与比例决定，这里不能选。': '더우바오 Seedance의 해상도는 모델과 비율로 결정되므로 여기서 선택할 수 없습니다.',
  '账户余额不足，请先充值。': '계정 잔액이 부족해요. 먼저 충전해 주세요.',
  '资料库': '라이브러리',
  '超时': '시간 초과',
  '超时（{0}s 没响应）': '시간 초과({0}초 무응답)',
  '跟它聊两句（简单对话）': '잠깐 대화해보기(간단한 대화)',
  '跟本机模型说点什么…': '로컬 모델에게 말을 걸어보세요…',
  '跟本机模型说点什么（也可以发图）…': '로컬 모델에게 말을 걸어보세요(이미지도 첨부할 수 있습니다)…',
  '跟随当前会话（推荐）': '현재 세션 따르기(권장)',
  '路径是 /openai/v1（不是 /v1），漏掉 openai 会 404。': '경로는 /openai/v1이에요 (/v1이 아니에요). openai를 빼면 404가 나요.',
  '跳过 {0} 个噪音目录': '노이즈 디렉터리 {0}개 건너뜀',
  '跳过这个版本': '이 버전 건너뛰기',
  '身份': '정체성',
  '轮换池': '로테이션 풀',
  '轮换池 = 把几个模型排成一队：前一个被限流（429）或不可用时，自动换下一个，直到有一个能答。池子本身不存 Key，用的是各厂家各自的 Key。': '로테이션 풀은 여러 모델을 한 줄로 세워 둡니다: 앞의 모델이 제한(429)되거나 사용할 수 없으면 답할 수 있는 모델이 나올 때까지 자동으로 다음을 시도합니다. 풀 자체는 Key를 저장하지 않고 각 서비스의 Key를 씁니다.',
  '轮换池 {0} · 本次用 {1}': '로테이션 {0} · 이번에는 {1} 사용',
  '轮换池 {0}，{1} 个模型，{2}': '로테이션 풀 {0}, 모델 {1}개, {2}',
  '轮换池 · {0} 个成员：{1}': '로테이션 풀 · 멤버 {0}개: {1}',
  '轮换池「{0}」已保存：{1} 个成员按顺序依次尝试': '로테이션 풀 "{0}" 저장됨: 멤버 {1}개를 순서대로 시도해요.',
  '轮换池已保存': '로테이션 풀이 저장됐어요',
  '轮换组 · {0} 个模型': '로테이션 그룹 · 모델 {0}개',
  '轮换组：': '로테이션 그룹:',
  '输入消息…': '메시지 입력…',
  '边界（如实说）': '한계(솔직하게)',
  '运行中 · {0} · 127.0.0.1:{1}': '실행 중 · {0} · 127.0.0.1:{1}',
  '运行中 · 端口 {0} · {1}': '실행 중 · 포트 {0} · {1}',
  '运行内存': '메모리',
  '运行历史': '실행 기록',
  '运行时清单不是合法 JSON。': '실행 환경 매니페스트가 유효한 JSON이 아닙니다.',
  '运行时清单是空的。': '실행 환경 매니페스트가 비어 있습니다.',
  '运行时清单的格式不对：它应该是一个 JSON 对象。': '실행 환경 매니페스트 형식이 잘못되었습니다. JSON 객체여야 합니다.',
  '运行时清单缺少 {0} 字段。': '실행 환경 매니페스트에 {0} 필드가 없습니다.',
  '运行时目录': '런타임 디렉터리',
  '运行环境**随这个安装包自带**（约 32 MB）—— **不需要联网**，直接在本机解开（约 26000 个文件）。这一步只做一次，以后更新不用再下。': '실행 환경이 **이 설치 패키지에 포함**되어 있습니다(약 32MB) — **네트워크가 필요 없으며** 기기에서 풀립니다(약 26,000개 파일). 한 번만 하면 이후 업데이트에서는 반복하지 않습니다.',
  '运行环境（约 32 MB）不在这个安装包里 —— 那样每次更新都要重下它。改成**第一次打开时下这一次**，支持断点续传；下完在本机解开（约 26000 个文件）。这一步只做一次，以后更新不用再下。': '실행 환경(약 32MB)은 이 설치 패키지에 들어 있지 않습니다 — 그래야 업데이트할 때마다 다시 받지 않습니다. 대신 **처음 열 때 한 번** 내려받고(이어받기 지원) 기기에서 풉니다(약 26,000개 파일). 한 번만 하면 이후 업데이트에서는 반복하지 않습니다.',
  '运行记录': '실행 기록',
  '运行记录（对照 game-qa 的验收口径逐项确认）': '실행 기록(game-qa의 인수 기준에 맞춰 항목별로 확인)',
  '运行：{0}': '실행: {0}',
  '返回': '뒤로',
  '返回内容过大（不像一份版本清单）': '응답이 너무 큽니다(버전 정보로 보기 어려움)',
  '还不在任何池子里': '아직 어떤 풀에도 없음',
  '还差一步：系统里要允许本应用「安装未知应用」。点下面的按钮去打开，回来再点「安装」。': '한 단계 남았습니다. 시스템에서 이 앱에 ‘알 수 없는 앱 설치’를 허용해야 합니다. 아래 버튼으로 설정을 열고 돌아와 ‘설치’를 누르세요.',
  '还差模型。最快的一条路：去「设置 → 模型」打开「免费模型（无需 Key）」——不用填任何 Key，打开就能用；想用自己的模型，再填地址和 API Key。': '모델이 없습니다. 가장 빠른 방법: \'설정 → 모델\'에서 \'무료 모델(Key 불필요)\'을 켜세요 — Key 없이 바로 쓸 수 있습니다. 직접 쓰는 모델이 있다면 주소와 API Key를 입력하세요.',
  '还没允许：{0}': '아직 허용되지 않음: {0}',
  '还没建索引 —— 不建就只能看，没法被检索。': '색인이 없습니다. 만들지 않으면 보기만 가능하고 검색은 되지 않습니다.',
  '还没开始对话，正在按新模型准备会话…': '아직 대화를 시작하지 않았습니다. 새 모델로 세션을 준비하는 중…',
  '还没放成员 —— 从下面「所有已注册的模型」里点几个。': '구성원이 아직 없습니다 — 아래 "등록된 모든 모델"에서 몇 개를 선택하세요.',
  '还没有': '아직 없음',
  '还没有 Key？到 {0} 免费注册 → 控制台「API Keys」创建密钥（sk- 开头）→ 粘贴到这里。': 'API 키가 없나요? {0}에서 무료로 가입 → 콘솔의 "API Keys"에서 키(sk-로 시작)를 만들고 → 여기에 붙여넣으세요.',
  '还没有产物': '아직 산출물이 없습니다',
  '还没有任何模型 —— 先去「设置 → 模型」加一个。': '모델이 아직 없습니다 — 먼저 「설정 → 모델」에서 추가하세요.',
  '还没有任何记忆。上面写一条，新建会话后模型就会看到它。也可以往下翻，从最近一次会话里提炼。': '아직 기억이 없습니다. 위에 한 건 작성하면 새 세션에서 모델이 그것을 봅니다. 아래로 내려가 최근 세션에서 추출할 수도 있습니다.',
  '还没有作品': '아직 작품이 없습니다',
  '还没有可恢复的会话。\n点右下角新建一个。': '복원할 수 있는 세션이 없습니다.\n오른쪽 아래를 눌러 새로 만드세요.',
  '还没有可用模型 · 去设置': '사용 가능한 모델 없음 · 설정으로',
  '还没有可用模型。': '아직 사용 가능한 모델이 없습니다.',
  '还没有可用模型。想马上就用：去「设置 → 模型」打开「免费模型（无需 Key）」，不用填 Key 也不花钱；想用自己的模型（DeepSeek / Agnes 等），再填地址和 API Key 点「测试并保存」。': '사용할 수 있는 모델이 아직 없습니다. 바로 쓰려면: \'설정 → 모델\'에서 \'무료 모델(Key 불필요)\'을 켜세요 — Key도 비용도 없습니다. 직접 쓰는 모델(DeepSeek / Agnes 등)을 쓰려면 주소와 API Key를 입력하고 \'테스트 후 저장\'을 누르세요.',
  '还没有可用模型，去设置': '사용 가능한 모델이 없습니다. 설정으로',
  '还没有可用的云端模型：请先在「设置 → 模型」里配好一个（填 Key 并保存）。': '사용할 수 있는 클라우드 모델이 없습니다. 설정 → 모델에서 하나 설정하세요(Key 입력 후 저장).',
  '还没有可用的模型': '사용 가능한 모델이 없습니다',
  '还没有开启任何专家': '활성화된 전문가가 아직 없습니다',
  '还没有开启任何专家；开启后会在会话的「专家中心」里出现': '활성화된 전문가가 아직 없습니다. 활성화하면 세션의 "전문가 센터"에 표시됩니다',
  '还没有执行记录。': '아직 실행 기록이 없습니다.',
  '还没有装任何知识库：可以下载下面列出的，或从手机导入。': '아직 설치된 지식 베이스가 없습니다. 아래에서 다운로드하거나 휴대폰에서 가져오세요.',
  '还没有装知识库。知识库是给本地模型查的离线资料：不联网、不花额度。': '아직 설치된 지식 베이스가 없습니다. 로컬 모델이 찾아보는 오프라인 자료로, 네트워크와 과금이 필요 없습니다.',
  '还没有轮换池。': '아직 로테이션 풀이 없습니다.',
  '还没有配置模型': '구성된 모델이 없습니다',
  '还没测过': '측정 기록 없음',
  '还没装模型：要下 **31.5 MB**（装好后占约 32 MB），下完自动解包。': '모델이 아직 없습니다: **31.5 MB**를 내려받습니다 (설치 후 약 32 MB). 완료되면 자동으로 압축을 풉니다.',
  '还没选图。可以从相册选，也可以直接用「作品」里已经生成的那张。': '아직 사진을 고르지 않았습니다. 앨범에서 고르거나 「작품」에 있는 생성된 이미지를 그대로 쓸 수 있습니다.',
  '还没选文件。点下面「从资料库选」—— 只列工作区里的视频。': '아직 파일을 고르지 않았습니다. 아래 "라이브러리에서 선택"을 누르세요 — 워크스페이스의 영상만 표시됩니다.',
  '还没配 Key —— 没凭据这条模型必然失败': 'Key 미설정 — 자격 증명이 없으면 이 모델은 반드시 실패합니다',
  '这 5 项不是普通权限：Android 不允许应用自己开，也没有「应用内开关」—— 只能在系统的「特殊应用权限」页里拨。下面写清每一项是干嘛的。': '이 5가지는 일반 권한이 아닙니다: Android는 앱이 스스로 부여할 수 없게 하고, 앱 내 스위치도 없습니다 — 시스템의 「특수 앱 액세스」 페이지에서만 켤 수 있습니다. 아래에 각 항목의 용도를 적었습니다.',
  '这一条**没有配音**': '이 결과물에는 **더빙이 없습니다**',
  '这一条太长了（上限 {0} 字节，约 600 多个汉字）': '이 항목이 너무 깁니다(상한 {0} 바이트, 한자 약 600자 남짓)',
  '这一项已经不在配置里了，请重新选择。': '이 항목은 더 이상 설정에 없습니다. 다시 선택해 주세요.',
  '这七个技能来自 NovelToGame v0.4.0（MIT 许可），只改写了简介并加了署名，正文与参考文件保持原样。': '이 일곱 스킬은 NovelToGame v0.4.0(MIT 라이선스)에서 가져왔습니다. 소개 문구만 다시 쓰고 출처 표기를 추가했으며, 본문과 참조 파일은 그대로입니다.',
  '这三个就是设置里那几个模型（文本模型 = 首页新会话用的那个；图形/视频 = 「设置 → 图像 / 视频模型」），在这儿改等于在设置里改 —— 创作台生成时会**直接用**这里选的。': '이 세 가지는 설정에 있는 것과 같습니다 (텍스트 모델 = 새 대화에서 쓰는 것, 이미지/동영상 = 설정 → 이미지 / 동영상 모델). 여기서 바꾸는 것은 설정에서 바꾸는 것과 같고, 스튜디오 생성은 여기서 고른 것을 사용합니다.',
  '这不像一个完整网址：要以 http:// 或 https:// 开头。': '완전한 URL이 아닌 것 같습니다. http:// 또는 https://로 시작해야 합니다.',
  '这两颗按钮跟手机档次无关 —— 同一份模型，只是换「谁来算」：CPU 是通用的，慢一点但稳；GPU 用图形芯片加速，通常快好几倍，但**部分机型在长对话时会把引擎干崩**（真机上遇到过，崩了就会报连不上）。所以默认给了 CPU；想快就切 GPU 试 —— 万一崩，下次启动会自动换回 CPU。': '이 두 버튼은 휴대폰 등급과 무관합니다. 같은 모델에서 「누가 계산할지」만 고르는 것입니다. CPU는 범용이라 조금 느리지만 안정적이고, GPU는 그래픽 칩으로 계산해 보통 몇 배 빠르지만 **일부 기기에서는 긴 대화에서 엔진이 다운됩니다**(실기기에서 발생. 다운되면 연결 오류만 보입니다). 그래서 기본값은 CPU입니다. 속도를 원하면 GPU로 바꿔 보세요 —— 만약 다운되면 다음 시작 때 자동으로 CPU로 돌아갑니다.',
  '这个 Android 版本不需要': '이 Android 버전에서는 필요하지 않습니다',
  '这个包与当前应用的**签名不一致**，不能覆盖安装 —— 它可能不是同一个来源发的。如果你确实换了签名钥匙，唯一的办法是卸载重装（数据会丢）。': '이 패키지는 **서명이 현재 앱과 일치하지 않아** 덮어 설치할 수 없습니다 — 같은 곳에서 배포된 것이 아닐 수 있습니다. 실제로 서명 키를 바꾸셨다면 삭제 후 다시 설치하는 방법밖에 없습니다(데이터가 사라집니다).',
  '这个包大得不像话（超过 {0}），已经停下不下了。': '이 패키지가 너무 큽니다({0} 초과). 다운로드를 중단했습니다.',
  '这个名字只是本 App 的显示名 —— ACP 协议没有改名功能，DSH 那边这条会话不受影响。留空保存 = 恢复成默认显示。': '이 이름은 이 앱의 표시 이름일 뿐입니다 — ACP 프로토콜에는 이름 변경 기능이 없어 DSH 쪽 세션에는 영향이 없습니다. 비운 채로 저장하면 기본 표시 이름으로 돌아갑니다.',
  '这个安装包里没有签名 —— 正规发布的包一定有签名，所以不装它。': '이 설치 패키지에는 서명이 없습니다 — 정식 배포된 패키지에는 반드시 서명이 있으므로 설치하지 않습니다.',
  '这个文件 App 内放不出来': '이 파일은 앱 안에서 재생되지 않습니다',
  '这个文件不是一个能识别的安装包。': '이 파일은 인식할 수 있는 설치 패키지가 아닙니다.',
  '这个文件夹在 App 私有目录里，其它应用读不到；「分享」或「复制路径」都能把它交出去。': '이 폴더는 앱 전용 디렉터리에 있어 다른 앱에서 읽을 수 없습니다. "공유" 또는 "경로 복사"로 넘길 수 있습니다.',
  '这个文件看起来是二进制': '이 파일은 바이너리로 보입니다',
  '这个格式 App 内不能预览': '이 형식은 앱에서 미리 볼 수 없습니다',
  '这个模型在你所在地区不可用（不是 Key 的问题）。': '이 모델은 현재 지역에서 사용할 수 없습니다 (Key 문제가 아닙니다).',
  '这个模型在清单里没有任何下载源': '이 모델은 목록에 다운로드 소스가 없습니다',
  '这个模型在该端点上不存在。请点「获取模型」重新选。': '이 모델은 해당 엔드포인트에 없습니다. "모델 가져오기"를 눌러 다시 선택하세요.',
  '这个模型文件只带 {0} 格缓存，上下文已收敛到 {0} 格（你设的是 {1}）—— 它的上下文上限就是那么多，装不下更长的对话': '이 모델 파일은 캐시가 {0}칸뿐이라 컨텍스트를 {0}으로 좁혔습니다(설정은 {1}) — 이것이 상한이고, 더 긴 대화는 들어가지 않습니다.',
  '这个模型没有在 DSH 的路由里注册。\n下一步：回「设置 → 模型」把默认模型重新点一次（这会让 App 重写配置），或者到会话里用模型按钮重新选一次。': '이 모델은 DSH 라우팅에 등록되어 있지 않습니다.\n다음 단계: "설정 → 모델"로 돌아가 기본 모델을 다시 한 번 탭하거나(앱이 설정을 다시 작성합니다), 세션에서 모델 버튼으로 다시 선택하세요.',
  '这个模型没法在当前会话里直接切，正在重建会话…': '이 모델은 현재 세션에서 바로 전환할 수 없습니다. 세션을 다시 만드는 중…',
  '这个模型的对话缓存装不下了：它的上下文上限是 {0} token，当前这段对话已经接近上限。请点右上角新开一个会话，或换一个上下文更大的模型。': '이 모델의 대화 캐시가 가득 찼습니다: 컨텍스트 상한이 {0} 토큰이고 현재 대화가 이미 상한에 가깝습니다. 오른쪽 위에서 새 세션을 시작하거나, 컨텍스트가 더 큰 모델로 바꾸세요.',
  '这个池子一个成员都没有 —— 在模型面板里选中它会直接失败，建议放进一两个模型或删掉它。': '이 풀에는 구성원이 하나도 없습니다 — 모델 패널에서 선택하면 바로 실패합니다. 모델을 한두 개 넣거나 삭제하세요.',
  '这个池子里的模型所在厂家都还没配 API Key —— 现在选中它，发言时必然失败。去「设置 → 模型 → 我的模型」给其中至少一家填 Key。': '이 풀에 있는 모델의 서비스는 모두 API Key가 설정되지 않았습니다 — 지금 선택하면 발언할 때 반드시 실패합니다. 「설정 → 모델 → 내 모델」에서 최소 한 곳에 Key를 입력하세요.',
  '这个账号下没有可用的系统音色。': '이 계정에는 사용할 수 있는 시스템 음성이 없습니다.',
  '这些是什么意思？': '이것들은 무슨 뜻인가요?',
  '这些说明是随 App 版本一起发出来的文字记录（离线存在安装包里）；App 不会联网检查新版本，也不会提示你升级。': '이 설명은 앱 버전과 함께 배포되는 기록입니다(설치 패키지 안에 오프라인 저장). 앱은 새 버전을 온라인으로 확인하지 않고 업그레이드도 안내하지 않습니다.',
  '这份日志是为了让开发者看出"运行中哪里出错了"。它会包含：': '이 로그는 개발자가 "실행 중 어디서 문제가 생겼는지" 확인하기 위한 것입니다. 포함 내용:',
  '这份是本地缓存的公告，还没有和远端对上时间': '로컬에 캐시된 공지이며, 아직 원격과 시간을 맞추지 않았습니다.',
  '这会删掉所有记忆条目，并从 AGENTS.md 里移除它们。不可恢复。': '모든 기억 항목을 삭제하고 AGENTS.md에서도 제거합니다. 되돌릴 수 없습니다.',
  '这台手机没有可接收分享的应用（系统返回 {0}）。': '이 휴대폰에는 공유를 받을 수 있는 앱이 없습니다(시스템 반환 {0}).',
  '这台手机没有可用的「保存文件」界面（系统返回 {0}）。': '이 휴대폰에는 사용할 수 있는 "파일 저장" 화면이 없습니다(시스템 반환 {0}).',
  '这台手机没有可用的「文字转语音」引擎（系统里一个都没装）。两条路：① 到「系统设置 → 语言与输入 → 文字转语音」装一个引擎并下载中文语音包；② 改用 MiMo 或 MiniMax 配音 —— 在「设置 → 云端大模型 → MiMo / MiniMax」里填一个 API Key 即可。': '이 기기에는 사용할 수 있는 「음성 합성」 엔진이 없습니다 (하나도 설치되어 있지 않습니다). 두 가지 방법: ① 「시스템 설정 → 언어 및 입력 → 텍스트 음성 변환」에서 엔진을 설치하고 중국어 음성 데이터를 내려받기; ② MiMo 또는 MiniMax 음성 합성으로 전환 — 「설정 → 클라우드 모델 → MiMo / MiniMax」에서 API Key를 넣으면 됩니다.',
  '这台手机没有语音引擎？改用 MiMo（需 Key）': '이 기기에 음성 엔진이 없나요? MiMo로 전환 (Key 필요)',
  '这台手机没装中文语音数据。请到「系统设置 → 语言与输入 → 文字转语音」里下载中文语音包；或者改用 MiMo 配音（需要 Key）。': '중국어 음성 데이터가 설치되어 있지 않습니다. 시스템 설정 → 언어 및 입력 → 텍스트 음성 변환에서 다운로드하거나 MiMo 음성(Key 필요)으로 바꾸세요.',
  '这台手机（或这个 Android 版本）里没有「{0}」的设置页 —— 国产 ROM 常把入口改名、藏起来或整个删掉。手动找：{1}': '이 휴대폰(또는 이 Android 버전)에는 「{0}」 설정 페이지가 없습니다 — 중국계 ROM은 입구 이름을 바꾸거나 숨기거나 아예 삭제합니다. 직접 열기: {1}',
  '这台设备上找不到能处理安装的应用（一般是定制系统裁掉了安装器），装不了。': '이 기기에는 설치를 처리할 앱이 없습니다(커스텀 ROM에서 설치 프로그램이 제거된 경우가 있습니다). 설치할 수 없습니다.',
  '这台设备上没有可以提炼的会话。': '이 기기에는 추출할 세션이 없습니다.',
  '这台设备上没有可用的语音识别服务': '이 기기에서 사용할 수 있는 음성 인식 서비스가 없습니다',
  '这台设备没有能打开网页的应用，请手动访问：{0}': '이 기기에는 웹 페이지를 열 수 있는 앱이 없습니다. 직접 방문해 주세요: {0}',
  '这台设备没有能接收分享的应用': '이 기기에는 공유를 받을 수 있는 앱이 없습니다',
  '这台设备的名字': '이 기기의 이름',
  '这家在本 App 里没接图像：点上面的「换一个」选一家支持图像的厂家。': '이 공급사의 이미지는 이 앱에 연결되어 있지 않습니다: 위의 「변경」을 눌러 이미지를 지원하는 공급사를 선택하세요.',
  '这家在本 App 里没接视频：点上面的「换一个」选一家支持视频的厂家（Agnes / 豆包 Seedance / MiniMax / 通义万相 / 硅基流动）。': '이 공급사의 동영상은 이 앱에 연결되어 있지 않습니다: 위의 「변경」을 눌러 동영상을 지원하는 공급사(Agnes / 더우바오 Seedance / MiniMax / 通義万相 / SiliconFlow)를 선택하세요.',
  '这家没有内置的注册地址 —— 去它的官网申请 Key 就行。': '이 제공자는 기본 등록 주소가 없습니다 — 공식 사이트에서 Key를 받으면 됩니다.',
  '这家还没配 Key': '이 제공자는 아직 Key가 없습니다',
  '这就是当前那把主 Key，不用再加一遍': '그것은 현재 기본 Key입니다. 다시 추가할 필요가 없습니다',
  '这张图打不开（Flutter 解码失败）：{0}\n\n{1}': '이 이미지를 열 수 없습니다(Flutter 디코딩 실패): {0}\n\n{1}',
  '这张图读不到了（可能刚被删除或移动），换一张试试。': '이 이미지를 더 이상 읽을 수 없습니다(방금 삭제되거나 이동되었을 수 있습니다). 다른 이미지를 시도하세요.',
  '这把 Key 已经在列表里了': '그 Key는 이미 목록에 있습니다',
  '这是什么': '무엇인가',
  '这是按消息长度**估算**的（ACP 目前不把真实用量推给 App），只看趋势别看小数。\n换窗三步：① 生成交接笔记 → ② 发出去 → ③ 新建一个会话继续。': '이것은 메시지 길이로부터의 **추정치**입니다(ACP는 아직 실제 사용량을 앱에 전달하지 않습니다). 소수점이 아니라 추세만 보세요.\n새 창으로 가는 세 단계: ① 인수인계 노트 생성 → ② 전송 → ③ 새 세션을 만들어 계속하기.',
  '这条会话在磁盘上没有可回放的消息。': '이 세션에는 디스크에 재생할 수 있는 메시지가 없습니다.',
  '这条会话没能恢复': '이 세션을 복원하지 못했습니다',
  '这条会话的记录没读出来 —— 会话文件可能已经不在了。你可以换一条，或者自己手写一条。': '이 세션의 기록을 읽지 못했습니다 — 세션 파일이 사라졌을 수 있습니다. 다른 세션을 고르거나 직접 한 건 작성하세요.',
  '这条会话里没有可提炼的对话内容（没有用户或助手的消息）。': '이 세션에는 추출할 대화 내용이 없습니다(사용자 또는 어시스턴트 메시지가 없습니다).',
  '这条回答顶到了长度上限、被截断了（不是答完）。可以再发一句「继续」，或者把问题拆小一点再问。': '이 답변은 길이 상한에 도달해 잘렸습니다(끝까지 답한 것이 아닙니다). "계속"이라고 보내거나 질문을 나눠서 물어보세요.',
  '这条是好的。': '이 채널은 정상입니다.',
  '这条模型的清单里没有 sha256，而清单要求必须校验哈希，已拒绝安装：{0}': '이 모델의 목록에 sha256이 없는데 목록이 해시 검증을 요구합니다. 설치를 거부했습니다: {0}',
  '这条没能发出去：会话没能建起来，可以再试一次。': '이 메시지는 전송되지 않았습니다. 세션을 만들지 못했습니다. 다시 시도해 주세요.',
  '这条没能回上来。可以再发一次；若反复如此，去「设置 → 运行日志」看细节。': '이 응답을 받지 못했습니다. 다시 보내 보세요. 반복되면 "설정 → 실행 로그"에서 세부정보를 확인하세요.',
  '这条通道现在是通的，不用填 Key。模型清单随时会变，以「获取模型」拉到的那份为准。': '이 채널은 지금 연결됩니다(Key 불필요). 모델 목록은 수시로 바뀌니 「모델 가져오기」로 받은 목록을 기준으로 하세요.',
  '这条通道用不了的时候才需要它：点一次自检，它会告诉你到底是哪种问题（网络不通 / 被上游拒绝 / 模型名退役 / Key 失效 / 限流），并可以把结论一键发给开发者。': '이 채널이 안 될 때만 필요합니다: 자체 점검을 한 번 실행하면 어떤 종류의 문제인지(네트워크 불통 / 상류 거부 / 모델명 폐기 / Key 무효 / 속도 제한) 알려주고, 결과를 한 번에 개발자에게 보낼 수 있습니다.',
  '这次下的是**完整包**（含运行环境）—— 因为这台手机上还没有，这样装完就能直接打开、不需要联网再补。': '이번에 내려받는 것은 **전체 패키지**(실행 환경 포함)입니다 — 이 기기에 아직 없기 때문에, 설치 후 바로 열 수 있고 추가 다운로드가 필요 없습니다.',
  '这次下的是**精简包**（不含运行环境）—— 这台手机上已经有了，所以能省下那份流量。': '이번에 내려받는 것은 **경량 패키지**(실행 환경 미포함)입니다 — 이 기기에 이미 있으므로 그만큼 데이터를 절약합니다.',
  '这次不提示': '이번엔 표시 안 함',
  '这次创作台用哪三个模型': '이번 스튜디오에서 사용할 세 가지 모델',
  '这次没有提炼出值得长期记住的内容 —— 这不代表失败，只是这段对话里没有跨会话有用的事实。你也可以自己手写一条。': '이번에는 장기적으로 기억할 만한 내용이 나오지 않았습니다 — 실패가 아니라 이 대화에 세션을 넘어 유용한 사실이 없었다는 뜻입니다. 직접 한 건 작성할 수도 있습니다.',
  '这次用哪三个模型': '이번에 사용할 세 가지 모델',
  '这段会话的上下文已经用掉约 {0}（估算）。用「长会话助手」可以把关键信息跟着带到新窗口，接着聊不会断。': '이 세션은 컨텍스트를 약 {0} 사용했습니다(추정). \'긴 세션 도우미\'를 쓰면 핵심 내용을 새 창으로 가져가 대화를 끊김 없이 이어갈 수 있습니다.',
  '这段话就是引擎的原话，没加工 —— 发我这份就能直接定位。': '이 문장은 엔진의 원문 그대로입니다. 보내주시면 원인을 바로 찾을 수 있습니다.',
  '这版引擎没编 Vulkan，只有 CPU 后端': '이 엔진 빌드에는 Vulkan이 없습니다(CPU 전용)',
  '这类错误通常过一会儿重试就好。': '이런 오류는 보통 잠시 후 다시 시도하면 해결됩니다.',
  '这里写的话会进 AGENTS.md，DSH 在**每个新会话的第一个请求前**把它注入模型上下文 —— 与「专家」开关同一条通道。**对已经打开的会话不生效**，要新建一个会话。': '여기에 쓴 내용은 AGENTS.md에 들어가고, DSH가 **새 세션의 첫 요청 전에** 모델 컨텍스트에 주입합니다 — 「전문가」 스위치와 같은 경로입니다. **이미 열려 있는 세션에는 적용되지 않습니다** — 새 세션을 만드세요.',
  '这里只显示你在「专家」页打开开关的专家；它们的角色摘要已写入下面这个文件，DSH 会在新会话的第一个请求前注入模型上下文。': '여기에는 「전문가」 페이지에서 켠 전문가만 표시합니다. 그 역할 요약은 아래 파일에 기록되고, DSH가 새 세션의 첫 요청 전에 모델 컨텍스트에 주입합니다.',
  '这里汇集了**所有生成过的图片和视频**：「影视」页生成的、以及会话里生成的一起收在这里，不用记是谁生成的。': '여기에는 **생성한 모든 이미지와 동영상**이 모입니다 — 영상 페이지에서 만든 것과 대화에서 만든 것을 함께 모아 두니, 어디서 만들었는지 기억하지 않아도 됩니다.',
  '这里汇集了所有生成过的图片和视频': '생성한 이미지와 영상이 여기에 모입니다',
  '进行中': '진행 중',
  '远程代码执行': '원격 코드 실행',
  '连上了代理，但没取到任何免费模型 —— 上游那条通道可能暂时不可用。': '프록시에는 연결했지만 무료 모델을 받지 못했습니다 — 업스트림 채널이 일시적으로 불가능할 수 있습니다.',
  '连不上': '연결할 수 없음',
  '连不上模型端点。\n可能是：手机网络不通、Base URL 写错，或者你在用「轮换组」而本地代理没起来（回设置页切一下模型就会重新起）；如果你用的是本机模型，多半是引擎刚崩了或被系统回收了 —— 去「设置 → 本地大模型（测试）」重新点一次「启动」。改完重发一次即可。': '모델 엔드포인트에 연결할 수 없습니다.\n가능한 원인: 휴대폰 네트워크 불통, Base URL 오타, 또는 로테이션 풀을 쓰는데 로컬 프록시가 떠 있지 않음(설정 화면에서 모델을 한 번 바꾸면 다시 뜹니다). 온디바이스 모델이라면 엔진이 방금 죽었거나 시스템에 회수된 경우가 많습니다. 「설정 → 로컬 대형 모델(테스트)」에서 「시작」을 다시 눌러 주세요. 고친 뒤 한 번 더 보내면 됩니다.',
  '连不上（网络）': '연결 실패(네트워크)',
  '连不上：{0}': '연결 실패: {0}',
  '连接 DSH': 'DSH 연결',
  '连接 {0}{1}': '{0}{1} 연결',
  '连接中…': '연결 중…',
  '连接失败': '연결 실패',
  '连接失败：{0}': '연결 실패: {0}',
  '连接已关闭': '연결이 닫혔습니다',
  '连接已断开': '연결이 끊어졌습니다',
  '连接日志': '연결 로그',
  '连接被拒绝：桥未启动或端口不对。': '연결이 거부되었습니다: 브리지가 실행되지 않았거나 포트가 잘못되었습니다.',
  '连接超时：请确认桥在运行、地址端口正确、手机与电脑在同一网络。': '연결 시간 초과: 브리지가 실행 중인지, 주소와 포트가 올바른지, 휴대폰과 컴퓨터가 같은 네트워크에 있는지 확인하세요.',
  '连接错误：{0}': '연결 오류: {0}',
  '连通性测试通过（{0}ms）。已把「{1}」的 {2} 个模型登记进来，会话的模型面板里现在就能选。': '연결 테스트 통과({0}ms). "{1}"의 모델 {2}개를 등록했습니다. 이제 세션의 모델 패널에서 바로 선택할 수 있습니다.',
  '连通性测试通过（{0}ms）。已登记 {1} 个模型，会话里现在能选。': '연결 테스트 통과({0}ms). 모델 {1}개를 등록했습니다. 이제 세션에서 선택할 수 있습니다.',
  '适合老花/小屏': '노안/작은 화면에 적합',
  '选「保存图片/视频」即可存进相册': '\'이미지/동영상 저장\'을 선택하면 갤러리에 저장됩니다',
  '选一个功能开始。做完点左上角就能回到这里。': '기능을 하나 선택하세요. 끝나면 왼쪽 위 화살표로 여기로 돌아옵니다.',
  '选一个视频': '영상 하나 선택',
  '选一刀': '작업 고르기',
  '选一张图': '이미지 선택',
  '选一张开局牌': '시작 카드 한 장 고르기',
  '选了「仅当前工作区」但没有工作目录路径 —— 这条记忆不知道该在哪儿生效。': '\'현재 작업 공간만\'을 선택했지만 작업 디렉터리 경로가 없습니다 — 이 기억은 적용될 곳이 없습니다.',
  '选图失败：{0}': '이미지 선택 실패: {0}',
  '选择一条会话': '세션 선택',
  '选择壁纸': '배경화면 선택',
  '选择失败': '선택 실패',
  '选择失败：{0}': '선택 실패: {0}',
  '选择文件': '파일 선택',
  '选择文件失败：{0}': '파일을 선택하지 못했습니다: {0}',
  '选择模型': '모델 선택',
  '选要拼的视频（按顺序）': '이어 붙일 영상 선택(순서대로)',
